int compress_run_length(char *buffer, size_t length) {
    int count = 1;
    size_t i = 1;
    while (i < length) {
        if (buffer[i] != buffer[i - 1]) {
            buffer[count++] = buffer[i];
        }
        i++;
    }
    buffer[count] = '\0';
    return count;
}

void write_to_file(const char *filename, const char *data) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        log_error("Error writing to file.");
        return;
    }
    fprintf(file, "%s", data);
    fclose(file);
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = "output.txt";
    bool compress = false;
    bool skip_comments = false;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"compress", no_argument, 0, 'c'},
        {"skip-comments", no_argument, 0, 's'},
        {"output", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    while (true) {
        int c = getopt_long(argc, argv, "hcso:", long_options, &option_index);
        if (c == -1)
            break;

        switch (c) {
            case 'h':
                printf("Usage:\n%s [options] input_file\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'c':
                compress = true;
                break;
            case 's':
                skip_comments = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                log_error("Invalid option.");
                exit(EXIT_FAILURE);
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    } else {
        printf("Error: No input file specified.\n");
        printf("%s --help for more information.\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *input = fopen(input_file, "r");
    if (!input) {
        log_error("Error opening input file.");
        exit(EXIT_FAILURE);
    }

    int line_count = 0;
    char line[4096];
    while (fgets(line, sizeof(line), input)) {
        if (!skip_comments && is_comment(line)) continue;
        line[strcspn(line, "\n")] = '\0'; // Remove newline character
        if (compress) {
            char compressed[strlen(line) + 16]; // Account for run-length encoding overhead
            int length = compress_run_length(line, strlen(line));
            strcpy(compressed, &line[0]);
            strcat(compressed, "_");
            strcat(compressed, itoa(length));
            write_to_file("output_compressed.txt", compressed);
        } else {
            write_to_file(output_file, line);
        }
        line_count++;
    }

    fclose(input);

    if (compress) {
        char command[128]; // Command to replace the original file with the compressed one
        snprintf(command, sizeof(command), "mv output_compressed.txt %s", input_file);
        system(command);
    }

    if (output_file != "output.txt") {
        char command[128]; // Command to rename the output file back to its original name
        snprintf(command, sizeof(command), "mv %s %s", output_file, input_file);
        system(command);
    }

    return EXIT_SUCCESS;
}
