#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t size;
} IntArray;

IntArray create_int_array(size_t capacity) {
    IntArray array = {malloc(capacity * sizeof(int)), capacity, 0};
    if (!array.data) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

void resize_if_needed(IntArray* array, size_t new_capacity) {
    if (new_capacity > array->capacity && array->data) {
        array->data = realloc(array->data, new_capacity * sizeof(int));
        if (!array->data) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        array->capacity = new_capacity;
    }
}

void destroy_int_array(IntArray* array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
}

int read_integer(FILE* file) {
    char buffer[12];
    int result;

    if (fscanf(file, "%11d", &result) != 1 || result < -1000000 || result > 1000000) {
        return -1;
    }

    return result;
}

IntArray read_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    IntArray array = create_int_array(10000);
    size_t current_capacity = array.capacity;
    int value;

    while ((value = read_integer(file)) != -1 && array.size < current_capacity) {
        array.data[array.size++] = value;
    }

    fclose(file);

    if (array.size > 0) {
        resize_if_needed(&array, array.size);
    } else {
        destroy_int_array(&array);
        fprintf(stderr, "No valid integers were entered\n");
        exit(EXIT_FAILURE);
    }

    return array;
}

void print_largest(const IntArray* array) {
    int largest = INT_MIN;

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
}

void process_file(const char* filename) {
    IntArray array = read_from_file(filename);
    print_largest(&array);
    destroy_int_array(&array);
}
```

