[" Here is a C++ function named `insertUniqueElement` that meets your requirements:

```cpp
#include <vector>
#include <unordered_set>
#include <algorithm>
#include <iterator>
#include <cassert>
#include <mutex>

void insertUniqueElement(std::vector<int>& vec, size_t insertIndex, size_t duplicateCheckIndex, int elementToInsert) {
    std::unordered_set<int> uniqueSet;
    for (const auto& elem : vec) {
        if (uniqueSet.count(elem)) {
            uniqueSet.erase(elem);
            vec.erase(std::remove(vec.begin(), vec.end(), elem), vec.end());
        } else {
            uniqueSet.insert(elem);
        }
    }

    std::mutex mtx;
    auto it = vec.begin();
    std::advance(it, static_cast<difference_t>(duplicateCheckIndex));

    if (it != vec.end() && *it != elementToInsert) {
        mtx.lock();
        it = vec.insert(it, elementToInsert);
        mtx.unlock();
    } else if (it != vec.end()) {
        ++it;
    }

    if (insertIndex >= vec.size()) {
        vec.push_back(elementToInsert);
    } else {
        mtx.lock();
        std::copy_backward(it, vec.end(), vec.end());
        vec.insert(it, elementToInsert);
        mtx.unlock();
    }
}
```

This function first removes any duplicate elements from the vector and stores them in an unordered set for efficient lookup. It then checks if `duplicateCheckIndex` is within bounds and if the element at that index matches `elementToInsert`. If not, it locks a mutex to ensure thread safety during insertion and performs the appropriate insertion or appending based on the given indices. Finally, it handles potential race conditions by using a mutex when modifying the vector's contents."]

