[' Here's a C# function that meets your requirements:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Win32;

public string GetConfigValue(string nodeName, string configPrefix = "app")
{
    string baseDir = DetermineBaseDirectory();
    string configFilePath = Path.Combine(baseDir, $"{configPrefix}.config.xml");

    if (!File.Exists(configFilePath))
    {
        Console.WriteLine($"Error: Configuration file '{configFilePath}' not found.");
        return null;
    }

    XmlDocument configDoc = new XmlDocument();
    configDoc.Load(configFilePath);

    XPathNavigator navigator = configDoc.CreateNavigator();
    var nodes = navigator.Select("/configuration/appSettings/add[@key='{nodeName}']");

    if (nodes.Count == 0)
    {
        Console.WriteLine($"Error: Node '{nodeName}' not found in the configuration file.");
        return null;
    }

    XPathNavigator node = nodes[0].Clone();
    string value = node.SelectSingleNode("./value").Value;

    if (string.IsNullOrWhiteSpace(value))
    {
        Console.WriteLine($"Error: Invalid data for node '{nodeName}'.");
        return null;
    }

    return value;
}

private string DetermineBaseDirectory()
{
    string baseDir = null;

    if (Environment.GetEnvironmentVariable("BASE_DIR") != null)
    {
        baseDir = Environment.GetEnvironmentVariable("BASE_DIR");
    }
    else
    {
        var currentDir = Directory.GetCurrentDirectory();
        baseDir = Path.Combine(currentDir, "..", ".."); // Go up two levels from the current directory
    }

    if (!Directory.Exists(baseDir))
    {
        Console.WriteLine("Error: Base directory does not exist.");
        throw new DirectoryNotFoundException($"Base directory '{baseDir}' not found.");
    }

    return baseDir;
}
```

This function first determines the application's base directory and constructs the path to the configuration file. It then loads the XML document, selects the specified node using XPath, and returns its value if it exists and is valid. If any errors occur during the process, informative messages are displayed, and exceptions may be thrown as needed.

The function uses performance optimizations by loading the entire XML document into memory only once and selecting nodes using XPath expressions. It can easily be extended to support additional node types by modifying the XPath expression used in the `nodes` variable declaration.']

