        <scope>runtime</scope>
    </dependency>
</dependencies>
```

Next, create a configuration class for Kafka and Ehcache:

```java
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.ConsumerFactory;
import org.springframework.kafka.core.DefaultKafkaConsumerFactory;
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer;
import net.sf.ehcache.*;

@Configuration
public class AppConfig {
    @Bean
    public CacheManager cacheManager() {
        EhCacheManagerFactoryBean factory = new EhCacheManagerFactoryBean();
        factory.setConfigLocation(new ClassPathResource("ehcache.xml"));
        return factory.getObject();
    }

    @Bean
    public ConsumerFactory<String, String> consumerFactory() {
        Map<String, Object> configProps = new HashMap<>();
        configProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        return new DefaultKafkaConsumerFactory<>(configProps, new StringDeserializer(), new StringDeserializer());
    }

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, String> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<String, String> factory = new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        return factory;
    }
}
```

Create a Kafka listener:

```java
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Service;

@Service
public class MessageProcessor {
    private final Cache<String, String> cache;
    private final Pattern exclusionPattern;

    public MessageProcessor(CacheManager cacheManager, String exclusionPattern) {
        this.cache = cacheManager.getCache("messageCache", String.class, String.class);
        this.exclusionPattern = Pattern.compile(exclusionPattern);
    }

    @KafkaListener(topics = "messages")
    public void processMessage(String message) {
        if (message == null || exclusionPattern.matcher(message).matches()) return;

        String hash = MD5.create().hashStr(message);
        cache.put(message, hash);
    }
}
```

Finally, create an `ehcache.xml` configuration file for Ehcache:

```xml
<config xmlns='http://www.ehcache.org/v3/config' xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' xsi:xsi='http://www.w3.org/2001/XMLSchema-instance'>
    <diskStore path='java.io.tmpdir'/>
    <cache name='messageCache' eternal='false' maxElementsInMemory='10000' overflowToDisk='true'>
        <expiry>
            <policy factory='org.ehcache.core.common.DefaultExpiryPolicy'>
                <timeUnitSeconds>60</timeUnitSeconds>
            </policy>
        </expiry>
    </cache>
</config>
```']

