                $this->logger->warning('Database error: ' . $e->getMessage());
                $this->db = null; // Close and recreate the connection to try again
                $this->maxRetries--;
                return $this->handleRequest();
            } else {
                $this->logger->error('Database error: ' . $e->getMessage());
                return json_encode(['message' => 'error', 'data' => []]);
            }
        }

