using Microsoft.EntityFrameworkCore;
using StackExchange.Redis;
using Newtonsoft.Json;

public class PageUpdaterService
{
    private readonly AppDbContext _context;
    private readonly IDatabase _redisDatabase;

    public PageUpdaterService(AppDbContext context, IConnectionMultiplexer redis)
    {
        _context = context;
        _redisDatabase = redis.GetDatabase();
    }

    public async Task UpdatePageAsync(HttpContext context)
    {
        var input = await JsonConvert.DeserializeObject<UpdateInput>(await ReadRequestBody(context));

        if (!ModelState.IsValid)
        {
            // Handle invalid model state here
            return;
        }

        var pageSection = await _context.PageSections.FirstOrDefaultAsync(p => p.Id == input.PageSectionId);
        if (pageSection == null)
        {
            // Handle non-existing page section here
            return;
        }

        var element = await _context.Elements.FirstOrDefaultAsync(e => e.Id == input.ElementId && e.PageSectionId == input.PageSectionId);
        if (element == null)
        {
            // Handle non-existing element here
            return;
        }

        var cacheKey = $"page:{pageSection.Id}:{element.Id}";
        var cachedContent = _redisDatabase.StringGet(cacheKey);

        if (cachedContent != null)
        {
            // Update the element's content with the cached value if available
            element.HtmlContent = cachedContent;
            await _context.SaveChangesAsync();
        }
        else
        {
            // Perform the update and cache the new content
            element.HtmlContent = input.HtmlContent;
            await _context.SaveChangesAsync();

            _redisDatabase.StringSet(cacheKey, element.HtmlContent, new RedisCacheEntryOptions() { SlidingExpiration = TimeSpan.FromMinutes(5) }); // Adjust expiration time as needed
        }
    }

    private async Task<string> ReadRequestBody(HttpContext context)
    {
        var buffer = new byte[context.Request.ContentLength];
        await context.Request.Body.ReadAsync(buffer, 0, buffer.Length);
        return Encoding.UTF8.GetString(buffer);
    }
}

public class UpdateInput
{
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
    public string HtmlContent { get; set; }
}
