    this.options = Object.assign({
      baseUrl: '',
      timeout: 5000,
      retryInterval: 1000,
      maxRetries: 3
    }, options);

    this.queue = [];
  }

  enqueue(url) {
    const uniqueFilename = this._generateUniqueFilename(url);
    this.queue.push({ url, uniqueFilename });
    this._processQueue();
  }

  _processQueue() {
    if (!this.queue.length) return;

    const { url, uniqueFilename } = this.queue.shift();

    fetch(this.options.baseUrl + url, {
      cache: 'no-store',
      timeout: this.options.timeout
    })
      .then(response => {
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        return response.text();
      })
      .then(scriptContent => {
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.innerHTML = scriptContent;
        document.head.appendChild(script);
      })
      .catch(error => {
        console.error(`Error loading ${uniqueFilename}:`, error);
        this._retry(url, uniqueFilename);
      });
  }

  _generateUniqueFilename(url) {
    const timestamp = new Date().getTime();
    const fileTypeIndex = url.lastIndexOf('.');
    const fileType = url.slice(fileTypeIndex);
    return `temp_${timestamp}${fileType}`;
  }

  _retry(url, uniqueFilename) {
    if (this.queue.some(({ url: currentUrl }) => currentUrl === url)) return;

    const retryAttempt = this.options.maxRetries - this.queue.length;
    setTimeout(() => this.enqueue({ url, uniqueFilename }), retryAttempt * this.options.retryInterval);
  }
}
```

This module can be used as follows:

```javascript
const remoteScriptLoader = new RemoteScriptLoader();
remoteScriptLoader.enqueue('https://example.com/script.js');
```"]

