```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int stream_id;
    float signal_strength;
    float noise_level;
    time_t timestamp;
} SensorData;

typedef struct {
    pthread_mutex_t lock;
    int capacity;
    int head;
    int tail;
    SensorData* buffer;
} RingBuffer;

RingBuffer create_ring_buffer(int capacity) {
    RingBuffer rb = { .capacity = capacity };
    rb.buffer = malloc(sizeof(SensorData) * capacity);
    rb.lock = PTHREAD_MUTEX_INITIALIZER;
    rb.head = 0;
    rb.tail = 0;
    return rb;
}

void enqueue(RingBuffer* rb, SensorData data) {
    pthread_mutex_lock(&rb->lock);
    if ((rb->head + 1) % rb->capacity == rb->tail) {
        // Buffer is full, handle overflow
    }
    rb->buffer[rb->head] = data;
    rb->head = (rb->head + 1) % rb->capacity;
    pthread_mutex_unlock(&rb->lock);
}

SensorData dequeue(RingBuffer* rb) {
    SensorData data;
    pthread_mutex_lock(&rb->lock);
    if (rb->head == rb->tail) {
        // Buffer is empty, handle underflow
    }
    data = rb->buffer[rb->tail];
    rb->tail = (rb->tail + 1) % rb->capacity;
    pthread_mutex_unlock(&rb->lock);
    return data;
}

