        for (int i = 0; i < num_streams; ++i) {
            SensorData oldest_data = dequeue(buffers + i);
            if (!oldest_data.signal_strength || !oldest_data.noise_level) continue; // Handle underflow.

            fetch_metadata(i, NULL); // Fetch metadata for the oldest data point.
            adjust_threshold(thresholds + i, oldest_data.signal_strength, oldest_data.noise_level); // Adjust threshold based on the metadata and the oldest data point.
        }
    }

    SensorData max_data;
