using mutex_t = std::mutex;

class ConfigLoader {
public:
    explicit ConfigLoader(const path& filePath) : _filePath(filePath), _cacheMutex(_mutex) {}

    int loadConfig(json& config) {
        if (loadFromCache(config)) return _numEntries;

        ifstream ifs(_filePath.string());
        if (!ifs.is_open()) return -1; // Error: Unable to open file

        json loadedJson;
        try {
            loadedJson = json::parse(ifs);
        } catch (const exception& e) {
            cerr << "Error parsing JSON: " << e.what() << endl;
            return -2; // Error: Malformed JSON
        }

        if (!validateConfig(loadedJson)) return -3; // Error: Invalid configuration structure

        config = move(loadedJson);
        _numEntries = countEntries(config);
        cache(config);

        return _numEntries;
    }

private:
    bool loadFromCache(json& config) {
        if (_cache.count(_filePath)) {
            config = _cache[_filePath];
            _numEntries = countEntries(config);
            return true;
        }
        return false;
    }

    void cache(const json& config) {
        lock_guard<mutex_t> lock(_cacheMutex);
        _cache[_filePath] = config;
    }

    bool validateConfig(const json& config) {
        // Implement validation logic here
