#include <vector>
#include <list>
#include <memory>

class Node {
public:
    std::string className;
    std::string id;
    std::list<std::unique_ptr<Node>> children;

    // Constructor, getters and setters omitted for brevity
};

struct Config {
    const char* selector;
    size_t limit;
    void (*callback)(const Node*, const char*);
};

std::list<Node*> processDOMElements(Node* root, const Config& config) {
    if (!root) return {};

    std::list<Node*> result;
    std::vector<Node*> stack{root};
    size_t length = std::strlen(config.selector);

    if (length > config.limit) return result;

    while (!stack.empty()) {
        auto node = stack.back();
        stack.pop_back();

        if (node->className == config.selector || node->id == config.selector) {
            config.callback(node, config.selector);
            result.push_back(node);
        }

        for (auto& child : node->children)
            stack.push_back(child.get());
    }

    return result;
}
