using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using Magick.Net;
using Magick.Net.Formats.Tiff;
using Magick.Net.Utils;

public class ImageInfo
{
    public int BitsPerSample { get; set; }
    public int SamplePerPixel { get; set; }
    public int[] ExtraSamples { get; set; }
    public byte[] Md5Hash { get; set; }
}

public ImageInfo ProcessTiffImage(string filePath, Action<string> log = null, bool includeExtraSamples = true)
{
    if (!File.Exists(filePath))
        throw new FileNotFoundException("The specified TIFF image file does not exist.", filePath);

    try
    {
        using (var image = new MagickImage(filePath, ReadOptions.SetFormat(TiffFormat.Tiff)))
        {
            var info = new ImageInfo
            {
                BitsPerSample = image.Depth > 8 ? (int)image.Depth : throw new NotSupportedException("Unsupported bit depth."),
                SamplePerPixel = image.SamplesPerPixel,
            };

            if (includeExtraSamples)
            {
                info.ExtraSamples = image.ChannelCount > 3 ? image.Channels.Select(c => c.Depth).ToArray() : new int[0];
            }

            using (var ms = new MemoryStream())
            {
                image.Write(ms);
                info.Md5Hash = MD5.Create().ComputeHash(ms.ToArray());
            }

            if (log != null)
            {
                log($"Processing TIFF image: {filePath}");
                log($"Bits per sample: {info.BitsPerSample}");
                log($"Sample per pixel: {info.SamplePerPixel}");
                if (includeExtraSamples)
                    log($"Extra samples: {string.Join(", ", info.ExtraSamples)}");
                log($"MD5 hash: {BitConverter.ToString(info.Md5Hash).Replace("-", string.Empty)}");
            }
        }
    }
    catch (Exception ex)
    {
        throw new Exception($"An error occurred while processing the TIFF image '{filePath}'. Details: {ex.Message}", ex);
    }

    return info;
}
```

