```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Diagnostics;
using System.Threading;

public class WebsiteStarter
{
    public static ProcessStartInfo StartWebsite(string directoryPath, string siteName)
    {
        if (!File.Exists($"{directoryPath}\\web.config")) return null;

        var processInfo = new ProcessStartInfo();
        processInfo.FileName = $"{directoryPath}\\dotnet.exe";
        processInfo.Arguments = $"watch run --project {siteName}.csproj";

        if (!CheckDependencies(directoryPath))
        {
            Console.WriteLine($"Missing dependencies for website '{siteName}'.");
        }

        var process = new Process();
        process.StartInfo = processInfo;
        process.Start();

        var cts = new CancellationTokenSource();
        var ct = cts.Token;

        Task.Run(async () =>
        {
            await Task.Delay(TimeSpan.FromSeconds(10), ct);

            try
            {
                using (var httpClient = new HttpClient())
                {
                    var response = await httpClient.GetAsync($"http://localhost:{process.Id}/");
                    response.EnsureSuccessStatusCode();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Site is not operational.");
                cts.Cancel();
            }
        });

        process.Exited += (sender, args) =>
        {
            if (!ct.IsCancellationRequested) return;

            if (process.ExitCode != 0)
            {
                Console.WriteLine("Process exited with non-zero code.");
            }
        };

        return processInfo;
    }
}
```

