[' Here's a simplified version of the Java application you requested. This code doesn't include all the features you mentioned but serves as a starting point. I've focused on the core functionality of script generation, execution, logging, and file deletion.

```java
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.ZipOutputStream;
import javax.script.*;

public class ScriptExecutor {
    private static final String LOG_DIR = "logs";
    private static final String SCRIPT_EXTENSION = ".js";

    public void executeScript(Map<String, Object> params) throws Exception {
        String scriptName = UUID.randomUUID().toString() + SCRIPT_EXTENSION;
        Path scriptPath = Files.createTempFile(Paths.get("scripts"), "", scriptName);
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("nashorn");

        engine.put("params", params);
        engine.put("logWriter", new LogWriter(scriptPath.getParent().resolve(LOG_DIR).toString()));

        engine.eval(Files.newBufferedReader(scriptPath));

        ProcessBuilder processBuilder = new ProcessBuilder(new String[]{"bash", "-c", "chmod +x " + scriptPath});
        processBuilder.inheritIO().start();

        Process process = new ProcessBuilder()
                .command("bash", "-c", "sh " + scriptPath)
                .directory(scriptPath.getParent())
                .redirectErrorStream(true)
                .start();

        try {
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new RuntimeException("Script execution failed with exit code: " + exitCode);
            }
        } finally {
            Files.deleteIfExists(scriptPath);
        }
    }

    private static class LogWriter {
        private final String logDir;
        private PrintWriter writer;
        private ZipOutputStream zipper;

        public LogWriter(String logDir) {
            this.logDir = logDir;
        }

        public void writeLine(String line) {
            if (writer == null) {
                try {
                    File directory = new File(logDir);
                    if (!directory.exists()) {
                        directory.mkdirs();
                    }
                    Calendar calendar = Calendar.getInstance();
                    SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd");
                    String currentDate = dateFormatter.format(calendar.getTime());
                    File logFile = new File(logDir, currentDate + ".log");
                    writer = new PrintWriter(new FileWriter(logFile, true));
                } catch (IOException e) {
                    throw new RuntimeException("Failed to create log file", e);
                }
            }
            writer.println(line);
            rotateLogs();
        }

        private void rotateLogs() {
            if (zipper == null) {
                try {
                    File logsDirectory = new File(logDir);
                    File[] logFiles = logsDirectory.listFiles((dir, name) -> name.endsWith(".log"));
                    if (logFiles != null && logFiles.length > 1) {
                        Calendar calendar = Calendar.getInstance();
                        SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd_HHmmss");
                        String currentTime = dateFormatter.format(calendar.getTime());
                        zipper = new ZipOutputStream(new FileOutputStream(new File(logsDirectory, "archive_" + currentTime + ".zip")));
                    }
                } catch (FileNotFoundException e) {
                    throw new RuntimeException("Failed to create archive file", e);
                }
            }
            if (zipper != null) {
                try {
                    File logFile = new File(logDir, "archive_" + System.currentTimeMillis() + ".log");
                    Files.copy(Paths.get(logDir, "latest.log"), Paths.get(logFile.getAbsolutePath()));
                    writer.close();
                    writer = null;
                    zipLogFile(logFile);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to rotate logs", e);
                }
            }
        }

        private void zipLogFile(File logFile) throws IOException {
            try (FileInputStream fis = new FileInputStream(logFile)) {
                zipper.putNextEntry(new ZipEntry(logFile.getName()));
                byte[] buffer = new byte[1024];
                int length;
                while ((length = fis.read(buffer)) > 0) {
                    zipper.write(buffer, 0, length);
                }
            } finally {
                Files.deleteIfExists(logFile.toPath());
            }
        }
    }
}
