    const configContent = fs.readFileSync(configFilePath, 'utf8');
    try {
        return yaml.load(configContent);
    } catch (error) {
        throw new Error(`Error parsing configuration file: ${error.message}`);
    }
}

// Function to initialize the application with the loaded configuration
async function initApp(config, dependencies) {
    const { services, environmentVariables } = config;

    // Set environment variables
    for (let envVar in environmentVariables) {
        process.env[envVar] = environmentVariables[envVar];
    }

    // Load required services and their dependencies
    loadDependencies(dependencies);

    // Initialize each service with the provided configuration
    for (let service of services) {
        const ServiceClass = require(`./services/${service}`);
        const serviceInstance = new ServiceClass(service.config);
        await serviceInstance.initialize();
    }
}

// Main function to start the application
