[' I'll provide you with a basic structure for the TripleDESDecryptor class in C#. This class uses the `System.Security.Cryptography` namespace for encryption and decryption, and `System.IO` for Base64 encoding/decoding. For HMAC-SHA256 signature validation, I'll use the `System.Security.Cryptography.HMACSHA256` class.

Please note that this is a simplified version and does not include key management, external API integration, or extensive error handling for concurrent decryption requests in a high-traffic environment. You may need to further develop the class based on your specific requirements.

```csharp
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Linq;

public class TripleDESDecryptor
{
    private readonly TripleDESCryptoServiceProvider _tripleDes;
    private readonly HMACSHA256 _hmac;
    private byte[] _key;
    private byte[] _iv;

    public TripleDESDecryptor(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
        _tripleDes = new TripleDESCryptoServiceProvider();
        _hmac = new HMACSHA256(_key);
    }

    public string DecryptBase64(string base64EncodedMessage, byte[] signature)
    {
        var decryptedBytes = Decrypt(_tripleDes, _iv, Convert.FromBase64String(base64EncodedMessage));
        var calculatedSignature = _hmac.ComputeHash(decryptedBytes);

        if (calculatedSignature.SequenceEqual(signature))
            return Encoding.UTF8.GetString(decryptedBytes);

        throw new Exception("Invalid HMAC signature.");
    }

    private byte[] Decrypt(TripleDESCryptoServiceProvider tripleDes, byte[] iv, byte[] encryptedData)
    {
        using (var ms = new MemoryStream(encryptedData))
        {
            using (var cs = new CryptoStream(ms, tripleDes.CreateDecryptor(_key, _iv), CryptoStreamMode.Read))
            {
                var decryptedBytes = new byte[encryptedData.Length];
                cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                return decryptedBytes;
            }
        }
    }
}
```

