```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <openssl/sha.h>

#define MAX_FILENAME_LENGTH 256
#define CONFIG_FILE "config.txt"

char* generate_filename(const char *input_filename) {
    char hash[SHA256_DIGEST_LENGTH * 2 + 1];
    SHA256((unsigned char *) input_filename, strlen(input_filename), (unsigned char *) hash);
    for (int i = 0; i < SHA256_DIGEST_LENGTH * 2; ++i) {
        sprintf(&hash[i], "%02x", (unsigned int) hash[i]);
    }

    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));

    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        fprintf(stderr, "Error: Unable to open configuration file.\n");
        return NULL;
    }

    char config_line[MAX_FILENAME_LENGTH];
    char *version = NULL, *environment = NULL;
    while (fgets(config_line, sizeof(config_line), config_file)) {
        if (strncmp(config_line, "VERSION=", 7) == 0) {
            version = strdup(&config_line[7]);
        } else if (strncmp(config_line, "ENVIRONMENT=", 12) == 0) {
            environment = strdup(&config_line[12]);
        }
    }
    fclose(config_file);

    char *filename = malloc(MAX_FILENAME_LENGTH);
    snprintf(filename, MAX_FILENAME_LENGTH, "%s-%s-%s%s", hash, timestamp, version, input_filename);

    size_t len = strlen(filename);
    int dot_index = -1;
    for (size_t i = 0; i < len; ++i) {
        if (input_filename[i] == '.') {
            dot_index = (int) i;
            break;
        }
    }

    if (dot_index != -1 && strlen(filename) + strlen(environment) + 2 < MAX_FILENAME_LENGTH) {
        strncat(filename, environment, MAX_FILENAME_LENGTH - len - 2);
        filename[len + strlen(environment)] = '.';
        strncat(filename + len + strlen(environment) + 1, input_filename + dot_index, MAX_FILENAME_LENGTH - len - strlen(environment) - 3);
    } else {
        strncat(filename, environment, MAX_FILENAME_LENGTH - len - 2);
        filename[len + strlen(environment)] = '.';
        strncat(filename + len + strlen(environment) + 1, input_filename, MAX_FILENAME_LENGTH - len - strlen(environment) - 3);
    }

    return filename;
}
