```rust
use openssl::asn1::{Derive, Derivation};
use openssl::aes::{Aes256, Cbc);
use openssl::evp::{Pkey, Rsa, Oaep;};
use openssl::hash::Sha1;
use hyper::Client;
use std::io::Write;
use std::sync::Arc;

struct CipherContext {
    cipher: Aes256<Cbc<Vec<u8>>>,
    ctx: Arc<Pkey<Rsa>>,
    http_client: Client,
}

fn initialize_cipher(password: &str, url: &str, verify_cert: bool) -> Result<CipherContext, ()> {
    let mut key = Vec::with_capacity(Aes256::<Cbc<Vec<u8>>>::block_size());
    let mut iv = Vec::with_capacity(Aes256::<Cbc<Vec<u8>>>::block_size());

    let mut ctx = Derive::new(Sha1::new())
        .derive(&password.as_bytes(), &Derivation::Pkcs5)
        .unwrap();
    ctx.read_to_end(&mut key).unwrap();
    ctx.read_to_end(&mut iv).unwrap();

    let cipher = Aes256::<Cbc<Vec<u8>>>::new_vec(key, iv)?;

    let mut rsa_config = Rsa::generate(2048, &openssl::rsa::RsaBuilder::new().unwrap())?;
    let ctx = Arc::new(Pkey::<Rsa>::from_pkey(&rsa_config)?);

    let http_client = Client::builder()
        .build(hyper::rt::tokio::runtime::Runtime::new().unwrap().handle());

    if !verify_cert {
        http_client.set_global_ssl_arena_config(|arena_config| {
            arena_config.set(
                hyper::tls::h2::H2ConfigBuilder::new()
                    .map_err(|e| e!)?
                    .no_early_data()
                    .build(),
            )?;
        });
    }

    Ok(CipherContext { cipher, ctx, http_client })
}

fn cleanup_cipher(ctx: &mut CipherContext) {
    drop(ctx.http_client);
    drop(ctx.ctx);
}
