} NFAPI_CRC_INDICATION_PDU_T;

// Union-Find data structure
typedef struct {
    int* parent;
    int* rank;
    int size;
} UFSet;

void init_ufset(UFSet* set, int n) {
    set->parent = malloc(n * sizeof(int));
    set->rank = calloc(n, sizeof(int));
    set->size = n;

    for (int i = 0; i < n; ++i) {
        set->parent[i] = i;
        set->rank[i] = 1;
    }
}

int find_set(UFSet* set, int x) {
    if (x != set->parent[x]) {
        set->parent[x] = find_set(set, set->parent[x]);
    }
    return set->parent[x];
}

void union_sets(UFSet* set, int x, int y) {
    int rootX = find_set(set, x);
    int rootY = find_set(set, y);

    if (rootX != rootY) {
        if (set->rank[rootX] < set->rank[rootY]) {
            set->parent[rootX] = rootY;
            set->rank[rootY] += set->rank[rootX];
        } else {
            set->parent[rootY] = rootX;
            set->rank[rootX] += set->rank[rootY];
        }
    }
}

void process_NFapiAndUnionFind(int* array, int size, NFAPI_CRC_INDICATION_PDU_T** pduList) {
    if (size <= 0 || array == NULL) {
        fprintf(stderr, "Invalid input: Array size must be greater than zero.\n");
        return;
    }

    for (int i = 0; i < size; ++i) {
        if (array[i] < 0) {
            fprintf(stderr, "Invalid input: Array contains negative integers.\n");
            return;
        }
    }

    *pduList = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int uniqueTags = 0;
    for (int i = 0; i < size; ++i) {
        int tag = uniqueTags++;
        int rnti = array[i];
        CRC_INDICATION_REL8_TAG crc_indication = (CRCFLAG)(rand() % 2); // Randomly set CRCFLAG

        // Check for duplicates and reassign tags if necessary
        while ((*pduList)[uniqueTags - 1].tag == tag) {
            tag = uniqueTags++;
        }

        (*pduList)[uniqueTags - 1] = (NFAPI_CRC_INDICATION_PDU_T){ .tag = tag, .rnti = rnti, .crc_indication = crc_indication };
    }

    UFSet ufset;
    init_ufset(&ufset, size);

    clock_t start = clock();
    for (int i = 0; i < size; ++i) {
        union_sets(&ufset, (*pduList)[i].rnti, (*pduList)[i].tag);
    }
    clock_t end = clock();

    double time_taken = (double)(end - start) / CLOCKS_PER_SEC * 1000;

    printf("Number of disjoint pairs: %d\n", ufset.size);
    printf("Time taken for Union-Find operations (ms): %.2f\n", time_taken);
}
