#include <stdio.h>
#include <string.h>
#include <regex.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* email;
    void* session;
    void* config;
    void (*log_func)(const char*, ...);
} UserData;

enum ErrorCodes {
    EC_SUCCESS = 0,
    EC_INVALID_EMAIL,
    EC_INVALID_SESSION,
    EC_INVALID_CONFIG,
    EC_NULL_LOG_FUNC,
    EC_RACE_CONDITION
};

int validate_user_data(UserData* user) {
    int ret = EC_SUCCESS;

    // Validate email format
    regex_t regex;
    regmatch_t match;
    const char* pattern = "^[\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4}$";
    if (regcomp(&regex, pattern, REG_EXTENDED)) {
        ret = EC_INVALID_EMAIL;
        goto cleanup;
    }

    // Validate session
    if (!user->session) {
        ret = EC_INVALID_SESSION;
        goto cleanup;
    }

    // Validate configuration object
    if (!user->config) {
        ret = EC_INVALID_CONFIG;
        goto cleanup;
    }

    // Validate logging function
    if (!user->log_func) {
        ret = EC_NULL_LOG_FUNC;
        goto cleanup;
    }

    // Check for race conditions when updating last active timestamp
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    pthread_mutex_lock(&lock);
    user->session = realloc(user->session, sizeof(struct session) + now.tv_sec * sizeof(long long));
    if (!user->session) {
        ret = EC_RACE_CONDITION;
        goto cleanup;
    }
    ((long long*)user->session)[now.tv_sec] = now.tv_nsec;
    pthread_mutex_unlock(&lock);

cleanup:
    regfree(&regex);
    return ret;
}
