typedef struct {
    EVP_CIPHER_CTX *cipher;
    unsigned char theme[/* size of your theme bitmap */];
} ThemeContext;

ThemeContext* initializeThemeAndRunCommand(const char *password, const char *command) {
    // Initialize OpenSSL and libpng contexts
    EVP_CIPHER_CTX *cipher = EVP_CIPHER_CTX_new();
    unsigned int key_len;
    unsigned char key[EVP_MAX_KEY_LENGTH];

    // Derive the encryption key using a secure KDF (e.g., Argon2)
    // ...

    // Initialize AES-256-CBC cipher with derived key and IV
    EVP_EncryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, key, /* IV */);

    // Recycle theme bitmap if not already used and set to null
    memset(theme, 0, sizeof(theme));

    // Parse PNG file from cache root directory and incorporate it into the theme cache
    // ...

    // Enable the cipher
    int rc = EVP_EncryptInit_ex(cipher, NULL);
    if (rc <= 0) {
        goto error;
    }

    ThemeContext *context = malloc(sizeof(ThemeContext));
    context->cipher = cipher;

    // Fork a child process to run the command in the background
    pid_t pid = fork();
    if (pid < 0) {
        goto error;
    } else if (pid == 0) {
        // Child process: execute the command
        execlp(command, command, NULL);
        perror("execlp");
        exit(1);
    }

    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status)) {
        return context;
    } else {
        goto error;
    }

error:
    // Cleanup and disable the cipher when no longer needed
    EVP_CIPHER_CTX_free(context->cipher);
    free(context);
    return NULL;
}
