#include <cassert>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    std::chrono::steady_clock::time_point timestamp;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
std::mutex mtx;

void createAndPopulate(size_t N, uint32_t (*generateCRCTag)(uint32_t lastTag)) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> newIndications;

    for (size_t i = 0; i < N; ++i) {
        uint32_t tag = generateCRCTag(i == 0 ? 0 : crcIndications.back().CRC_INDICATION_REL8_TAG + 1);
        while (!std::all_of(newIndications.cbegin(), newIndications.cend(),
                            [tag](const auto& pdu) { return pdu.CRC_INDICATION_REL8_TAG != tag; })) {
            if (newIndications.size() == crcIndications.size()) {
                std::cerr << "Error: Insufficient memory to allocate new structures." << std::endl;
                return;
            }
            newIndications.push_back({});
        }

        auto now = std::chrono::steady_clock::now();
        newIndications.back().RX_UE_INFORMATION_TAG = i + 1;
        newIndications.back().RNTI = i * 2 + 3; // Example RNTI generation logic
        newIndications.back().CRC_INDICATION_REL8_TAG = tag;
        newIndications.back().timestamp = now;
    }

    std::unique_lock<std::mutex> lock(mtx);
    crcIndications.swap(newIndications);
    lock.unlock();

    if (callback) {
        callback(crcIndications);
    }
}

void processCrcIndications(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& indications, void (*callback)(const std::vector<NFAPI_CRC_INDICATION_PDU_T>&)) {
    callback = callback;
    createAndPopulate(indications.size(), [](uint32_t lastTag) -> uint32_t { return lastTag + 1; });
}
```

