```"]

[' Here's a Python function that addresses your requirements:

```python
import os
import sys
import time
import threading
import logging
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor

def manage_tests(label, f, config):
    test_results = defaultdict(lambda: {'status': None, 'start_time': None, 'duration': None})
    log = logging.getLogger(__name__)

    def _run_test(label, f):
        try:
            module = __import__(config['module'], fromlist=[label])
            test_func = getattr(module, label)
            start_time = time.monotonic()
            result = test_func()
            duration = time.monotonic() - start_time
            log.info(f"Test '{label}' started at {start_time:.6f}, completed at {duration:.6f}s, status: {str(result)}")
            return result
        except Exception as e:
            log.error(f"Error running test '{label}': {e}", exc_info=True)
            return False

    if config['parallel'] and threading.active_count() < len(config['tests']):
        with ThreadPoolExecutor(max_workers=min(len(config['tests']), os.cpu_count())) as executor:
            for result in executor.map(_run_test, config['tests'], config['functions']):
                test_results[config['tests'][config['functions'].index(f)]] = {'status': result, 'start_time': None, 'duration': None}
    else:
        for label, f in zip(config['tests'], config['functions']):
            if not config.get('skip', {}).get(label, False):
                test_results[label] = _run_test(label, f)

    return {k: v['status'] for k, v in test_results.items() if v['status'] is not None}
```

