[' Here's a basic structure for the PHP script, using Composer autoloader, PDO for database connection, and a simple function for updating clinic data in the database. I've also included a caching mechanism using Redis and logging for successful updates and failed attempts.

```php
<?php
// config.php - Application configuration file
$config = require __DIR__ . '/config.php';

// vendor/autoload.php - Composer autoloader
require __DIR__ . '/vendor/autoload.php';

use Predis\Client as Redis;

class Database {
    private $pdo;
    private $redis;

    public function __construct() {
        $this->pdo = new PDO($config['db_dsn'], $config['db_user'], $config['db_pass']);
        $this->redis = new Redis();
        $this->redis->connect($config['redis_host'], $config['redis_port']);
    }

    public function beginTransaction() {
        return $this->pdo->beginTransaction();
    }

    public function commit() {
        return $this->pdo->commit();
    }

    public function rollback() {
        return $this->pdo->rollback();
    }

    // Cache get and set methods for Redis
    public function get($key) {
        return $this->redis->get($key);
    }

    public function set($key, $value, $expire = 0) {
        return $this->redis->setex($key, $expire, $value);
    }
}

class Clinic {
    private $db;

    public function __construct(Database $db) {
        $this->db = $db;
    }

    public function updateStatusAndLastModified($clinicId, $status, $ipAddress) {
        try {
            $this->db->beginTransaction();

            // Query to update clinic status and last modified date
            $stmt = $this->db->pdo->prepare("UPDATE clinics SET status = :status, last_modified_date = NOW(), last_modified_ip = :ipAddress WHERE id = :clinicId");
            $stmt->execute([':clinicId' => $clinicId, ':status' => $status, ':ipAddress' => $ipAddress]);

            // Cache the updated clinic data for faster reads
            $this->db->set('clinic_' . $clinicId, json_encode($stmt->fetch(PDO::FETCH_ASSOC)));

            $this->db->commit();

            // Log successful update
            logUpdateSuccess($clinicId);
        } catch (Exception $e) {
            // Log failed attempt and rollback the transaction
            logUpdateFailure($e->getMessage());
            $this->db->rollback();
        }
    }
}

