use reqwest::Client;
use std::collections::HashMap;
use std::time::{Duration};
use tokio::task::spawn_blocking;
use tokio::runtime::Runtime;

pub struct Config {
    base_url: String,
    verify_certificate: bool,
    retries: u32,
    retry_delay_base: Duration,
}

pub async fn create_http_client(config: &Config) -> Result<Client, reqwest::Error> {
    let mut client = Client::new();

    if !config.verify_certificate {
        client.set_global_ssl_hostname_verifier(move || true);
    }

    let runtime = Runtime::new().unwrap();

    let handle_request = move |req| {
        async move {
            match req.send().await {
                Ok(res) => res,
                Err(e) => {
                    if config.retries > 0 {
                        let delay = config.retry_delay_base * (2.0.pow(config.retries as u64 - 1));
                        let sleep = tokio::time::sleep(delay).await;
                        spawn_blocking(move || create_http_client(config)).await.unwrap().send(req).await?
                    } else {
                        return Err(e);
                    }
                }
            }
        }
    };

    client.request_builder_with_body(|req| {
        req.on_error(move |e| {
            eprintln!("Request error: {}", e);
        })
        .method(req.method())
        .uri(&config.base_url)
        .body(req.body())
    }).handle(handle_request)
}
