// Define aliases for digests
#define MD5_DIGEST "md5"
#define SHA1_DIGEST "sha1"
#define SHA256_DIGEST "sha256"

typedef struct {
    EVP_CIPHER_CTX* cipher_ctx;
    EVP_MD_CTX* digest_ctx;
    unsigned char* key;
    size_t key_len;
} crypt_context;

crypt_context* crypt_init(const char* key_path, const char* algorithm) {
    // Initialize context and load key from file
    crypt_context* ctx = malloc(sizeof(crypt_context));
    if (!ctx) return NULL;

    // Load key into memory
    FILE* fp = fopen(key_path, "rb");
    if (!fp) goto error;
    fseek(fp, 0, SEEK_END);
    size_t key_size = ftell(fp);
    rewind(fp);
    ctx->key = mmap(NULL, key_size, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    if (ctx->key == MAP_FAILED) goto error;
    fread(ctx->key, 1, key_size, fp);
    fclose(fp);
    ctx->key_len = key_size;

    // Initialize cipher and digest contexts
    EVP_CIPHER_CTX_init(&ctx->cipher_ctx);
    EVP_MD_CTX_init(&ctx->digest_ctx);

    // Configure cipher and digest using OpenSSL functions
    int ret = EVP_add_cipher(ctx->cipher_ctx, algorithm);
    if (ret <= 0) goto error;
    ret = EVP_add_digest(ctx->digest_ctx, algorithm);
    if (ret <= 0) goto error;

    return ctx;

error:
    // Handle errors and clean up resources
    // ...
    free(ctx);
    return NULL;
}

void crypt_free(crypt_context* ctx) {
    // Clear key from memory
    munmap(ctx->key, ctx->key_len);

    // Free context and associated resources
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    EVP_MD_CTX_free(ctx->digest_ctx);
    free(ctx);
}

// Implement encryption, decryption, and digest functions using the crypt_context
// ...
