int convert_jpeg_to_pdf(const char *input, const char *output, const char *tool, FILE *log) {
    ConversionData data = {.input = input, .output = output, .tool = tool, .log = log};
    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    // Create temporary PDF file name
    char temp_pdf[1024] = {0};
    snprintf(temp_pdf, sizeof(temp_pdf), "%s.tmp", output);

    // Start conversion in separate threads
    while (num_threads < MAX_THREADS && access(input, F_OK) == 0) {
        pthread_create(&threads[num_threads], NULL, convert_helper, &data);
        num_threads++;
    }

    // Wait for all threads to finish or reach the timeout limit
    int remaining = MAX_THREADS;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (remaining > 0 || (clock_gettime(CLOCK_MONOTONIC, &end) - start).tv_sec < TIMEOUT / 1000.0) {
        int completed = 0;
        for (int i = 0; i < num_threads; ++i) {
            int state;
            pthread_join(threads[i], &state);
            if (state == PTHREAD_STATE_DEAD) {
                if (WEXITSTATUS(state) == 0) {
                    completed++;
                } else if (WEXITSTATUS(state) == 2) {
                    // Log error and return 2 immediately
                    fprintf(data.log, "Error: Conversion failed for %s\n", input);
                    return 2;
                }
            }
        }
        if (completed == num_threads) {
            break;
        }
        remaining--;
        usleep(100000); // Sleep for a short period to reduce CPU usage
    }

    // If timeout is reached, delete the temporary PDF file and return 1
    if (num_threads > 0 && access(temp_pdf, F_OK) == 0) {
        unlink(temp_pdf);
        return 1;
    }

    // Move the temporary PDF file to the final output location
    rename(temp_pdf, output);

    return 0;
}

void* convert_helper(void *data) {
    ConversionData *conversion = (ConversionData *) data;
    char command[1024] = {0};
    snprintf(command, sizeof(command), "%s %s %s %s", conversion->tool, input, temp_pdf, output);

    // Implement retry logic with appropriate backoff strategies
    int attempts = 3;
    while (attempts > 0) {
        if (system(command) == 0) {
            break;
        }
        usleep(pow(2, attempts++) * 100000); // Exponential backoff
    }

    if (attempts <= 3) {
        fprintf(conversion->log, "Conversion of %s started at %s\n", input, ctime(&time(NULL)));
        if (attempts > 1) {
            fprintf(conversion->log, "Retried after %d attempts due to temporary tool unavailability or network issues.\n", attempts);
        }
    } else {
        // Log error and return immediately
        fprintf(conversion->log, "Error: Conversion of %s failed after %d attempts\n", input, attempts);
        pthread_exit((void *) 2);
    }

    pthread_exit((void *) 0);
}
