use std::env;
use std::error::Error;
use std::fmt;
use std::io::{self, Write};
use std::net::TcpStream;
use std::sync::Arc;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::prelude::*;
use tokio::time::sleep;
use digest::Digest;
use sha2::{Sha256, Sha512};
use reqwest::Client;

type Result<T> = std::result::Result<T, Box<dyn Error + Send + Sync + 'static>>;

struct ExternalData {
    url: String,
    metadata: Option<String>,
}

impl ExternalData {
    async fn fetch(&self) -> Result<Self> {
        let mut client = Client::new();
        let response = client.get(&self.url).send().await?;
        let metadata = response.text().await?;
        Ok(ExternalData { url: self.url, metadata: Some(metadata) })
    }

    async fn retry_fetch(&mut self, max_retries: u32) -> Result<Self> {
        if let Some(ref metadata) = self.metadata {
            return Ok(self.clone());
        }

        match self.fetch().await {
            Ok(data) => Ok(data),
            Err(e) if max_retries > 0 => {
                sleep(e::duration_from_secs(2u64::pow(max_retries as u64, 2))).await;
                self.retry_fetch(max_retries - 1).await?
            }
            Err(e) => Err(Box::new(RetryError { e })),
        }
    }
}

struct RetryError(Box<dyn Error + Send + Sync + 'static>);
impl fmt::Display for RetryError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Retry error: {}", self.0)
    }
}

async fn compute_hash(data: &str, external_data: Arc<ExternalData>) -> Result<String> {
    let mut hasher = Sha256::new();
    hasher.update(format!("{}-{}", data, external_data.metadata.as_ref().unwrap_or("")));
    Ok(hex::encode(hasher.finalize()))
}

async fn process_request(request: &str, external_data: Arc<ExternalData>) -> Result<String> {
    match external_data.retry_fetch(5).await {
        Ok(data) => compute_hash(request, data).await,
        Err(e) => Err(Box::new(e)),
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} STRING", args[0]);
        return Ok(());
    }

    let request = &args[1];
    let external_data = Arc::new(ExternalData { url: "http://example.com/metadata".to_string(), metadata: None });

    let handle = tokio::spawn(process_request(request, external_data.clone()));

    match handle.await {
        Ok(result) => println!("MD5 Hash: {}", result),
        Err(e) => eprintln!("Error computing hash: {}", e),
    }

    Ok(())
}
```

