```csharp
using System;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Collections.Generic;

public class BinaryFileDeserializer
{
    private readonly string _filePath;
    private readonly Type _dataType;
    private static readonly object _lock = new object();

    public BinaryFileDeserializer(string filePath, Type dataType)
    {
        _filePath = filePath;
        _dataType = dataType;
    }

    public T Deserialize<T>()
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        try
        {
            using (var stream = File.OpenRead(_filePath))
            {
                var formatter = new BinaryFormatter();
                T result;

                lock (_lock)
                {
                    result = (T)formatter.Deserialize(stream);
                }

                MonitorMemoryUsage();
                stopwatch.Stop();
                Console.WriteLine($"Deserialization time: {stopwatch.Elapsed}");

                return result;
            }
        }
        catch (SerializationException ex)
        {
            Console.WriteLine($"Error during deserialization: {ex.Message}");
            throw;
        }
    }

    private void MonitorMemoryUsage()
    {
        var process = Process.GetCurrentProcess();
        var memoryInfo = process.WorkingSet64 / (1024 * 1024); // Memory in MB

        Console.WriteLine($"Current memory usage: {memoryInfo} MB");
    }
}
```

