```javascript
const axios = require('axios');
const qs = require('qs');
const lodash = require('lodash');
const Bluebird = require('bluebird');
const winston = require('winston');

// External storage API and logging service configurations
const STORAGE_API_URL = 'https://storage-api.com';
const LOGGING_SERVICE_URL = 'https://logging-service.com';

class Uploader {
  constructor() {
    this.queue = new Map();
    this.connectionPool = new Map();
  }

  async upload(url, fileType, fileSize, fileUploader) {
    const key = url + fileType;

    if (this.queue.has(key)) {
      // Retry logic with exponential backoff
      const retryAttempts = this.queue.get(key).length;
      await Bluebird.delay(Math.pow(2, retryAttempts) * 1000);
    }

    if (!this.queue.has(key)) {
      this.queue.set(key, []);
    }

    const uploadTask = async () => {
      try {
        const response = await fileUploader.upload(url, fileType, fileSize);
        const metadata = {
          uploadDuration: Date.now() - new Date().getTimezoneOffset() * 60000, // Adjust for timezone offset
          fileSize,
          ...response.data
        };

        this.queue.get(key).shift();
        winston.info(`Successfully uploaded ${url} with metadata:`, metadata);
        return metadata;
      } catch (error) {
        const errorMetadata = {
          uploadDuration: Date.now() - new Date().getTimezoneOffset() * 60000, // Adjust for timezone offset
          fileSize,
          error: error.message
        };

        this.queue.get(key).unshift({ url, errorMetadata });
        winston.error(`Failed to upload ${url}:`, errorMetadata);

        if (this.queue.get(key).length > 3) {
          throw new Error('Maximum retry attempts exceeded');
        }

        await this.retryUpload(url, fileType, fileSize, fileUploader);
      }
    };

    const connection = this.connectionPool.get(key) || axios.create({ baseURL: STORAGE_API_URL });
    this.connectionPool.set(key, connection);

    this.queue.get(key).push(uploadTask());
    return Bluebird.race(this.queue.get(key))
      .then((result) => {
        this.connectionPool.delete(key);
        return result;
      });
  }

  async retryUpload(url, fileType, fileSize, fileUploader) {
    const tasks = [...this.queue.get(url + fileType)];
    await Bluebird.mapSeries(tasks, (task) => task(), { concurrency: Math.min(5, tasks.length) })
      .then((results) => {
        if (!results.includes(null)) {
          this.queue.delete(url + fileType);
        } else {
          // Log the error and handle it appropriately (e.g., notify the user or retry after a delay)
          winston.error(`All retry attempts for ${url} failed:`, tasks.filter((_, i) => results[i] === null));
        }
      });
  }

  async logUploadStatus(metadata) {
    const formattedMetadata = lodash.omitBy(metadata, (value, key) => ['uploadDuration', 'fileSize'].includes(key));
    await axios.post(`${LOGGING_SERVICE_URL}/uploads`, qs.stringify(formattedMetadata), { responseType: 'json' });
  }
}
```

This code defines an `Uploader` class that handles file uploads using a specified file uploader library (e.g., `multer` or `busboy`). The class implements retry logic for failed uploads, manages connections to the storage API efficiently, and integrates with an external logging service.

The `upload()` function takes a URL, file type, and size as input and returns a promise that resolves with the uploaded file's metadata. It also logs the upload status and errors using the provided `winston` library. The `retryUpload()` function handles retry attempts for failed uploads, while the `logUploadStatus()` function sends the upload metadata to an external logging service.

The code uses Bluebird promises for handling asynchronous operations and exponential backoff for retry logic. It also manages connections to the storage API using a connection pool to optimize resource usage during concurrent uploads."]

