    public void GenerateGraph(int maxVertices, int maxEdges, int memoryThreshold, Action<Vertex, Vertex> addEdge)
    {
        var vertices = new List<Vertex>();
        var edges = new List<(Vertex v1, Vertex v2)>();

        while (vertices.Count < maxVertices && edges.Count < maxEdges && vertices.Sum(v => v.MemoryUsage) < memoryThreshold)
