                if (!edges.Contains((vertex, edgeVertex)) && !edges.Contains((edgeVertex, vertex)))
                {
                    edges.Add((vertex, edgeVertex));
                    addEdge(vertex, edgeVertex);
                }
            }
        }
    }
}

public class Vertex
{
    public int Id { get; set; }
    public float Size { get; set; }
