private:
    std::uniform_int_distribution<int> m_distIntMinMax;
    std::uniform_real_distribution<double> m_distFloatMinMax;
    std::default_random_engine m_engine;
    int m_minInt, m_maxInt;
    double m_minFloat, m_maxFloat;

    void checkInput(const std::vector<int>& input) {
        if (input.empty()) throw "Invalid input: empty vector";
        for (const auto& i : input) {
            if (i < 0) throw "Invalid input: non-negative integers required";
        }
    }

public:
    DynamicGraphGenerator(int minInt, int maxInt, double minFloat = 0.0, double maxFloat = 1.0)
        : m_distIntMinMax(minInt, maxInt), m_distFloatMinMax(minFloat, maxFloat), m_minInt(minInt), m_maxInt(maxInt) {}

    std::vector<NFAPI_CRC_INDICATION_PDU_T> generateGraph(int size, const std::vector<int>& input) {
        checkInput(input);
        std::vector<NFAPI_CRC_INDICATION_PDU_T> graph;
        std::map<int, bool> usedTags;
        std::map<int, bool> usedRNTIs;

        for (int i = 0; i < size; ++i) {
            int tag = m_distIntMinMax(m_engine);
            while (usedTags.find(tag) != usedTags.end()) tag = m_distIntMinMax(m_engine);
