            int rnti = m_distIntMinMax(m_engine);
            while (usedRNTIs.find(rnti) != usedRNTIs.end()) rnti = m_distIntMinMax(m_engine);
            usedRNTIs[rnti] = true;

            graph.emplace_back(tag, rnti, m_distIntMinMax(m_engine), false);

            for (const auto& j : input) {
                if (i != j && !graph[j].CRCFLAG) {
                    graph[i].CRCFLAG = true;
                    graph[j].CRCFLAG = true;
                }
            }
        }

        return graph;
    }

    void printRange() const {
        std::cout << "Integer range: [" << m_minInt << ", " << m_maxInt << "]\n";
        std::cout << "Float range: [" << m_minFloat << ", " << m_maxFloat << "]\n";
    }
};

