#include <sqlite3.h>

typedef struct {
    sqlite3 *db;
    sqlite3_stmt *stmt;
} IDataReader;

IDataReader* executeSQL(sqlite3 *db, const char *sql, ...) {
    va_list args;
    sqlite3_stmt *stmt;
    IDataReader *reader = (IDataReader*) malloc(sizeof(IDataReader));
    reader->db = db;

    va_start(args, sql);
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot prepare statement: %s\n", sqlite3_errmsg(db));
        free(reader);
        return NULL;
    }

    reader->stmt = stmt;
    return reader;
}

void finalizeSQL(IDataReader *reader) {
    sqlite3_finalize(reader->stmt);
    free(reader);
}
