1. Memory pool for arrays:

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    void* data;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
} Pool;

Pool* create_pool(size_t initial_capacity) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;

    pool->data = malloc(initial_capacity * sizeof(long));
    if (!pool->data) goto error;

    pool->capacity = initial_capacity;
    pool->allocated = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;

error:
    free(pool);
    return NULL;
}

void* grow_pool(Pool* pool) {
    void* new_data = realloc(pool->data, (pool->capacity * 2) * sizeof(long));
    if (!new_data) return NULL;

    pool->capacity *= 2;
    return new_data;
}
```

2. Record array:

```c
typedef struct record {
    int value;
} Record;

Pool* create_record_pool(size_t initial_capacity) {
    // Similar to create_pool() but for Record structures
}

void init_records(Pool* pool, size_t count, int min, int max) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < count; ++i) {
        Record* record = (Record*)((char*)pool->data + pool->allocated * sizeof(long));
        record->value = rand() % (max - min + 1) + min;
        pool->allocated++;
    }

    pthread_mutex_unlock(&pool->lock);
}
```

3. Memory deallocation and management:

