int log_event(const char* event, void* data, size_t size) {
    int fd = open("/path/to/logfile", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) return -1;

    off_t pos = lseek(fd, 0, SEEK_END);
    mmap(NULL, size + sizeof(off_t), PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, fd, pos);
    write(fd, &pos, sizeof(off_t));
    write(fd, data, size);
