function DialogService($q, $rootScope) {
  const REFRESH_MODE = 'refreshMode';
  const SYNCHRONOUS = 'synchronous';
  const ASYNCHRONOUS = 'asynchronous';

  let refreshMode = ASYNCHRONOUS;

  function setRefreshMode(mode) {
    if (mode === SYNCHRONOUS || mode === ASYNCHRONOUS) {
      refreshMode = mode;
    }
  }

  let dialogStack = [];

  function pushDialog(dialog) {
    dialogStack.push(dialog);
  }

  function popDialog() {
    return dialogStack.pop();
  }

  function getCurrentDialog() {
    return dialogStack[dialogStack.length - 1];
  }

  function refreshFields(resourceId, url, fieldNames) {
    const deferred = $q.defer();

    if (!getCurrentDialog()) {
      // Handle the case when there's no active dialog
      return;
    }

    let currentDialog = getCurrentDialog();

    function refreshField(field) {
      if (fieldNames.includes(field.name)) {
        field.sendMessage({ type: 'REFRESH', name: field.name });
      }

      if (field.children && field.children.length > 0) {
        field.children.forEach(childField => refreshField(childField));
      }
    }

    currentDialog.fields.forEach(refreshField);

    if (refreshMode === SYNCHRONOUS) {
      deferred.resolve();
    } else {
      // Assuming that the 'result' event is emitted when a field has been updated
      $rootScope.$on('result', () => {
        if (dialogStack.length === 0) {
          deferred.resolve();
        }
      });
    }

    pushDialog(currentDialog);

    // Make an API call to fetch the data for the given URL and resourceId
    // Implement error handling, retry logic, and circular reference detection here

    return deferred.promise;
  }

  return {
    setRefreshMode,
    refreshFields,
  };
}
