#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

size_t get_filename_length(const char *path) {
    size_t length = 0;
    const char *current = path;
    while (*current != '\0') {
        if (*current == '/') {
            ++length;
        }
        ++current;
    }
    return length + strlen(path);
}

char* process_file(const char *path) {
    size_t path_len = get_filename_length(path);
    if (path_len > 254) {
        fprintf(stderr, "File path exceeds the maximum allowed length of 255 characters.\n");
        return NULL;
    }

    char *new_name = malloc(path_len + 9); // 9 for ".txt" or ".log" and null terminator
    strcpy(new_name, path);

    size_t filename_length = strlen(new_name) - path_len;
    if (filename_length > 3) {
        new_name[path_len] = '\0'; // Truncate the file name if necessary
        filename_length = 3;
    }

    char extension[5];
    strncat(new_name + path_len, &new_name[filename_length], 1); // Copy the last character of the filename to extension
    extension[1] = '\0';
    if (isdigit(extension[0])) {
        strcat(new_name + path_len, ".txt");
    } else if (isalpha(extension[0])) {
        strcat(new_name + path_len, ".log");
    }

    return new_name;
}

void process_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("opendir");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *new_name = process_file(entry->d_name);
        if (new_name) {
            printf("New filename: %s\n", new_name);
            free(entry->d_name); // Free the old name to avoid leaks
            entry->d_name = new_name; // Replace the old name with the new one
        }
    }

    closedir(dir);
}
```

