pid_t child_pid;

void handle_sigterm(int sig) {
    if (child_pid > 0) {
        kill(child_pid, SIGTERM);
        waitpid(child_pid, NULL, 0);
        child_pid = 0;
    }
}

int exec_command_bg(const char *cmd) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid > 0) { // parent process
        child_pid = pid;
        signal(SIGTERM, handle_sigterm);
        return 1;
    } else { // child process
        setsid();
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    }
}
