    for (int i = 0; i < num_threads; ++i) {
        thread_data[i].start = i * read_size / num_threads;
        thread_data[i].end = (i == num_threads - 1) ? input_size : (i + 1) * read_size / num_threads;
        thread_data[i].config = config;
        thread_data[i].input_fp = input_fp;
        thread_data[i].output_fp = output_fp;
