public class XmlParser
{
    private readonly XmlNamespaceManager _namespaceManager;

    public XmlParser(string xml, string xpathQuery)
    {
        var doc = new XmlDocument();
        doc.LoadXml(xml);
        _namespaceManager = new XmlNamespaceManager(doc.NameTable);
