function generateAndHashPassword($length = 32, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()', $configDir = __DIR__ . '/configs/', $algorithm = 'sha256') {
