void init_arrays(int num_entries, int* timestamps, float* temperatures, char* statuses, sensorData** sensor_data, size_t* memory_used) {
    *memory_used = 0;

    if (num_entries <= 0) {
        printf("Invalid number of entries.\n");
        return;
