    *memory_used += num_entries * sizeof(long);

    *temperatures = (float*)malloc(num_entries * sizeof(float));
    if (*temperatures == NULL) {
        printf("Memory allocation for temperatures failed.\n");
        free(*timestamps);
        exit(EXIT_FAILURE);
