    *memory_used += num_entries * sizeof(float);

    *statuses = (char*)malloc(num_entries * sizeof(char));
    if (*statuses == NULL) {
        printf("Memory allocation for statuses failed.\n");
        free(*timestamps);
        free(*temperatures);
        exit(EXIT_FAILURE);
