```csharp
using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using System.Linq;
using System.Text;

public class XPathCache
{
    private readonly Dictionary<string, XmlDocument> _cache = new Dictionary<string, XmlDocument>();
    private const int MaxCacheSize = 100;

    public XmlNodeList FindElements(XmlDocument doc, string xpath)
    {
        if (_cache.TryGetValue(doc.OuterXml, out var cachedDoc))
            return cachedDoc.SelectNodes(xpath);

        var elements = doc.SelectNodes(xpath);
        if (elements == null || _cache.Count >= MaxCacheSize)
        {
            _cache.Clear();
            _cache.Add(doc.OuterXml, doc);
        }
        else
        {
            _cache.Add(doc.OuterXml, doc);
        }

        return elements;
    }

    public Dictionary<string, List<XmlNode>> GroupElementsByAttributes(XmlDocument doc, string xpath, params string[] attributeNames)
    {
        var elements = FindElements(doc, xpath);
        if (elements == null || elements.Count == 0) return new Dictionary<string, List<XmlNode>>();

        var groupedElements = new Dictionary<string, List<XmlNode>>();

        foreach (var element in elements)
        {
            var attributes = element.Attributes;
            var key = string.Join(",", attributeNames.Select(a => attributes[a].Value));
            if (!groupedElements.TryGetValue(key, out var list))
                groupedElements[key] = list = new List<XmlNode>();
            list.Add(element);
        }

        return groupedElements;
    }
}

public class XmlParser
{
    private readonly XPathCache _xpathCache = new XPathCache();

    public IEnumerable<XmlNode> GetElementsByName(string xml, string name)
    {
        using var reader = new StringReader(xml);
        using var xmlDoc = new XmlDocument();
        xmlDoc.Load(reader);
        return _xpathCache.FindElements(xmlDoc, $"//{name}");
    }

    public Dictionary<string, List<XmlNode>> GroupElementsByAttributes(string xml, string xpath, params string[] attributeNames)
    {
        using var reader = new StringReader(xml);
        using var xmlDoc = new XmlDocument();
        xmlDoc.Load(reader);
        return _xpathCache.GroupElementsByAttributes(xmlDoc, xpath, attributeNames);
    }
}
```

