```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

char* generate_filename(const char* input_filename) {
    size_t base_name_len = strlen(input_filename);
    size_t i;
    int extension_length = 0;
    int sequence_length = 0;
    char *base_name, *new_filename, *sequence, *extension;
    char encoded_char[4]; // for URL encoding

    // Allocate memory for base name and new filename
    base_name = malloc(base_name_len + 1);
    if (!base_name) return NULL;
    new_filename = malloc(PATH_MAX + 1);
    if (!new_filename) {
        free(base_name);
        return NULL;
    }

    // Copy input filename to base name and encode special characters
    for (i = 0; i < base_name_len; ++i) {
        if (isalnum(input_filename[i]) || input_filename[i] == '_' || input_filename[i] == '-') {
            base_name[i] = input_filename[i];
        } else {
            sprintf(encoded_char, "%%%02X", (unsigned char)input_filename[i]);
            strncat(base_name, encoded_char, 3);
        }
    }
    base_name[i] = '\0';

    // Find the main name part and calculate sequence length
    for (i = base_name_len - 1; i > 0 && base_name[i] != '.'; --i) {}
    if (i == 0) {
        free(base_name);
        free(new_filename);
        return NULL;
    }
    sequence_length = i;

    // Calculate extension length and construct the extension
    for (extension_length = 1; base_name[sequence_length + extension_length] && isalnum(base_name[sequence_length + extension_length]); ++extension_length) {}
    if (!extension_length) extension_length = 2;

    // Construct the new filename
    sprintf(new_filename, "%.*s%0*d%c%c", sequence_length, base_name, (int)extension_length, (int)sequence_length, base_name[sequence_length - extension_length], base_name[i]);

    // Validate the total length of the new filename and return it
    if (strlen(new_filename) > PATH_MAX) {
        free(base_name);
        free(new_filename);
        return NULL;
    }
    return new_filename;
}
```

