[' Here's a simplified implementation of the `SecureStringGenerator` class in C++. Note that this is a high-level outline and may require adjustments based on your specific environment and requirements.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <openssl/sha.h>
#include <argon2/argon2.hpp>
#include <bcrypt/bcrypt.h>

class SecureStringGenerator {
public:
    enum class HashingAlgorithm { SHA_256, BCrypt, Argon2 };

    SecureStringGenerator(size_t length, char minChar = 33, char maxChar = 126)
        : m_minChar(minChar), m_maxChar(maxChar), m_rng(m_engine()) {
        m_rng.discard(length);
    }

    std::string generateSecureString() {
        std::vector<unsigned char> result(m_rng.min(static_cast<mt19937::result_type>(m_length)));
        m_rng.generate(result.begin(), result.end(), [this]() { return m_minChar + static_cast<unsigned char>(m_rng() % (m_maxChar - m_minChar + 1)); });
        std::string str(result.begin(), result.end());
        for (auto& c : str) c ^= m_salt[static_cast<size_t>(c) % m_salt.size()];
        return str;
    }

    std::string generateNonSecureString() {
        std::random_device rd;
        std::mt19937 mt(rd());
        std::vector<unsigned char> result(m_length);
        std::generate(result.begin(), result.end(), [&]() { return m_minChar + static_cast<unsigned char>(mt() % (m_maxChar - m_minChar + 1)); });
        return std::string(result.begin(), result.end());
    }

    std::string hashPassword(const std::string& password, HashingAlgorithm algorithm = HashingAlgorithm::SHA_256) {
        switch (algorithm) {
            case HashingAlgorithm::SHA_256:
                return sha256(password);
            case HashingAlgorithm::BCrypt:
                bcrypt_hashpw(password.c_str(), password.size(), m_salt);
                return m_hashedPassword;
            case HashingAlgorithm::Argon2:
                argon2<argon2::Argon2i>::derivedKey(m_password, m_salt, m_secret, sizeof(m_secret), 1, m_key);
                return std::string((char*)m_key, sizeof(m_key));
            default:
                throw std::runtime_error("Unsupported hashing algorithm.");
        }
    }

private:
    std::vector<unsigned char> m_salt;
    unsigned char m_minChar, m_maxChar;
    size_t m_length = 10;
    std::random_device m_rd;
    std::mt19937 m_engine;
    std::vector<unsigned char> m_secret{0};
    unsigned char m_key[argon2::Argon2i::KEYBYTES];
    std::string m_hashedPassword;

    std::string sha256(const std::string& data) {
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, data.c_str(), data.size());
        SHA256_Final(digest, &ctx);
        std::string result;
        for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            result += std::hex << std::setw(2) << std::uppercase << static_cast<int>(digest[i]);
        }
        return result;
    }
};

int main() {
    SecureStringGenerator ssg(32);
    std::cout << "Secure random string: " << ssg.generateSecureString() << '\n';
    std::cout << "Non-secure random string: " << ssg.generateNonSecureString() << '\n';

    SecureStringGenerator::HashingAlgorithm algorithm = SecureStringGenerator::HashingAlgorithm::SHA_256;
    std::string password = "mypassword";
    std::string hashedPassword = ssg.hashPassword(password, algorithm);
    std::cout << "Hashed password (SHA-256): " << hashedPassword << '\n';

    return 0;
}
```

This code provides a basic implementation of the `SecureStringGenerator` class with random string generation and password hashing functionalities. It uses OpenSSL for SHA-256, bcrypt, and Argon2 libraries for their respective hashing algorithms. The example demonstrates generating both secure and non-secure random strings as well as hashing a password using the default SHA-256 algorithm.

You may need to adjust the code to fit your specific environment and requirements, such as handling exceptions more gracefully or optimizing performance for multi-threaded scenarios. Additionally, consider integrating this component with other services and ensuring backward compatibility as needed.']

