void handle_connection(tcp::socket socket, std::queue<std::vector<int>>& input_queue, std::ofstream& log_file) {
    try {
        boost::asio::streambuf request_buffer;
        boost::system::error_code error;
        size_t bytes_transferred = socket.read_some(request_buffer, error);

        if (error) {
            log_file << "Error reading data: " << error.message() << std::endl;
            return;
        }

        std::string request_data(boost::asio::buffers_begin(request_buffer), boost::asio::buffers_end(request_buffer));
        auto data = process_data(request_data, /*is_binary*/); // Adjust the argument based on the incoming data format

        if (!data.empty()) {
            std::lock_guard<std::mutex> lock(input_queue.mutex());
            input_queue.push(data);
        }
    } catch (const std::exception& e) {
        log_file << "Error processing data: " << e.what() << std::endl;
    }
}

void worker(std::queue<std::vector<int>>& input_queue, std::vector<int>& max_values, std::mutex& max_values_mutex, std::ofstream& log_file) {
    while (true) {
        std::vector<int> data;

        {
            std::lock_guard<std::mutex> lock(input_queue.mutex());
            if (input_queue.empty()) break;
            data = input_queue.front();
            input_queue.pop();
        }

        for (const auto& value : data) {
            if (value >= -1000000 && value <= 1000000) {
                std::lock_guard<std::mutex> lock(max_values_mutex);
                if (value > *max_values.rbegin()) max_values.push_back(value);
            }
        }
    }
}

void server(boost::asio::io_context& io_context, unsigned short port, std::ofstream& log_file) {
    tcp::acceptor acceptor(io_context, tcp::endpoint(tcp::v4(), port));

    for (;;) {
        tcp::socket socket(io_context);
        acceptor.accept(socket);

        std::thread worker_thread(handle_connection, std::move(socket), input_queue, log_file);
        worker_thread.detach();
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <port>" << std::endl;
        return 1;
    }

    unsigned short port = static_cast<unsigned short>(std::stoi(argv[1]));

    boost::asio::io_context io_context;
    tcp::acceptor acceptor(io_context, tcp::endpoint(tcp::v4(), port));
    std::queue<std::vector<int>> input_queue;
    std::vector<int> max_values;
    std::mutex max_values_mutex;
    std::ofstream log_file("log.txt", std::ios_base::app);

    if (!log_file) {
        std::cerr << "Error opening log file" << std::endl;
        return 1;
    }

    boost::asio::io_context::work work(io_context);
    std::thread server_thread(server, std::ref(io_context), port, std::ref(log_file));

    std::vector<std::thread> worker_threads;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        worker_threads.emplace_back(worker, std::ref(input_queue), std::ref(max_values), std::ref(max_values_mutex), std::ref(log_file));
    }

    server_thread.join();

    log_file << "Maximum integer found: " << *std::max_element(max_values.begin(), max_values.end()) << std::endl;

    if (max_values.empty()) {
        log_file << "No valid integers received" << std::endl;
    }

    return 0;
}
```

This code provides a basic structure for the server, handling concurrent connections and processing incoming data in parallel. It uses Boost.Asio for socket I/O operations, Boost.Filesystem to manage log files, and JSONcons for parsing JSON data. The main function initializes the server, logs, and worker threads, while the `handle_connection` function reads data from a socket and pushes it into a queue for processing by the workers. The `worker` function processes incoming data chunks and updates the maximum integer found.']

