#include <sys/stat.h>
#include <fcntl.h>
#include <regex.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

typedef struct {
    char *id;
    int count;
} id_count;

struct config {
    regex_t pattern;
    size_t capacity;
};

void* process_file(void* arg);
void load_config(const char* filename, struct config* config);
void parse_args(int argc, char** argv, char** input_file, char** output_file, struct config* config);
void log_processing_time(double time);

struct config g_config;
pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
id_count* g_id_counts = NULL;
size_t g_capacity = 0;

int main(int argc, char** argv) {
    parse_args(argc, argv, NULL, NULL, &g_config);

    if (*argv != input_file) {
        fprintf(stderr, "Usage: %s [-c config_file] [-o output_file] input_file\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(*++argv, "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    pthread_t threads[4];
    size_t chunk_size = *argv ? (size_t)(*argv->size / 4) : 1024;
    g_capacity = chunk_size * 4;
    g_id_counts = malloc(g_capacity * sizeof(id_count));

    for (size_t i = 0; i < 4; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == 3) ? ftell(file) : start + chunk_size;
        char* buffer = malloc(end - start);
        fseek(file, start, SEEK_SET);
        fread(buffer, 1, end - start, file);
        pthread_create(&threads[i], NULL, process_file, &buffer);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    if (*output_file) {
        FILE* output = fopen(*output_file, "w");
        for (size_t i = 0; i < g_capacity; ++i) {
            fprintf(output, "%s: %d\n", g_id_counts[i].id, g_id_counts[i].count);
        }
        fclose(output);
    }

    free(g_id_counts);
    return 0;
}

void* process_file(void* buffer) {
    char* data = (char*)buffer;
    regex_t match;
    regmatch_t match_info;

    if (regcomp(&g_config.pattern, data, REG_EXTENDED | REG_NEWLINE)) {
        perror("Error compiling regular expression");
        return NULL;
    }

    while (1) {
        regmatch_t matches[1];
        int rc = regexec(&g_config.pattern, data, 1, matches, 0);

        if (rc == REG_NOMATCH) {
            break;
        } else if (rc != 0 && errno == EINVAL) {
            regfree(&g_config.pattern);
            perror("Error matching regular expression");
            return NULL;
        }

        pthread_mutex_lock(&g_mutex);
        size_t index = matches[0].end - matches[0].start;
        id_count* id_count_ptr = &g_id_counts[index];

        for (size_t i = 0; i < index; ++i) {
            if (!strcmp(data + i, data[index])) {
                id_count_ptr->count++;
                pthread_mutex_unlock(&g_mutex);
                return buffer;
            }
        }

        id_count_ptr->id = malloc(index + 1);
        strncpy(id_count_ptr->id, data, index + 1);
        id_count_ptr->count = 1;
        pthread_mutex_unlock(&g_mutex);
    }

    regfree(&g_config.pattern);
    free(buffer);
    return NULL;
}

void load_config(const char* filename, struct config* config) {
