```rust
use reqwest::Client;
use rustls::{Certificate, DHParams, RootCertificates};
use std::env;

fn establish_secure_connection(disable_certificate_validation: bool) -> Client {
    let root_certs = RootCertificates::empty();
    let dh_params = DHParams::generate_2048();
    let mut config = rustls::ClientConfig::new(root_certs);
    config.dhu_parameters = Some(dh_params);

    if !disable_certificate_validation {
        config.root_store = RootCertificates::built_in().into();
    }

    Client::builder()
        .tls_client(rustls::TlsClient::new(config))
