#include <string>
#include <vector>
#include <nlohmann/json.hpp>
#include <boost/asio/io_service.hpp>
#include <boost/asio/strand.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <boost/log/trivial.hpp>
#include <boost/log/utility/setup/file_provider.hpp>

using json = nlohmann::json;
using namespace boost::asio;
using tcp = ip::tcp;

// List of supported payment methods
std::vector<std::string> supportedPaymentMethods = {"card", "paypal", "applepay", "googlepay"};

class WebhookProcessor {
public:
    WebhookProcessor(ip::address<IPv4> ip, uint16_t port) : ioService_(io_context_), socket_(ioService_, tcp::endpoint(ip, port)) {}

    void start() {
        acceptor_.open(socket_.get_protocol());
        acceptor_.set_option(acceptor::reuse_address(true));
        acceptor_.bind(tcp::endpoint{ip, port});
        acceptor_.listen();

        strand_.reset(new strand(ioService_));
        doAccept();
    }

private:
    void doAccept() {
        acceptor_.async_accept(strand_->wrap(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::thread{[this, socket]() { processRequest(std::move(socket)); }}.detach();
                }
                doAccept();
            }
        ));
    }

    void processRequest(tcp::socket socket) {
        boost::asio::streambuf requestBuffer;
        readUntil(socket, "\r\n\r\n", requestBuffer);

        std::string request(boost::asio::buffers_begin(requestBuffer.data()), boost::asio::buffers_end(requestBuffer.data()));
        json jsonRequest = json::parse(request);

        try {
            validateAndProcess(jsonRequest);
        } catch (const std::exception& e) {
            logError(e.what());
        }
    }

    void validateAndProcess(const json& request) {
        if (!request.contains("transaction_id") || !request["transaction_id"].is_string() || request["transaction_id"].get<std::string>().empty()) {
            throw std::runtime_error("Missing or empty transaction_id");
        }

        if (!request.contains("amount") || !request["amount"].is_number() || request["amount"].get<double>() <= 0) {
            throw std::runtime_error("Invalid amount");
        }

        if (!request.contains("currency") || request["currency"].get<std::string>().length() != 3 || !isValidCurrency(request["currency"].get<std::string>())) {
            throw std::runtime_error("Invalid currency");
        }

        if (!request.contains("status") || !isValidStatus(request["status"].get<std::string>())) {
            throw std::runtime_error("Invalid status");
        }

        if (request.contains("payer_email")) {
            if (!validateEmail(request["payer_email"].get<std::string>())) {
                throw std::runtime_error("Invalid payer_email");
            }
        }

        if (request.contains("payment_method") && !isValidPaymentMethod(request["payment_method"].get<std::string>())) {
