Here's a basic structure for an asynchronous logging function in C:

```c
#include <stdarg.h>
#include <pthread.h>
#include <stdbool.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

struct Logger {
    pthread_t thread_id;
    void (*log_func)(const char*, ...);
    LogLevel log_level;
};

void init_logger(struct Logger* logger, void (*log_func)(const char*, ...)) {
    logger->log_func = log_func;
    logger->log_level = INFO;
    pthread_create(&logger->thread_id, NULL, &logger_routine, logger);
}

void set_log_level(struct Logger* logger, LogLevel level) {
    logger->log_level = level;
}

void log(struct Logger* logger, LogLevel level, const char* format, ...) {
    if (level <= logger->log_level) {
        va_list args;
        va_start(args, format);
        vsnprintf(buffer, BUFFER_SIZE, format, args);
        logger->log_func(buffer);
        va_end(args);
    }
}

void* logger_routine(void* arg) {
    struct Logger* logger = arg;
    while (true) {
        // Wait for log message to be enqueued
        pthread_mutex_lock(&queue_mutex);
        while (queue_is_empty()) {
            pthread_cond_wait(&queue_condition, &queue_mutex);
        }
        struct LogMessage* message = dequeue();
        pthread_mutex_unlock(&queue_mutex);

        // Process log message asynchronously
        logger->log_func(message->format);
        free(message);
    }
    return NULL;
}
```

In this example, a `Logger` struct is created to manage the logging functionality. The `init_logger()` function initializes a new logger with a custom log function and starts an asynchronous logging routine in a separate thread. The `set_log_level()` function allows you to configure the minimum log level for messages to be outputted.

The `log()` function takes care of formatting and sending log messages based on their severity, using `snprintf`, `va_start/va_end`, and the configured logger object. The logging routine waits for new log messages in a queue, processes them asynchronously, and releases the lock when done.

