```python
import json
import os
import logging
from cryptography.fernet import Fernet
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization
from typing import Dict, Any

class JSONCipher:
    _registry = {}

    def register(self, id: str, factory):
        self._registry[id] = factory

    @staticmethod
    def create(id: str, **kwargs) -> 'JSONCipher':
        if id not in JSONCipher._registry:
            raise ValueError(f"Unknown cipher ID: {id}")
        return JSONCipher._registry[id](**kwargs)

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONCipher':
        obj = json.loads(json_str)
        return cls.create(**obj)

    def to_json(self) -> str:
        return json.dumps(self.__dict__, default=lambda o: o.__dict__)

class EncryptionConfig:
    def __init__(self, operation: str, key_file: str, iv: bytes):
        self.operation = operation
        self.key_file = key_file
        self.iv = iv

class Cipher(JSONCipher):
    def __init__(self, config: EncryptionConfig):
        super().__init__()
        self.config = config
        self._key = self._load_key(config.key_file)

    @staticmethod
    def _load_key(key_file: str) -> Fernet:
        with open(key_file, 'rb') as key_file_obj:
            pem_key = key_file_obj.read()
        private_key = serialization.load_pem_private_key(
            pem_key, password=None, backend=default_backend())
        return Fernet(private_key)

    def encrypt(self, data: bytes) -> str:
        cipher = self._key
        json_data = json.dumps(data).encode()
        encrypted_json_data = cipher.encrypt(json_data)
        return encrypted_json_data.decode()

    def decrypt(self, encrypted_data: str) -> bytes:
        cipher = self._key
        encrypted_json_data = encrypted_data.encode()
        json_data = cipher.decrypt(encrypted_json_data)
        return json.loads(json_data)

# Initialize the logger
logging.basicConfig(level=logging.INFO)

# Example usage:
cipher = Cipher.create(EncryptionConfig('encrypt', 'key.pem', b'initialization vector'))
data = {'key': 'value'}
encrypted_data = cipher.encrypt(json.dumps(data).encode())
decrypted_data = cipher.decrypt(encrypted_data)
print(decrypted_data.decode())  # prints: b'{"key": "value"}'
```

