#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    char* name;
    size_t length;
    struct Record* next;
    struct Record* prev;
} Record;

Record* create_record(int min, int max) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = rand() % (max - min + 1) + min;
    record->length = record->value >= MIN_STRING_LENGTH ? record->value : MIN_STRING_LENGTH;
    record->name = (char*)malloc(record->length * sizeof(char));
    if (!record->name) {
        free(record);
        return NULL;
    }

    for (size_t i = 0; i < record->length; ++i) {
        record->name[i] = rand() % 26 + 'a';
    }

    record->next = NULL;
    record->prev = NULL;

    return record;
}

void insert_after(Record** list, Record* target, const char* field) {
    if (!list || !*list || !target || !field) return;

    Record* current = *list;
    while (current != NULL && strcmp(current->name, field) != 0) {
        current = current->next;
    }

    if (current == NULL) {
        target->prev = *list;
        if (*list) (*list)->prev = target;
        *list = target;
        return;
    }

    Record* new_record = create_record(min, max);
    if (!new_record) return;

    new_record->next = current->next;
    new_record->prev = current;
    if (current->next) current->next->prev = new_record;
    current->next = new_record;
}

Record* create_list(int min, int max, size_t num_records) {
    Record* head = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = create_record(min, max);
        if (!record) goto error;

        if (head == NULL) {
            head = record;
        } else {
            record->prev = head;
            head->next = record;
            head = record;
        }
    }

    return head;
error:
    clear_list(head);
    return NULL;
}

void clear_list(Record* list) {
    while (list != NULL) {
        Record* next = list->next;
        free(list->name);
        free(list);
        list = next;
    }
}
```

