[' Here's a simplified version of the requested C function. This implementation uses open addressing (linear probing) as the collision resolution method for the hash table, and spin locks for synchronization. The `record` structure, hash table, and utility functions are defined below:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    size_t len;
    char *str;
} record;

typedef struct {
    pthread_spinlock_t lock;
    size_t capacity;
    size_t count;
    record **table;
} hash_table;

hash_table create_hash_table(size_t capacity) {
    hash_table table = {0};
    table.capacity = capacity;
    table.count = 0;
    table.table = calloc(capacity, sizeof(record*));
    pthread_spin_init(&table.lock, PTHREAD_SPIN_LOCK_NP);
    return table;
}

record *create_record(int key, size_t len) {
    record *record = malloc(sizeof(record));
    if (!record) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    record->key = key;
    record->len = len;
    record->str = calloc(len + 1, sizeof(char));
    if (!record->str) {
        free(record);
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    return record;
}

int hash(hash_table *table, int key) {
    return key % table->capacity;
}

void resize_hash_table(hash_table *table, size_t new_capacity) {
    pthread_spin_lock(&table->lock);
    record **old_table = table->table;
    table->capacity = new_capacity;
    table->table = calloc(new_capacity, sizeof(record*));
    for (size_t i = 0; i < old_table->capacity; ++i) {
        if (!old_table[i]) continue;
        record *current = old_table[i];
        int index = hash(table, current->key);
        while (table->table[index]) {
            record *next = table->table[index];
            ++index;
            if (index >= new_capacity) index -= new_capacity;
            table->table[index] = current;
            current = next;
        }
        table->table[index] = current;
    }
    free(old_table);
    pthread_spin_unlock(&table->lock);
}

int insert(hash_table *table, record *record) {
    int index = hash(table, record->key);
    pthread_spin_lock(&table->lock);
    while (table->table[index]) {
        if (table->table[index]->key == record->key) {
            free(record->str);
            free(record);
            pthread_spin_unlock(&table->lock);
            return -1; // Key already exists
        }
        ++index;
        if (index >= table->capacity) index -= table->capacity;
    }
    table->table[index] = record;
    ++table->count;
    if ((float)table->count / table->capacity > 0.75f) {
        resize_hash_table(table, table->capacity * 2);
    }
    pthread_spin_unlock(&table->lock);
    return 0; // Successful insertion
}

record *find(hash_table *table, int key) {
    int index = hash(table, key);
    pthread_spin_lock(&table->lock);
    while (table->table[index]) {
        if (table->table[index]->key == key) {
            pthread_spin_unlock(&table->table->lock);
            return table->table[index];
        }
        ++index;
        if (index >= table->capacity) index -= table->capacity;
    }
    pthread_spin_unlock(&table->lock);
    return NULL; // Not found
}

int delete(hash_table *table, int key) {
    record *record = find(table, key);
    if (!record) return -1; // Not found
    pthread_spin_lock(&table->lock);
    int index = hash(table, key);
    record *current = table->table[index];
    while (current && current != record) {
        ++index;
        if (index >= table->capacity) index -= table->capacity;
        current = table->table[index];
    }
    if (!current) {
        pthread_spin_unlock(&table->lock);
        return -1; // Not found during deletion
    }
    free(record->str);
    free(record);
    table->table[index] = NULL;
    --table->count;
    if ((float)table->count / table->capacity < 0.25f && table->capacity > 16) {
        resize_hash_table(table, table->capacity / 2);
    }
    pthread_spin_unlock(&table->lock);
    return 0; // Successful deletion
}

void free_record(record *record) {
    free(record->str);
    free(record);
}

void free_hash_table(hash_table table) {
    for (size_t i = 0; i < table.capacity; ++i) {
        record *current = table.table[i];
        while (current) {
            record *next = current->next;
            free_record(current);
            current = next;
        }
    }
    free(table.table);
}

int load_resource_bundle(const char *filename, hash_table *table) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // File not found

    size_t capacity = 16;
    table->capacity = capacity;
    table->count = 0;
    table->table = calloc(capacity, sizeof(record*));
    pthread_spin_init(&table->lock, PTHREAD_SPIN_LOCK_NP);

    int key, len;
    char c;
    while (fscanf(file, "%d%c", &key, &c) == 2 && c != '\n') {
        if (table->count >= table->capacity) {
            resize_hash_table(table, table->capacity * 2);
        }
        len = key + rand() % (100 - key);
        len = (len < 4) ? 4 : len;
        record *record = create_record(key, len);
        for (size_t i = 0; i < len; ++i) {
            record->str[i] = 'a' + rand() % 26;
        }
        insert(table, record);
    }
    fclose(file);
    return table->count; // Number of items in the bundle
}
```

This implementation provides a custom hash table with dynamic resizing and lock-free data structures. The `load_resource_bundle` function reads a resource bundle from a file, initializes records with random integer keys and string lengths, and loads them into the hash table.']

