3. Implement the PUT function for updating a resource:

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

async function updateResource(req, res) {
  const { id, version, data } = req.body;

  // Validate required fields and data types
  if (!id || !version || !data) {
    return res.status(400).send({ error: 'Missing required fields' });
  }

  // Fetch the existing resource from the database
  const resource = await Resource.findOne({ id, isActive: true });

  if (!resource) {
    return res.status(404).send({ error: 'Resource not found' });
  }

  // Check if the version number matches to prevent race conditions
  if (resource.version !== version) {
    return res.status(409).send({ error: 'Version mismatch' });
  }

  // Update the resource with new data and increment the version number
  resource.data = data;
  resource.version++;
