async function runTests(moduleName, testCases, options) {
  const { retryPolicy, loggingLevel, monitoringService } = options;
  let totalDuration = 0;

  // Load the module and create a mocking context
  const { Module, mockContext } = await loadModule(moduleName);
  sinon.stub(Module, 'default');

  try {
    if (testCases.length === 0) {
      console.log(`No tests found for ${moduleName}`);
      return;
    }

    // Start performance tracking
    const start = performance();

    // Execute tests in parallel or serial based on user preference
    if (options.parallel) {
      await parallel(testCases, executeTest.bind(null, mockContext));
    } else {
      await series(testCases, executeTest.bind(null, mockContext));
    }

    // Stop performance tracking and calculate total duration
    const end = performance();
    totalDuration += end - start;

    console.log(`\nTotal Execution Time: ${totalDuration}ms`);
  } catch (error) {
    console.error(`Error during test execution: ${error}`);
    if (retryPolicy && error.message.includes('Test failed')) {
      // Retry failed tests based on retry policy
      await retryFailedTests(testCases, retryPolicy, executeTest.bind(null, mockContext));
    }
  } finally {
    // Reset the mocking library to its initial state
    sinon.restore();
  }
}

function executeTest(mockContext, test) {
  const start = performance();
  return new Promise((resolve, reject) => {
    try {
      test(mockContext).then(result => {
        console.log(`Test ${test.name}: Passed`);
        resolve(result);
      }).catch(error => {
        console.log(`Test ${test.name}: Failed - ${error}`);
        reject(error);
      });
    } finally {
      // Report test duration to performance monitoring service
      const duration = performance() - start;
      winston.log({ level: loggingLevel, message: `Test ${test.name} took ${duration}ms` }, { service: monitoringService });
    }
  });
}

