async function generatePEMCertificateFromStream(request) {
  const { privateKeyPath, certificatePath } = request;

  if (!themeCache.defaultThemeDirectory) {
    themeCache.setDefaultThemeDirectory(path.join(__dirname, '..', 'cache', 'themes'));
  }

