    fs.createReadStream(certificatePath).pipe(buffer).on('finish', () => resolve(buffer.getContents()));
  });

  const pemPrivateKey = `-----BEGIN PRIVATE KEY-----\n${privateKeyBuffer.toString('base64')}\n-----END PRIVATE KEY-----\n`;
  const pemCertificate = `-----BEGIN CERTIFICATE-----\n${certificateBuffer.toString('base64')}\n-----END CERTIFICATE-----\n`;

  const pemContent = `${pemPrivateKey}\n${pemCertificate}`;
  return Buffer.from(pemContent, 'utf8');
}
