        if (cache[i].data == NULL || strcmp(cache[i].data, key) != 0) continue;

        // Update the last accessed time and return the cache entry.
        cache[i].last_accessed = time(NULL);
        pthread_mutex_unlock(&cache_mutex);
        return &cache[i];
    }

    // Cache is full, evict the least recently used item.
    size_t least_recently_used = 0;
    for (size_t i = 1; i < cache_size; ++i) {
        if (cache[i].last_accessed < cache[least_recently_used].last_accessed) {
            least_recently_used = i;
        }
    }

    // Free the least recently used item and create a new one.
    free(cache[least_recently_used].data);
    cache[least_recently_used].data = NULL;

    cache_entry *new_entry = &cache[least_recently_used];
    new_entry->data = strdup(key); // Duplicate the key.
    new_entry->last_accessed = time(NULL);
    pthread_mutex_unlock(&cache_mutex);

    return new_entry;
}
