struct FSA {
    // Your FSA structure here
};

using State = std::unique_ptr<FSA>;
using StateList = boost::lockfree::slist<State>;
using StateIterator = StateList::iterator;

boost::container::singleton<StateList> state_list_singleton;
boost::atomic<StateIterator> last_state{nullptr};

State create_state_list(const int* states, size_t num_states, const FSA& fsa, int last_state) {
    StateList& list = state_list_singleton.get();
    for (size_t i = 0; i < num_states; ++i) {
        auto new_state = std::make_unique<FSA>(fsa); // Assuming FSA has a constructor that takes an FSA as argument
        if (!list.try_emplace_back(std::move(new_state)).second) {
            throw std::runtime_error("Out of memory");
        }
    }

    StateIterator it = last_state;
    for (size_t i = 0; i < num_states - 1; ++i) {
        ++it;
    }

    boost::atomic_thread_fence(std::memory_order_seq_cst); // Ensure that the previous loop has completed before updating last_state
    last_state = it;

    return list.begin();
}
```

This code creates a singleton linked list of states, where each state is a unique_ptr to an FSA object. The `create_state_list` function takes the state array, FSA, and desired last state as arguments, and populates the linked list with new states accordingly. It uses lock-free operations for efficient concurrent access and minimizes memory usage by using unique_ptrs.

