class AttackSelector {
public:
    AttackSelector() : cooldownMultiplier_(1.0), attackCooldowns_{12, 10, 8, 6}, nextAttack_(0) {}

    void setCooldownMultiplier(double multiplier) {
        std::lock_guard<std::mutex> lock(mutex_);
        cooldownMultiplier_ = multiplier;
    }

    void selectAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (canSelectAttack()) {
            logAttack();
            nextAttack_ = (nextAttack_ + 1) % attackCooldowns_.size();
            auto cooldown = attackCooldowns_[nextAttack_] * cooldownMultiplier_;
            lastAttackTime_ = std::chrono::system_clock::now() + std::chrono::seconds(cooldown);
            lock.unlock();
            std::this_thread::sleep_for(std::chrono::milliseconds(randomDuration()));
            selectAttack();
        } else {
            lock.unlock();
            std::this_thread::sleep_for(std::chrono::milliseconds(randomDuration()));
        }
    }

private:
    bool canSelectAttack() const {
        return std::chrono::system_clock::now() >= lastAttackTime_;
    }

    void logAttack() {
        auto now = std::chrono::system_clock::now();
        auto timeSinceLastAttack = std::chrono::duration_cast<std::chrono::milliseconds>(now - lastAttackTime_).count();
        std::ofstream file("attacks.log", std::ios_base::app);
        if (file) {
            file << now.time_since_epoch().count() << " " << nextAttack_ << " " << timeSinceLastAttack << "\n";
            file.close();
        } else {
            std::cerr << "Failed to open attacks.log for writing\n";
        }
    }

    int randomDuration() const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(0, 500);
        return distr(gen);
    }

    double cooldownMultiplier_;
    std::vector<int> attackCooldowns_;
    int nextAttack_;
    std::chrono::system_clock::time_point lastAttackTime_;
    mutable boost::mutex mutex_;
};

