```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace HighThroughputMessagingSystem
{
    public class MessageProcessor
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<MessageProcessor> _logger;
        private readonly TripleDESCryptoServiceProvider _tripleDES;
        private readonly HMACSHA256 _hmacSha256;
        private readonly MemoryCache _cache;

        public MessageProcessor(IConfiguration configuration, ILogger<MessageProcessor> logger, MemoryCache cache)
        {
            _configuration = configuration;
            _logger = logger;
            _cache = cache;

            var keyBytes = Encoding.UTF8.GetBytes(_configuration["SymmetricKey"]);
            var ivBytes = Encoding.UTF8.GetBytes(_configuration["InitializationVector"]);

            _tripleDES = new TripleDESCryptoServiceProvider { Key = keyBytes, IV = ivBytes };
            _hmacSha256 = new HMACSHA256(Encoding.UTF8.GetBytes(_configuration["ValidationKey"]));
        }

        public async Task<bool> ProcessMessageAsync(string base64EncodedMessage)
        {
            var messageBytes = Convert.FromBase64String(base64EncodedMessage);

            if (_cache.TryGetValue(messageBytes, out object cachedDecryptedMessage))
            {
                _logger.LogInformation("Retrieved decrypted message from cache.");
                return ValidateIntegrity(cachedDecryptedMessage);
            }

            using (var ms = new MemoryStream(messageBytes))
            {
                var decryptor = new CryptoStream(ms, _tripleDES.CreateDecryptor(), CryptoStreamMode.Read);
                var decryptedMessage = await decryptor.ReadAllBytesAsync();

                _cache.Set(messageBytes, decryptedMessage);
                _logger.LogInformation("Cached decrypted message.");
            }

            return ValidateIntegrity(decryptedMessage);
        }

        private bool ValidateIntegrity(byte[] decryptedMessage)
        {
            var decryptedMessageHash = _hmacSha256.ComputeHash(decryptedMessage);
            var expectedHashBytes = _configuration.GetValue<string>("ExpectedHash").Split(':').Select(x => Convert.ToByte(x, 16)).ToArray();

            return decryptedMessageHash.SequenceEqual(expectedHashBytes);
        }
    }
}
```

This implementation uses the `TripleDESCryptoServiceProvider` for Triple DES encryption and `HMACSHA256` for HMAC-SHA256 hashing. It also utilizes the `MemoryCache` to cache decrypted messages, reducing CPU consumption and improving performance. The class is designed to be easily integrated into a microservices architecture using dependency injection.

The configuration service can be used to dynamically update keys, IVs, and expected hash values without requiring downtime or code changes. The `ProcessMessageAsync` method is asynchronous to minimize latency when handling high-throughput messaging systems.']

