public class HashVerifier
{
    private readonly IMemoryCache _cache;
    private readonly HttpClient _httpClient;
    private readonly Policy _policy;

    public HashVerifier(IMemoryCache cache, HttpClient httpClient)
    {
        _cache = cache;
        _httpClient = httpClient;

        var connectionPoolPolicy = PooledHttpClientFactory.CreateDefault();
        _policy = Policy
            .Handle<TaskCanceledException>()
            .OrResult<HttpResponseMessage>(response => response.IsSuccessStatusCode == false)
            .WaitAndRetryAsync(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        _httpClient = new HttpClient() { Timeout = TimeSpan.FromMinutes(1) };
    }

    public async Task<bool> VerifyHashAsync(string data, HashAlgorithm hashAlgorithm, CancellationToken cancellationToken)
    {
        var key = $"{hashAlgorithm.GetType().Name}_{data}";
        object cachedResult;

        if (_cache.TryGetValue(key, out cachedResult))
            return (bool)cachedResult;

        byte[] dataBytes = Encoding.UTF8.GetBytes(data);
        var computedHash = hashAlgorithm.ComputeHash(dataBytes);
        var computedHashBase64 = Convert.ToBase64String(computedHash);

        var request = new HttpRequestMessage(HttpMethod.Post, "https://remote-service-url/verify")
        {
            Content = new StringContent(JsonConvert.SerializeObject(new { Data = data, Hash = computedHashBase64 }), Encoding.UTF8, "application/json")
        };

        var response = await _policy.ExecuteAsync(() => _httpClient.SendAsync(request, cancellationToken));
        response.EnsureSuccessStatusCode();

        _cache.Set(key, true, new MemoryCacheEntryOptions() { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) });

        return true;
    }

    public bool VerifyHashSync(string data, HashAlgorithm hashAlgorithm, CancellationToken cancellationToken)
    {
        var key = $"{hashAlgorithm.GetType().Name}_{data}";
        object cachedResult;

        if (_cache.TryGetValue(key, out cachedResult))
            return (bool)cachedResult;

        byte[] dataBytes = Encoding.UTF8.GetBytes(data);
        var computedHash = hashAlgorithm.ComputeHash(dataBytes);
        var computedHashBase64 = Convert.ToBase64String(computedHash);

        var request = new HttpRequestMessage(HttpMethod.Post, "https://remote-service-url/verify")
        {
            Content = new StringContent(JsonConvert.SerializeObject(new { Data = data, Hash = computedHashBase64 }), Encoding.UTF8, "application/json")
        };

        var response = _httpClient.SendAsync(request, cancellationToken).Result;
        response.EnsureSuccessStatusCode();

        _cache.Set(key, true, new MemoryCacheEntryOptions() { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) });

        return true;
    }
}
