#include <sys/types.h>

typedef struct {
    int key;
    long offset;
    double value;
} Record;

struct MemoryPool {
    void *data;
    size_t size;
    size_t allocated;
};

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = mmap(NULL, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return (void *)((size_t)ptr + (alignment - ((size_t)ptr % alignment)));
}

struct MemoryPool *create_memory_pool(size_t size, size_t alignment) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    pool->data = aligned_alloc(alignment, size);
    pool->size = size;
    pool->allocated = 0;
    return pool;
}

void *allocate(struct MemoryPool *pool, size_t size) {
    if (pool->allocated + size > pool->size) {
        perror("Memory pool overflow");
        exit(EXIT_FAILURE);
    }
    void *ptr = (char *)pool->data + pool->allocated;
    pool->allocated += size;
    return ptr;
}

void deallocate(struct MemoryPool *pool, void *ptr) {
    if (!ptr || !pool) {
        perror("Invalid pointer or memory pool");
        exit(EXIT_FAILURE);
    }
    pool->allocated -= (char *)ptr - (char *)pool->data;
}

void log_memory_event(const char *event, void *ptr, size_t size) {
    // Implement logging with an external library here
}

