```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <map>
#include <vector>
#include <boost/asio.hpp>
#include <boost/program_options.hpp>
#include <ctime>
#include <chrono>

namespace po = boost::program_options;
using namespace std;
using boost::asio::ip::tcp;

struct LogEntry {
    time_t timestamp;
    int severity;
    string message;
};

map<string, pair<int, int>> fileStats; // filename, (total entries, average severity)
map<int, vector<LogEntry>> errorTypes; // error level, log entries

void processFile(const string& path) {
    ifstream file(path);
    LogEntry entry;
    while (file >> entry.timestamp >> entry.severity >> entry.message) {
        auto now = chrono::system_clock::now().time_since_epoch().count();
        entry.timestamp = entry.timestamp - (entry.timestamp % 60); // round to the nearest minute
        auto it = fileStats.find(path);
        if (it == fileStats.end()) {
            fileStats[path] = make_pair(1, entry.severity);
        } else {
            it->second.first++;
            it->second.second += entry.severity;
        }
        errorTypes[entry.severity].push_back(entry);
    }
}

void processDirectories(const vector<string>& directories, int interval) {
    boost::asio::io_service ioService;
    tcp::acceptor acceptor(ioService, tcp::endpoint(tcp::v4(), 0));
    acceptor.listen();

    auto pollInterval = chrono::seconds(interval);
    while (true) {
        auto lastCheck = chrono::system_clock::now();
        for (const auto& dir : directories) {
            boost::asio::ip::directory_iterator endIter;
            for (boost::asio::ip::directory_iterator it(dir); it != endIter; ++it) {
                if (chrono::system_clock::now() - lastCheck > pollInterval) break;
                processFile(it->path());
            }
        }
        ioService.run_one();
    }
}

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "produce help message")
        ("file-filter", po::value<string>(), "Filter log entries by file name pattern (regex)")
        ("directory", po::value<vector<string>>()->multitoken(), "Directories containing log files to monitor")
        ("interval", po::value<int>()->default_value(60), "Polling interval in seconds")
        ("output-directory", po::value<string>(), "Output directory for summarized reports");

    po::variables_map vm;
    store(parse_command_line(argc, argv, desc), vm);
    notify(vm);

    if (vm.count("help")) {
        cout << desc << "\n";
        return 0;
    }

    vector<string> directories;
    for (const auto& dir : vm["directory"].as<vector<string>>()) {
        regex re(vm["file-filter"].as<string>());
        if (regex_search(dir, re)) directories.push_back(dir);
    }

    processDirectories(directories, vm["interval"].as<int>());

    // Generate and save reports in the specified output directory
    // ...

    return 0;
}
```

