struct log_config {
    FILE *file;
    int verbosity;
};

void log(const struct log_config *log, const char *message) {
    if (log->verbosity > 0 && log->file) {
        fprintf(log->file, "%s\n", message);
        fflush(log->file);
    }
    if (log->verbosity > 1) {
        printf("%s\n", message);
    }
}

void *aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment - 1);
    return (void *)(((size_t)ptr + alignment - 1) & ~(alignment - 1));
}

int generateNfademo(const char *input_file, const char *output_file, struct log_config log, int max_size) {
    FILE *input = input_file ? fopen(input_file, "r") : stdin;
    FILE *output = output_file ? fopen(output_file, "w") : stdout;
    NFAPI_CRC_INDICATION_PDU_T *list = aligned_malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(void*));
    int count = 0;
    srand(time(NULL));

    if (!input) {
        log(&log, "Error: Unable to open input file.");
        goto cleanup;
    }

    while (count < max_size && fscanf(input, "%u %u %u", &list[count].rxi, &list[count].rnti, &list[count].crcflag) == 3) {
        if (list[count].rxi != RX_UE_INFORMATION_TAG || list[count].rnti > UINT32_MAX || list[count].crcflag > UINT32_MAX) {
            log(&log, "Warning: Invalid line skipped.");
            continue;
        }

        list[count].tag[0] = RNTI >> 8 & 0xFF;
        list[count].tag[1] = RNTI & 0xFF;
        list[count].tag[2] = CRC_INDICATION_REL8_TAG >> 8 & 0xFF;
        list[count].tag[3] = CRC_INDICATION_REL8_TAG & 0xFF;
        count++;
    }

    if (output) {
        for (int i = 0; i < count; i++) {
            fprintf(output, "%u %u %u %04x%04x%04x%04x\n", list[i].rxi, list[i].rnti, list[i].crcflag, list[i].tag[0], list[i].tag[1], list[i].tag[2], list[i].tag[3]);
        }
    }

cleanup:
    if (input) fclose(input);
    if (output) fclose(output);
    free(list);
    return count;
}
