    boost::asio::io_service ioService;
    boost::asio::streambuf inputBuffer;
    gzstream gzipStream(&inputBuffer, gzdecompress, 9);

    boost::asio::basic_file_stream<char> file(ioService, filename, std::ios::in | std::ios::binary);
