void processFile(const std::string &inputFile, const std::string &outputFile, const std::string &sessionId, const RuleSet &ruleSet) {
    std::ifstream inputStream(inputFile, std::ios::binary | std::ios::ate);
    if (!inputStream.is_open()) {
        std::cerr << "Error opening input file: " << inputFile << std::endl;
        return;
    }
    size_t fileSize = static_cast<size_t>(inputStream.tellg());
    inputStream.seekg(0, std::ios::beg);

    std::ofstream outputStream(outputFile, std::ios::binary | std::ios::trunc);
    if (!outputStream.is_open()) {
        std::cerr << "Error opening output file: " << outputFile << std::endl;
        return;
    }

    char *buffer = new char[4096];
    size_t bytesRead;
    double totalBytesProcessed = 0.0;
    double progress = 0.0;

    while ((bytesRead = inputStream.read(buffer, sizeof(buffer))) > 0) {
        outputStream.write(buffer, bytesRead);
        totalBytesProcessed += bytesRead;
        progress = (totalBytesProcessed / fileSize) * 100.0;
        if (progress % 5 == 0) {
            std::lock_guard<std::mutex> lock(mtx);
            std::cout << "Processing: " << static_cast<int>(progress) << "%" << std::endl;
        }

        // Transform the contents based on the rule set here

        if (ruleSet.applyRule(buffer, bytesRead)) {
            outputStream.write(buffer, bytesRead);
        } else {
            std::cerr << "Error applying rule to data: session ID=" << sessionId << ", file=" << inputFile << ", offset=" << totalBytesProcessed << std::endl;
        }
    }

    delete[] buffer;
    inputStream.close();
    outputStream.close();
}

int main(int argc, char *argv[]) {
    if (argc != 7) {
        std::cerr << "Usage: ./process_file <input_file> <output_file> <session_id> <rule_set_url> <log_level> <extension_digits>" << std::endl;
