#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int rnti;
    unsigned char crc_indication_rel8_tag[4];
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int key;
    long offset;
} Index;

typedef struct {
    int value;
} Record;

void generate_unique_rntis(int* rntis, int size) {
    for (int i = 1; i <= size; ++i) {
        rntis[i] = i;
    }
    for (int i = 1; i < size; ++i) {
        int j = rand() % (i + 1);
        if (j != i) {
            int temp = rntis[i];
            rntis[i] = rntis[j];
            rntis[j] = temp;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_list(int n, int* rntis) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; ++i) {
        list[i].rnti = rntis[i + 1];
        list[i].crcflag = rand() % 2;
        for (int j = 0; j < i; ++j) {
            if (list[i].rnti == list[j].rnti) {
                --i;
                break;
            }
        }
    }
    return list;
}

Index* create_index(int n, int* rntis) {
    Index* index = (Index*)malloc(n * sizeof(Index));
    for (int i = 0; i < n; ++i) {
        index[i].key = rntis[i + 1];
        index[i].offset = i;
    }
    return index;
}

Record* create_records(int size, int min, int max) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }
    return records;
}

void serialize_list(const char* filename, NFAPI_CRC_INDICATION_PDU_T* list, Index* index, int size) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    fprintf(file, "%d\n", size);
    for (int i = 0; i < size; ++i) {
        fprintf(file, "RNTI:%d CRCFLAG:%u ", index[i].key, list[index[i].offset].crcflag);
        for (int j = 0; j < 4; ++j) {
            fprintf(file, "%02X ", list[index[i].offset].crc_indication_rel8_tag[j]);
        }
        fprintf(file, "\n");
    }
    fclose(file);
}

int main() {
    srand(time(NULL));

    int n = 1000;
    int size = 5000;
    int min = 10;
    int max = 99;

    int* rntis = (int*)malloc((n + 1) * sizeof(int));
    generate_unique_rntis(rntis, n);

    NFAPI_CRC_INDICATION_PDU_T* list = create_list(n, rntis);
    Index* index = create_index(n, rntis);

    Record* records = create_records(size, min, max);

    char filename[256];
    sprintf(filename, "output.dat");
    serialize_list(filename, list, index, n);

    free(rntis);
    free(list);
    free(index);
    free(records);

    return 0;
}
```

