        std::mt19937ar generator;
        std::array<uint64_t, 624> state;
        std::ofstream stateFileStream;

    public:
        RandomNumberGenerator(const Config& config);
        ~RandomNumberGenerator();
        void saveState();
        uint64_t generate(uint64_t min, uint64_t max);
        static std::vector<uint64_t> generateSequence(size_t size, uint64_t min, uint64_t max);
    };
} // namespace RandomNumberGenerator
```

2. random_number_generator_impl.cpp

```cpp
#include "random_number_generator.h"
#include <json/json.h>
#include <system_error>

namespace RandomNumberGenerator {
    void RandomNumberGenerator::saveState() {
        if (stateFileStream.is_open()) {
            for (const auto& value : state) {
                stateFileStream << value << ' ';
            }
            stateFileStream << std::endl;
        }
    }

    RandomNumberGenerator::RandomNumberGenerator(const Config& config)
        : generator(state.data()), stateFileStream(config.stateFile, std::ios_base::out | std::ios_base::app) {
        if (!stateFileStream.is_open()) {
            throw std::system_error(errno, std::generic_category(), "Failed to open state file.");
        }

        if (config.seed != 0) {
            for (size_t i = 0; i < state.size(); ++i) {
                state[i] = config.seed & ((1ULL << 64) - 1);
                if (++i >= state.size()) break;
                generator(state.data());
            }
        } else {
            std::ifstream stateFile(config.stateFile, std::ios_base::in);
            if (!stateFile.is_open()) {
                throw std::system_error(errno, std::generic_category(), "Failed to open state file.");
            }

            for (size_t i = 0; i < state.size(); ++i) {
                state[i] = 0;
                if (!(stateFile >> state[i])) {
                    break;
                }
            }
            generator(state.data());
        }
    }

    RandomNumberGenerator::~RandomNumberGenerator() {
        saveState();
        stateFileStream.close();
    }

    uint64_t RandomNumberGenerator::generate(uint64_t min, uint64_t max) {
        return min + generator() % (max - min + 1);
    }

    std::vector<uint64_t> RandomNumberGenerator::generateSequence(size_t size, uint64_t min, uint64_t max) {
        std::vector<uint64_t> result;
        for (size_t i = 0; i < size; ++i) {
            result.push_back(min + generator() % (max - min + 1));
        }
        return result;
    }
} // namespace RandomNumberGenerator
```

