```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct Node {
    char *str;
    int weight;
    struct Node *next;
} Node;

Node* create_node(const size_t str_len) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failure");
        return NULL;
    }

    new_node->str = (char *)calloc(str_len + 1, sizeof(char));
    if (!new_node->str) {
        free(new_node);
        perror("Memory allocation failure");
        return NULL;
    }

    new_node->next = NULL;
    return new_node;
}

void generate_random_weight(Node *node, int min, int max) {
    node->weight = rand() % (max - min + 1) + min;
}

void print_weights(Node *head) {
    for (Node *current = head; current != NULL; current = current->next) {
        printf("Weight: %d\n", current->weight);
    }
}

Node* manage_memory(size_t num_nodes, size_t str_len, int min_weight, int max_weight, size_t system_threshold) {
