    size_t total_allocated = 0;

    for (size_t i = 0; i < num_nodes && total_allocated < system_threshold; ++i) {
        Node *new_node = create_node(str_len);
        if (!new_node) {
            break;
        }

        generate_random_weight(new_node, min_weight, max_weight);
        total_allocated += sizeof(Node) + str_len + 1;

        new_node->next = head;
        head = new_node;
    }

    if (total_allocated >= system_threshold) {
        perror("Exceeded system threshold");
        for (Node *current = head; current != NULL; current = current->next) {
            free(current->str);
            free(current);
        }
        return NULL;
    }

    return head;
}

int main() {
    srand(time(NULL));

    size_t num_nodes = 1000;
    size_t str_len = 20;
    int min_weight = 1;
    int max_weight = 100;
    size_t system_threshold = (num_nodes * sizeof(Node) + num_nodes * str_len + num_nodes) * 1024 * 1024; // Example threshold: 10 MB

    Node* head = manage_memory(num_nodes, str_len, min_weight, max_weight, system_threshold);

    if (head != NULL) {
        print_weights(head);
    }

    return 0;
}
```

