        if (++query->retry_count <= MAX_RETRY_COUNT) {
            dns_cache_add(cache, query->hostname, query);
            sleep(BACKOFF_FACTOR * pow(2, query->retry_count));
            return dns_query_thread(query);
        }
    }

    // Cache the result if successful and process the resolved addresses
    if (res != NULL) {
        DnsQuery* cached_query = dns_cache_get(cache, query->hostname);
        pthread_mutex_lock(&cached_query->lock);

        for (ptr = res; ptr != NULL; ptr = ptr->ai_next) {
            // Process the resolved address based on your requirements
            void* addr = ptr->ai_addr;
            socklen_t addrlen = ptr->ai_addrlen;

            pthread_mutex_unlock(&cached_query->lock);
