public class EncryptionUtils {
    private static final int KEY_LENGTH = 256;
    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = ALGORITHM + "/CBC/PKCS5Padding";

    public static Cipher initializeAndEncryptWithAES(String password) throws NoSuchAlgorithmException, NoSuchPaddingException {
        KeyGenerator keyGen = KeyGenerator.getInstance(ALGORITHM);
        keyGen.init(KEY_LENGTH);
        SecretKey secretKey = keyGen.generateKey();

        byte[] salt = new byte[64]; // You can generate a random salt or use a fixed one for simplicity
