        SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = keyFactory.generateSecret(pbeKeySpec).getEncoded();
        SecretKey aesKey = new SecretKeySpec(keyBytes, ALGORITHM);

        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        IvParameterSpec iv = new IvParameterSpec(Arrays.copyOfRange(keyBytes, 0, 16)); // First 16 bytes of the key are used as IV
        cipher.init(Cipher.ENCRYPT_MODE, aesKey, iv);

        return cipher;
    }

    public static byte[] processAndLogDecryptedData(Cipher cipher, byte[] ciphertext, IvParameterSpec iv) {
        try {
            cipher.init(Cipher.DECRYPT_MODE, cipher.getParameters().getParameterSpec(SecretKeySpec.class), iv);
            byte[] plaintext = cipher.doFinal(ciphertext);
            LoggingService.logDecryptedData(plaintext, System.currentTimeMillis());
            return plaintext;
        } catch (Exception e) {
            // Handle exceptions gracefully and log them if necessary
