    int fd;
    size_t buffer_size;
    char *buffer;
};

void* process_file(void *arg) {
    struct file_data *data = arg;
    // Process the file here
    return NULL;
}

int main(int argc, char **argv) {
    int opt;
    bool help = false, count = false, output_specified = false;
    const char *output_file = NULL;
    while ((opt = getopt(argc, argv, "hc:o:")) != -1) {
        switch (opt) {
            case 'h':
                help = true;
                break;
            case 'c':
                count = true;
                break;
            case 'o':
                output_specified = true;
                output_file = optarg;
                break;
        }
    }

    // Display usage information if no input files are specified
    if (optind >= argc) {
        if (help) {
            printf("Usage:\n%s [options] file1 [file2 ...]\n\nOptions:\n"
                   "-h, --help          Show this help message and exit\n"
                   "-c, --count          Count words in each line of input files\n"
                   "-o, --output=FILE    Write results to the specified output file\n", argv[0]);
            return 0;
        } else {
            fprintf(stderr, "Error: No input files provided.\n");
            return 1;
        }
    }

    // Process multiple input files concurrently
    pthread_t threads[argc - optind];
    struct file_data *file_datas[argc - optind];
    for (int i = optind; i < argc; ++i) {
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            perror("open");
            return 1;
        }
        struct stat st;
        fstat(fd, &st);
        size_t buffer_size = st.st_size > 1048576 ? st.st_size / 1024 : 1024;
        char *buffer = malloc(buffer_size);
        file_datas[i - optind] = (struct file_data *)malloc(sizeof(struct file_data));
        file_datas[i - optind]->filename = argv[i];
        file_datas[i - optind]->fd = fd;
        file_datas[i - optind]->buffer_size = buffer_size;
        file_datas[i - optind]->buffer = buffer;
        pthread_create(&threads[i - optind], NULL, process_file, file_datas[i - optind]);
    }

    // Merge results and write to output file if specified
    int total_word_count = 0;
    if (output_specified) {
        FILE *output = fopen(output_file, "w");
        if (!output) {
            perror("fopen");
            return 1;
        }
        for (int i = 0; i < argc - optind; ++i) {
            fprintf(output, "%d\n", file_datas[i]->word_count);
            total_word_count += file_datas[i]->word_count;
        }
        fclose(output);
    }

    // Wait for all threads to finish
    for (int i = 0; i < argc - optind; ++i) {
        pthread_join(threads[i], NULL);
        free(file_datas[i]);
    }

    if (count) {
        printf("Total word count: %d\n", total_word_count);
    }

    return 0;
}
```

