const books = require('./config.json').books; // Loading JSON configuration file

function countBooks(text) {
  const regexes = books.map(book => RegExp(`\\b${book}\\b`, 'gi'));
  let counts = {};

  regexes.forEach(regex => {
    let match;
    while ((match = regex.exec(text)) !== null) {
