    private int _resetIntervalOperations;
    private Timer _resetTimer;

    public DataProcessor(int resetIntervalOperations)
    {
        _resetIntervalOperations = resetIntervalOperations;
        InitializePipelines();

        _resetTimer = new Timer(ResetAllPipelines, null, Timeout.Infinite, Timeout.Infinite);
