```cpp
#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <codecvt>
#include <locale>
#include <sstream>

const std::vector<std::string> allowed_extensions = {".txt", ".jpg", ".png", ".pdf", ".docx"};
const size_t max_filename_length = 256;

std::wstring utf8toWide(const std::string& str) {
    std::wstring_convert<std::codecvt_utf8<wchar_t>> converter;
    return converter.from_bytes(str);
}

std::string wideToString(const std::wstring& str) {
    std::wstring_convert<std::codecvt_utf8<wchar_t>> converter;
    return converter.to_bytes(str).data();
}

std::string generateNewFilename(const std::string& originalFilename) {
    std::regex re("\\.[^.]+$"); // regex to match the extension
    std::smatch match;
    if (std::regex_search(originalFilename, match, re)) {
        std::wstring wideOriginal = utf8toWide(originalFilename);
        std::wstring prefix = L"";
        size_t filenameLength = static_cast<size_t>(wideOriginal.length());
        if (filenameLength > max_filename_length - match.str().length() - 16) { // 16 for timestamp and separator
            size_t prefixLength = std::min(max_filename_length - match.str().length() - 16, filenameLength / 2);
            prefix = wideOriginal.substr(0, prefixLength);
        }
        wchar_t separator[] = L"_";
        std::wstring newFilename = prefix + L"-" + match.str();
        time_t now = time(nullptr);
        struct tm* localTime = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localTime);
        newFilename += L"-";
        newFilename += utf8toWide(timestamp);
        newFilename += match.suffix().data();
        std::string result = wideToString(newFilename);
        if (std::find(allowed_extensions.begin(), allowed_extensions.end(), result.back() + '.') == allowed_extensions.end()) {
            result += ".tmp";
        }
        return result;
    }
    return originalFilename;
}
```

