[" Here's a simplified implementation of the requested hash table in C. This code provides functions for insertion, retrieval, and cleanup, as well as an adjustable load factor. Note that this is a basic version and may not cover all edge cases or optimizations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    int value;
} Record;

const int TABLE_SIZE = 1024;
const float LOAD_FACTOR = 0.75;

int hash(int key) {
    return key % TABLE_SIZE;
}

int find_empty(int index) {
    for (int i = index; i < TABLE_SIZE; ++i) {
        if (!table[i].key) return i;
    }
    for (int i = 0; i <= index - 1; ++i) {
        if (!table[i].key) return i;
    }
    return -1; // No empty slot found
}

void resize_table() {
    Record* new_table = calloc(TABLE_SIZE * 2, sizeof(Record));
    for (int i = 0; i < TABLE_SIZE; ++i) {
        if (table[i].key) {
            int index = hash(table[i].key);
            for (int j = index; j < new_TABLE_SIZE * 2; ++j) {
                if (!new_table[j].key) {
                    new_table[j] = table[i];
                    break;
                }
            }
        }
    }
    free(table);
    table = new_table;
}

void insert(Record record) {
    int index = hash(record.key);
    int empty_index = find_empty(index);
    if (empty_index != -1) {
        table[empty_index] = record;
        return;
    }
    if ((float)num_records / TABLE_SIZE > LOAD_FACTOR) resize_table();
    int index2 = hash(record.key + 1);
    int empty_index2 = find_empty(index2);
    if (empty_index2 != -1) {
        table[empty_index2] = record;
        return;
    }
}

Record* find(int key) {
    int index = hash(key);
    for (int i = index; i < TABLE_SIZE; ++i) {
        if (table[i].key == key) return &table[i];
        if (!table[i].key) break;
    }
    for (int i = 0; i <= index - 1; ++i) {
        if (table[i].key == key) return &table[i];
    }
    return NULL;
}

void cleanup() {
    free(table);
}
```

This code defines a `Record` structure, a hash function, and functions for insertion, retrieval, resizing the table when necessary, and cleaning up memory. The load factor is adjustable through the `LOAD_FACTOR` constant. The implementation uses open addressing with linear probing to handle collisions."]

