char* modify_filename(const char* path) {
    size_t len = strlen(path);
    char* new_filename = malloc(len + 10); // Allowing for a 3-digit extension and a null terminator
    if (new_filename == NULL) {
        fprintf(stderr, "Failed to allocate memory for new filename\n");
        exit(EXIT_FAILURE);
    }

    strcpy(new_filename, path);

    size_t last_dot = len;
    for (size_t i = len - 1; i > 0; --i) {
        if (path[i] == '.') {
            last_dot = i;
            break;
        }
    }

    size_t extension_len = 4; // ".txt" or ".log"
    if (last_dot + extension_len > len) {
        fprintf(stderr, "Filename too long to accommodate the new extension\n");
        exit(EXIT_FAILURE);
    }

    char* ext = path + last_dot;
    if (isdigit((unsigned char)ext[0])) {
