        pthread_mutex_init(&records[i].mutex, NULL);
    }

    return records;
}

Record* get_record(Record *records, size_t index) {
    if (index >= sizeof(records) / sizeof(Record)) return NULL;
    pthread_mutex_lock(&records[index].mutex);
    Record *result = &records[index];
    pthread_mutex_unlock(&result->mutex);
    return result;
}

Record* find_record(Record *records, int key) {
    for (size_t i = 0; i < sizeof(records) / sizeof(Record); ++i) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].mutex);
            Record *result = &records[i];
            pthread_mutex_unlock(&result->mutex);
            return result;
        }
    }
    return NULL;
}

void deallocate(Record *records) {
    for (size_t i = 0; i < sizeof(records) / sizeof(Record); ++i) {
        pthread_mutex_destroy(&records[i].mutex);
    }
