#include <random>
#include <string>
#include <pthread.h>

struct Record {
    int value;
};

constexpr size_t MAX_FILENAME_LENGTH = 255;
constexpr size_t TRUNCATED_INDICATOR_LENGTH = 3;

class MemoryManager {
public:
    MemoryManager(size_t offsetSize, size_t keySize, size_t recordCount)
        : offsets_(offsetSize), keys_(keySize), records_(recordCount) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, INT_MAX);

        for (auto& record : records_) {
            record.value = dis(gen);
        }
    }

    ~MemoryManager() {
        offsets_.clear();
        keys_.clear();
        records_.clear();
    }

    Record* getRecord(int key) {
        pthread_mutex_lock(&mutex_);
        auto it = keys_.find(key);
        if (it == keys_.end()) {
            pthread_mutex_unlock(&mutex_);
            return nullptr;
        }
        Record* record = &records_[it->second];
        keys_.erase(it);
        offsets_.erase(offsets_.begin() + it->second);
        pthread_mutex_unlock(&mutex_);
        return record;
    }

    void putRecord(int key, Record* record) {
        pthread_mutex_lock(&mutex_);
        size_t index = offsets_.size();
        keys_[key] = index;
        offsets_.push_back(index);
        records_[index] = *record;
        pthread_mutex_unlock(&mutex_);
    }

    void logMemoryEvent(const std::string& event, int key, Record* record) {
        // Implement logging here using a specific library
    }

private:
    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<Record> records_;
    pthread_mutex_t mutex_;
};

