std::string generateFilename(const std::string& baseName, int version) {
    size_t baseNameLength = baseName.length();
    if (baseNameLength > MAX_FILENAME_LENGTH - TRUNCATED_INDICATOR_LENGTH - 5) {
        baseName = baseName.substr(0, MAX_FILENAME_LENGTH - TRUNCATED_INDICATOR_LENGTH - 5) + "...";
    }

    std::string extension;
    size_t dotIndex = baseName.find('.');
    if (dotIndex != std::string::npos) {
        extension = baseName.substr(dotIndex);
        baseName = baseName.substr(0, dotIndex);
    }

    return baseName + "_" + std::to_string(version) + extension + ".txt";
}
