        FILE *output = fopen(opts.output_file, opts.format == PLAIN ? "w" : "wb");
        if (!output) {
            perror("Error opening output file");
            return 4;
        }

        if (opts.compress && opts.callback == count_lines) {
            compress(NULL, &output);
            fseek(output, 0, SEEK_SET);
            count_lines(tmpfile(), opts.skip_comments, opts.threshold, write);
        } else if (opts.callback != count_lines) {
            process_lines((void *)&opts);
            if (fclose(output) == EOF) {
                perror("Error closing output file");
                return 5;
            }
        }

        fclose(output);
    } else if (opts.callback != count_lines) {
        process_lines((void *)&opts);
    }

    cleanup();
    return 0;
}
```

