class RandomNumberGenerator {
public:
    static RandomNumberGenerator& getInstance() {
        static RandomNumberGenerator instance;
        return instance;
    }

    int generate(unsigned int max) {
        std::lock_guard<std::mutex> lock(mutex);
        gen.discard(max); // discard initial values to avoid bias
        int result;
        gen >> result;
        return result % max;
    }

private:
    RandomNumberGenerator() : gen(rand()) {
        std::random_device rd;
        std::seed_seq ss{rd(), rd(), rd()};
        gen.seed(ss);
        mutex.lock();
