using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Newtonsoft.Json;
using StackExchange.Redis;

public class HomeController : Controller
{
    private readonly AppDbContext _context;
    private readonly IConnectionMultiplexer _redis;
    private readonly HttpClient _httpClient;

    public HomeController(AppDbContext context, IConnectionMultiplexer redis, HttpClient httpClient)
    {
        _context = context;
        _redis = redis;
        _httpClient = httpClient;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement([FromBody] UpdateElementRequest request)
    {
        var user = await _context.Users.FirstOrDefaultAsync(u => u.Id == request.UserId && u.SessionToken == request.SessionToken);
        if (user == null) return BadRequest("Invalid user or session token.");

        var cacheKey = $"element_{request.PageSectionId}_{request.ElementId}";
        var cachedContent = await GetFromCache(cacheKey);
        if (cachedContent != null) return Ok(new { Success = true, RefreshPage = false, Content = cachedContent });

        var contentResponse = await UpdateThirdPartyService(request);
        if (!contentResponse.IsSuccessStatusCode) return StatusCode((int)contentResponse.StatusCode, contentResponse.Content);

        var content = JsonConvert.DeserializeObject<string>(await contentResponse.Content.ReadAsStringAsync());
        await SetInCache(cacheKey, content);
        await _context.SaveChangesAsync(); // Save user's update action to the database

        return Ok(new { Success = true, RefreshPage = true, Content = content });
    }

    private async Task<string> GetFromCache(string key)
    {
        using (var db = _redis.GetDatabase())
        {
            return await db.StringGetAsync(key);
        }
    }

    private async Task SetInCache(string key, string value)
    {
        using (var db = _redis.GetDatabase())
        {
            await db.KeyDeleteAsync(key); // Delete old cache entry if it exists
            await db.StringSetAsync(key, value);
        }
    }

    private async Task<HttpResponseMessage> UpdateThirdPartyService(UpdateElementRequest request)
    {
        return await _httpClient.PostAsJsonAsync($"https://third-party-service-url", request);
    }
}

public class UpdateElementRequest
{
    public int UserId { get; set; }
    public string SessionToken { get; set; }
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
    public string Content { get; set; }
}
```

