    public async Task UpdateDialogFieldAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (!ValidateInputs(pageSectionId, elementId, htmlContent))
            throw new ArgumentException("Invalid inputs");

        var key = CreateCacheKey(pageSectionId, elementId);
        var cachedHtmlContent = _cache.Get(key);

        if (cachedHtmlContent != null)
