[" Here's a simplified version of the requested function, focusing mainly on generating a PEM certificate from streams and handling transient network failures. I've used `stream` and `fs` modules for handling streams and files respectively, and `bluebird` for promises.

```javascript
const { Readable, Transform } = require('stream');
const fs = require('fs');
const path = require('path');
const bluebird = require('bluebird');

class PemBufferStream extends Transform {
  constructor() {
    super({ objectMode: true });
    this._data = [];
  }

  _transform(chunk, encoding, callback) {
    this._data.push(chunk);
    callback();
  }

  get pem() {
    return Buffer.concat(this._data).toString('ascii');
  }
}

function generatePEMCertificateFromStream(privateKeyStream, certificateStream) {
  const privateKeyBuffer = new PemBufferStream();
  const certificateBuffer = new PemBufferStream();

  privateKeyStream.pipe(privateKeyBuffer);
  certificateStream.pipe(certificateBuffer);

  return bluebird.all([
    new Promise((resolve, reject) => {
      privateKeyBuffer.on('finish', resolve);
      privateKeyBuffer.on('error', reject);
    }),
    new Promise((resolve, reject) => {
      certificateBuffer.on('finish', resolve);
      certificateBuffer.on('error', reject);
    })
  ]).then(() => {
    const privateKeyPem = privateKeyBuffer.pem;
    const certificatePem = certificateBuffer.pem;

    // Combine private key and certificate into a single PEM file
    const pemContent = `-----BEGIN CERTIFICATE-----\n${certificatePem}\n-----END CERTIFICATE-----\n\n-----BEGIN PRIVATE KEY-----\n${privateKeyPem}\n-----END PRIVATE KEY-----`;
    return pemContent;
  });
}
```

This function processes the private key and certificate streams, buffers their data, and combines them into a single PEM file. It handles errors by rejecting the promise when an error occurs during stream processing.

