struct pool {
    PoolBlock* head;
    PoolBlock* tail;
    size_t blockSize;
};

Pool* create_pool(size_t blockSize) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;
    pool->blockSize = blockSize;
    pool->head = pool->tail = NULL;
    return pool;
}

void* pool_alloc(Pool* pool, size_t numBlocks) {
    PoolBlock* newBlock = malloc(numBlocks * sizeof(PoolBlock));
    if (!newBlock) return NULL;

    for (size_t i = 0; i < numBlocks; ++i) {
        newBlock[i].data = NULL;
        newBlock[i].size = pool->blockSize;
        newBlock[i].next = NULL;
    }

    if (!pool->head) {
        pool->head = newBlock;
        pool->tail = &newBlock[numBlocks - 1];
    } else {
        pool->tail->next = newBlock;
        pool->tail = &newBlock[numBlocks - 1];
    }

    return newBlock;
}

void* pool_alloc_block(Pool* pool) {
    if (!pool->head) return NULL;
    PoolBlock* block = pool->head;
    pool->head = block->next;
    return block;
}

void pool_free(Pool* pool, void* block) {
    if (block == NULL || pool == NULL) return;

    PoolBlock* current = pool->head;
    PoolBlock* previous = NULL;

    while (current != NULL && current != block) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) {
        pool->head = current->next;
    } else {
        previous->next = current->next;
