Record* init_records(size_t size, int min_value, int max_value) {
    srand(time(NULL));
    Record* records = (Record*)malloc(size * sizeof(Record));

    for (size_t i = 0; i < size; ++i) {
        records[i].key = i;
        records[i].offset = i * sizeof(Record);
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void serialize_records(const Record* records, size_t size, char** byte_array) {
    *byte_array = (char*)malloc((size + 1) * sizeof(Record) + size * sizeof(long) + size * sizeof(int));

    char* ptr = *byte_array;
    for (size_t i = 0; i < size; ++i) {
        memcpy(ptr, &records[i], sizeof(Record));
        ptr += sizeof(Record);
        memcpy(ptr, &records[i].key, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &records[i].offset, sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &records[i].value, sizeof(int));
        ptr += sizeof(int);
    }
}
