2. Dynamic memory allocation for offsets and keys:

```cpp
size_t* offsets = new size_t[capacity]; // Initialize with zeros
int* keys = new int[capacity]; // Initialize with zeros
```

3. Singly linked list for managing records:

```cpp
struct Node {
    Record data;
    Node* next;
};

Node* head = nullptr;
```

4. Dynamic resizing of the singly linked list:

```cpp
void resize(size_t newCapacity) {
    if (newCapacity <= capacity) return; // No need to resize if capacity is sufficient

    Node** newNodes = new Node*[newCapacity];
    std::copy_n(head, capacity, newNodes);
    capacity = newCapacity;
    delete[] offsets;
    offsets = new size_t[capacity]; // Initialize with zeros
    delete[] keys;
    keys = new int[capacity]; // Initialize with zeros

    Node* current = head;
    for (size_t i = capacity; i < newCapacity; ++i) {
        offsets[i] = 0;
        keys[i] = 0;
        while (current && offsets[current->data.len + 1]) current = current->next;
        if (!current) break;
        offsets[current->data.len + 1] = i;
        current->next = newNodes[i];
    }
}
```

5. Efficient traversal:

```cpp
Node* find(size_t index) {
    if (index >= capacity) return nullptr;
    Node* current = head;
    for (size_t i = 0; i <= index; ++i) current = current->next;
    return current;
}
```

6. Memory allocation for records:

```cpp
void allocateRecord(Node** node, size_t len) {
    if (!len) return; // No need to allocate memory if length is zero

    char* str = new char[len + 1];
    std::fill_n(str, len + 1, '\0');
    (*node)->data.id = rand() % maxIntValue;
    (*node)->data.str.assign(str, len);
    (*node)->data.len = len;
    offsets[(*node)->data.len + 1] = offsets[(*node)->data.len];
    keys[offsets[(*node)->data.len]] = (*node)->data.id;
}
```

