class DataPacketPool {
public:
    DataPacketPool(size_t numPackets) : freeList(), allocated(numPackets) {}

    DataPacket* allocate() {
        if (!freeList.empty()) {
            auto packet = freeList.front();
            freeList.pop();
            return packet;
        }
        return new DataPacket[allocated.size()];
    }

    void deallocate(DataPacket* packet) {
        freeList.push_back(packet);
    }

private:
