void processAndEnhanceNetworkTraffic(std::list<DataPacket>& packets, const std::vector<std::string>& args, size_t minPayloadSize, double errorThreshold) {
    namespace po = boost::program_options;
    namespace csv = boost::csv;
    namespace asio = boost::asio;

    auto findCommand = [&](const std::string& command) -> std::list<DataPacket>::iterator {
        for (auto it = packets.begin(); it != packets.end(); ++it) {
            if (it->id == std::stoi(command))
                return it;
        }
        return packets.end();
    };

    auto insertCommandPacket = [&](const std::string& command, const DataPacket& packet) {
        auto it = findCommand(command);
        if (it != packets.end())
            packets.insert(++it, packet);
        else
            packets.push_back(packet);
