        packet.id = row["id"].get<int>();
        packet.timestamp = row["timestamp"].get<std::uint64_t>();
        packet.payloadSize = row["payloadSize"].get<size_t>();
        packet.errorFlags = (packet.payloadSize < minPayloadSize);
        packet.networkStatus = row["networkStatus"];

        if (packet.errorFlags && packet.payloadSize * errorThreshold > packet.timestamp) {
