[' Here's a simplified implementation of the task in C++ using a custom slab allocator, hash table, and logging library. Note that this is a high-level outline and may require adjustments based on specific requirements and constraints.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <thread>
#include <mutex>
#include <chrono>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>

struct Record {
    int value;
};

class MemoryManager {
public:
    MemoryManager() : offsets_(16, 0), keys_(16, -1), records_(), slabAllocator_(), hashTable_(), log_("MemoryManager") {}

    void* allocateOffset(size_t size) {
        if (slabAllocator_.allocate(size))
            return slabAllocator_.getSlab()->data;
        resizeOffsetsAndKeys();
        return slabAllocator_.allocate(size);
    }

    int allocateKey() {
        std::lock_guard<std::mutex> lock(keysMutex_);
        if (keys_.back() != keys_.size() - 1)
            return keys_.back() + 1;
        resizeOffsetsAndKeys();
        return keys_.back() + 1;
    }

    Record* allocateRecord() {
        void* data = allocateOffset(sizeof(Record));
        new (data) Record{ rand() % MAX_VALUE };
        return static_cast<Record*>(data);
    }

    Record& getRecord(int key) {
        auto it = hashTable_.find(key);
        if (it != hashTable_.end())
            return it->second;
        throw std::out_of_range("Invalid index");
    }

private:
    void resizeOffsetsAndKeys() {
        auto oldSize = offsets_.size();
        offsets_.resize(oldSize * 2);
        keys_.resize(keys_.size() * 2);
        slabAllocator_.resizeSlabs(oldSize, oldSize * 2);
    }

    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<Record> records_;
    SlabAllocator slabAllocator_;
    std::unordered_map<int, Record> hashTable_;
    std::mutex keysMutex_;

    static log4cxx::LoggerPtr log_;
};

log4cxx::LoggerPtr MemoryManager::log_ = log4cxx::Logger::getLogger("MemoryManager");

void logEvent(const char* event, void* data, size_t size) {
    auto now = std::chrono::system_clock::now();
    auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
    log_->info(event);
    log_->info("Size: " + std::to_string(size));
    log_->info("Data: " + std::to_string(reinterpret_cast<int*>(data)));
    log_->info("Time: " + std::to_string(millis));
}
```

