**C Function (hash_table.c)**

```c
#include "hash_table.h"

static unsigned long hash(const char* str, unsigned long size) {
    unsigned long hash = 5381;
    for (unsigned long i = 0; *str != '\0'; ++i) {
        hash = ((hash << 5) + hash) + (*str);
    }
    return hash % size;
}

HashTable* create_hash_table(unsigned long size) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    if (!hash_table) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    hash_table->size = size;
    hash_table->table = calloc(size, sizeof(HashNode*));
    if (!hash_table->table) {
        perror("calloc");
        free(hash_table);
        exit(EXIT_FAILURE);
    }
    return hash_table;
}

void destroy_hash_table(HashTable* hash_table) {
    for (unsigned long i = 0; i < hash_table->size; ++i) {
        HashNode* node = hash_table->table[i];
        while (node) {
            HashNode* next = node->next;
            free(node->record->id);
            free(node->record);
            free(node);
            node = next;
        }
    }
    free(hash_table->table);
    free(hash_table);
}

Record* create_record(int value, char* id) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    record->id = strdup(id);
    if (!record->id) {
        free(record);
        perror("strdup");
        exit(EXIT_FAILURE);
    }
    return record;
}

void insert(HashTable* hash_table, Record* record, int key) {
    unsigned long index = hash(record->id, hash_table->size);
    HashNode** node = &hash_table->table[index];
    while (*node) {
        if ((*node)->record->value == key) {
            free((*node)->record->id);
            free(*node->record);
            *node->record = *record;
            return;
        }
        node = &(*node)->next;
    }
    *node = malloc(sizeof(HashNode));
    if (!*node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    (*node)->record = record;
    (*node)->next = NULL;
}

Record* find(HashTable* hash_table, int key) {
    unsigned long index = hash(hash_table->id, hash_table->size);
    HashNode* node = hash_table->table[index];
    while (node) {
        if (node->record->value == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}
```

