    data.ui = rand();
    for (int i = 0; i < 10; ++i) {
        data.str[i] = static_cast<char>(rand() % 26 + 'a');
        data.str[i + 1] = '\0';
    }
}

std::unordered_map<unsigned long, Data*> createHashTable(size_t size) {
    std::unordered_map<unsigned long, Data*> hashTable;
    for (size_t i = 0; i < size; ++i) {
        Data* data = new Data();
        generateRandomData(*data);
        auto it = hashTable.emplace(i, data);
        if (!it.second) { // collision handling strategy: rehash or open addressing
            std::cerr << "Collision occurred at key: " << i << std::endl;
            delete data;
        }
    }
    return hashTable;
}

Data* getData(std::unordered_map<unsigned long, Data*> &hashTable, unsigned long key) {
    auto it = hashTable.find(key);
    if (it != hashTable.end()) {
        return it->second;
    }
    std::cerr << "Key not found: " << key << std::endl;
    return nullptr;
}

void printData(const Data* data) {
    std::cout << "d: " << data->d << ", ui: " << data->ui << ", str: " << data->str << std::endl;
}

