const retries = 3;
const maxConcurrentReads = 1000;
const logger = console; // Replace with a proper logging library for production use

function processJsonFiles(directory) {
  const watcher = chokidar.watch(directory, { persistent: true });

  let concurrentReads = 0;

  watcher
    .on('add', (filePath) => {
      if (path.extname(filePath) === '.json' && validateFileSize(filePath)) {
        processJsonFile(filePath);
      }
    })
    .on('change', (filePath) => {
      processJsonFile(filePath);
    });

  async function processJsonFile(filePath) {
    if (concurrentReads < maxConcurrentReads) {
      concurrentReads++;
      try {
        const content = await readFileAsync(filePath);
        cache.set(filePath, content);
        parseJsonContent(content);
      } catch (error) {
        if (retries > 0) {
          setTimeout(() => processJsonFile(filePath), Math.pow(2, retries--) * 1000);
        } else {
          logger.warn(`Failed to process ${filePath} after ${retries} retries. Marking for manual review.`);
        }
      } finally {
        concurrentReads--;
