#define E_TIMEOUT_OCCURRED 5
#define E_OUT_OF_MEMORY 6
#define E_BASE64_MALFORMED 7
#define E_Padding_ERROR 8

// Define a structure to hold the decryption context
typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} DecryptContext;

// Function to handle decryption in a separate thread
void* decrypt_thread(void* arg) {
    SecurityData* data = (SecurityData*)arg;
    DecryptContext* ctx = malloc(sizeof(DecryptContext));

    // Initialize the encryption context
    EVP_CIPHER_CTX_init(ctx->ctx);
    int encrypt_ok = 0;

    // Set the encryption algorithm (e.g., AES)
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();

    // Initialize the encryption context
    if (1 != EVP_CIPHER_CTX_init(ctx->ctx)) {
        log4c_logger_error(logger, "Failed to initialize encryption context");
        goto cleanup;
    }

    // Set the encryption algorithm and IV
    if (1 != EVP_EncryptInit_ex(ctx->ctx, cipher, data->connection->iv, data->password)) {
        log4c_logger_error(logger, "Failed to initialize encryption");
        goto cleanup;
    }

    encrypt_ok = 1;

    // Perform the decryption
    unsigned char plaintext[1024];
    int plaintext_len = 0;
    if (1 != EVP_DecodeBase64(data->connection->data, strlen(data->connection->data), plaintext, &plaintext_len)) {
        log4c_logger_error(logger, "Failed to decode Base64 data");
        goto cleanup;
    }

    if (1 != EVP_DecryptUpdate(ctx->ctx, plaintext, &plaintext_len, plaintext, plaintext_len)) {
        log4c_logger_error(logger, "Failed to decrypt data");
        goto cleanup;
    }

    // Finalize the decryption
    unsigned char final_plaintext[1024];
    int final_plaintext_len = 0;
    if (1 != EVP_DecryptFinal_ex(ctx->ctx, final_plaintext, &final_plaintext_len)) {
        log4c_logger_error(logger, "Failed to decrypt data");
        goto cleanup;
    }

cleanup:
    // Clean up the encryption context and free memory
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);

    if (!encrypt_ok) {
        data->callback(E_DECRYPTION_FAILED, NULL);
    } else {
        // Call the callback with the decrypted data
        char* decryptedData = malloc(final_plaintext_len + 1);
        memcpy(decryptedData, final_plaintext, final_plaintext_len);
        decryptedData[final_plaintext_len] = '\0';
        data->callback(0, decryptedData);
        free(decryptedData);
    }

    return NULL;
}

// Function to start the decryption process asynchronously
void start_decryption(SecurityData* data) {
    // Start a new thread for decryption
    pthread_create(&data->thread_id, NULL, &decrypt_thread, data);
}
