typedef struct {
    char* session_id;
    struct Connection* connection;
} SessionConfig;

struct Connection {
    char* name;
    pthread_mutex_t mutex;
    int active_sessions;
    void (*error_callback)(int);
    int error_threshold;
};

enum ErrorCodes {
    SUCCESS = 0,
    INVALID_SESSION_ID,
    ID_LENGTH_EXCEEDED,
    INVALID_CONNECTION_NAME,
    NAME_LENGTH_EXCEEDED,
    TOO_MANY_ACTIVE_SESSIONS,
    NULL_ERROR_CALLBACK,
    ERROR_CALLBACK_THRESHOLD_VIOLATED,
};

int setup_session(SessionConfig* config) {
    struct Connection* connection = config->connection;
    char* session_id = config->session_id;

    // Lock the connection mutex to ensure thread safety
    pthread_mutex_lock(&connection->mutex);

    if (!session_id || strlen(session_id) > 16) {
        pthread_mutex_unlock(&connection->mutex);
        return INVALID_SESSION_ID;
    }

    if (!connection->name || ucslen(connection->name) > 64) {
        pthread_mutex_unlock(&connection->mutex);
        return INVALID_CONNECTION_NAME;
    }

    if (connection->active_sessions < 0 || connection->active_sessions > 150) {
        pthread_mutex_unlock(&connection->mutex);
        return TOO_MANY_ACTIVE_SESSIONS;
    }

    if (!connection->error_callback || connection->error_threshold <= 0) {
        pthread_mutex_unlock(&connection->mutex);
        return NULL_ERROR_CALLBACK;
    }

    // All checks passed, allocate and initialize session resources
    Session* session = malloc(sizeof(Session));
    if (!session) {
        pthread_mutex_unlock(&connection->mutex);
        return MEMORY_ALLOCATION_FAILURE;
    }

    session->session_id = strdup(session_id);
    if (!session->session_id) {
        free(session);
        pthread_mutex_unlock(&connection->mutex);
        return MEMORY_ALLOCATION_FAILURE;
    }

    connection->active_sessions++;
    session->connection = connection;

    // Link the session to the network connection
    session->next = connection->sessions;
    connection->sessions = session;

    pthread_mutex_unlock(&connection->mutex);
    return SUCCESS;
}
```

This function ensures thread safety by locking the connection mutex before performing any checks and operations. It also properly manages dynamically allocated memory using `malloc`, `strdup`, and proper deallocation in case of errors.']

