#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

typedef struct node {
    record_t data;
    struct node* next;
} node_t;

typedef struct slab {
    size_t size;
    unsigned long capacity;
    unsigned long allocated;
    node_t** nodes;
    pthread_spinlock_t lock;
} slab_t;

slab_t offsets, keys, records;
pthread_once_t once_control = PTHREAD_ONCE_INIT;

void init_slab(slab_t* slab, size_t size) {
    slab->size = size;
    slab->capacity = 0;
    slab->allocated = 0;
    slab->nodes = NULL;
    pthread_spin_init(&slab->lock, 0);
}

void* allocate(slab_t* slab) {
    if (slab->capacity <= slab->allocated + slab->size) {
        resize_slab(slab, slab->capacity + slab->size * 2);
    }

    pthread_spin_lock(&slab->lock);
    node_t* node = slab->nodes[slab->allocated];
    slab->allocated++;
    pthread_spin_unlock(&slab->lock);

    return node;
}

void deallocate(slab_t* slab, void* ptr) {
    if (ptr >= slab->nodes && ptr < slab->nodes + slab->capacity) {
        pthread_spin_lock(&slab->lock);
        ((node_t*)ptr)->next = slab->free_list;
        slab->free_list = (node_t*)ptr;
        pthread_spin_unlock(&slab->lock);
    }
}

void resize_slab(slab_t* slab, unsigned long new_capacity) {
    node_t** old_nodes = slab->nodes;
    slab->nodes = calloc(new_capacity, sizeof(node_t*));

    for (unsigned long i = 0; i < slab->allocated; ++i) {
        slab->nodes[i] = old_nodes[i];
    }

    free(old_nodes);
    slab->capacity = new_capacity;
}

void init() {
    pthread_once(&once_control, []() {
        init_slab(&offsets, sizeof(long));
        init_slab(&keys, sizeof(int));
        init_slab(&records, sizeof(record_t));
    });
}

void log_allocation(const char* type, void* ptr) {
    // Implement logging here using an external library
}

record_t* get_record(unsigned long index) {
    unsigned long hash = hash(index);
    node_t* current = records.free_list;

    pthread_spin_lock(&records.lock);
    while (current != NULL && hash > hash(current->data.value)) {
        current = current->next;
    }

    if (current == NULL) {
        current = (node_t*)allocate(&records);
        current->data.value = index;
    }

    pthread_spin_unlock(&records.lock);
    return &current->data;
}

