public:
    void* allocate(size_t size) {
        if (freeList.empty()) {
            void* memory = std::malloc(size);
            if (!memory) throw std::bad_alloc();
            usedMemory += size;
        }
        void* result = freeList.back();
        freeList.pop_back();
