typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
size_t capacity = 0, size = 0;
int* keys = NULL;
long* offsets = NULL;
Record* records = NULL;

void resize() {
    Node** newHead = (Node**)malloc((capacity + 1024) * sizeof(Node*));
    for (size_t i = 0; i < capacity; ++i) {
        Node* current = head[i];
        if (current != NULL) {
            size_t index = size / (capacity * 4);
            newHead[index] = current;
        }
    }
    free(head);
    head = newHead;
    capacity *= 2;
}

void allocate() {
    if (size >= capacity * 0.75) resize();
    keys = realloc(keys, sizeof(int) * (size + 1024));
    offsets = realloc(offsets, sizeof(long) * (size + 1024));
    records = realloc(records, sizeof(Record) * (size + 1024));
}

void push_back(int key, long offset) {
    pthread_mutex_lock(&mutex);
    allocate();
    records[size].key = key;
    records[size].offset = offset;
    size++;
    if (head[size / 4] == NULL) head[size / 4] = &records[size - 1];
    else {
        Node* current = head[size / 4];
        while (current->next != NULL) current = current->next;
        current->next = &records[size - 1];
    }
    pthread_mutex_unlock(&mutex);
}

Record get(int key) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] == key) {
            Record result = records[i];
            pthread_mutex_unlock(&mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&mutex);
    fprintf(stderr, "Error: Key not found\n");
    exit(1);
}

