```python
import json
import os
import logging
from cryptography import exceptions, fernet
from concurrent.futures import ThreadPoolExecutor
from typing import Dict, Any

class Cipher:
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.id = config['id']
        self.factory = registry.get(self.id)
        self.cipher_obj = None

        # Validate and initialize cipher object
        try:
            self.cipher_obj = self.factory(**config)
        except Exception as e:
            raise ValueError(f"Failed to create cipher object for ID {self.id}: {e}")

    def encrypt(self, data: bytes) -> str:
        if not self.cipher_obj:
            raise ValueError("No cipher object initialized")
        return self.cipher_obj.encrypt(data)

    def decrypt(self, data: str) -> bytes:
        if not self.cipher_obj:
            raise ValueError("No cipher object initialized")
        return self.cipher_obj.decrypt(data)

    def sign(self, data: bytes) -> str:
        if not self.cipher_obj:
            raise ValueError("No cipher object initialized")
        return self.cipher_obj.sign(data)

    def verify(self, data: bytes, signature: str) -> bool:
        if not self.cipher_obj:
            raise ValueError("No cipher object initialized")
        return self.cipher_obj.verify(data, signature)

registry = {}

def register(id: str, factory):
    registry[id] = factory

def load_config(filepath: str) -> Dict[str, Any]:
    with open(filepath, 'r') as f:
        return json.load(f)

def encrypt_large_files(ciphers: List[Cipher], filepaths: List[str]):
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(cipher.encrypt, open(filepath, 'rb').read()) for cipher, filepath in zip(ciphers, filepaths)]
        encrypted_data = [f.result() for f in futures]
    return encrypted_data

# Example usage:
