using System;
using System.Xml;
using System.Xml.Schema;
using System.IO;
using System.Collections.Generic;

public class ConfigLoader
{
    private readonly Dictionary<string, XmlSchemaSet> _schemaSets = new Dictionary<string, XmlSchemaSet>();

    public T LoadConfig<T>(string filePath) where T : new()
    {
        var config = new T();
        using (var reader = XmlReader.Create(filePath))
        {
            var version = reader.GetAttribute("version");
            if (!_schemaSets.TryGetValue(version, out var schemaSet))
            {
                schemaSet = new XmlSchemaSet();
                schemaSet.Add(XmlSchema.Read(new StringReader(Resources.Load<TextAsset>("config_schema_" + version).text), null));
                _schemaSets[version] = schemaSet;
            }

            var serializer = new XmlSerializer(typeof(T));
            using (var validatingReader = new XmlValidatingReader(reader, schemaSet))
            {
                config = (T)serializer.Deserialize(validatingReader);
            }
        }

        return config;
    }
}
```

