    private readonly ILogger<ThemeManager> _logger;

    public ThemeManager(ILogger<ThemeManager> logger, string defaultThemeDirectory)
    {
        _logger = logger;
        _defaultThemeDirectory = defaultThemeDirectory;
        ValidateDirectory(_defaultThemeDirectory);
        _xmlParser = new XmlDocument();
        _httpClient = new HttpClient();
    }

    public Bitmap GetThemeBitmap(string themeName)
    {
        WeakReference weakRef;
        if (_themeCache.TryGetValue(themeName, out weakRef))
        {
            var bitmap = weakRef.Target as Bitmap;
            if (bitmap != null) return bitmap;
        }

        var themeFilePath = Path.Combine(_defaultThemeDirectory, themeName + ".png");
        if (!File.Exists(themeFilePath))
        {
            _logger.LogError($"Missing theme file: {themeFilePath}");
            return LoadFallbackBitmap(); // Implement fallback mechanism
        }

        using (var stream = new FileStream(themeFilePath, FileMode.Open))
        {
            var bitmap = Image.FromStream(stream);
            _themeCache[themeName] = new WeakReference(bitmap);
            return bitmap;
        }
    }

    public void FetchThemeBitmap(string themeName)
    {
        var themeUrl = $"https://api.example.com/themes/{themeName}.png";
        try
        {
            var response = _httpClient.GetAsync(themeUrl).Result;
            if (!response.IsSuccessStatusCode) throw new Exception($"Failed to fetch theme: {themeUrl}");

            using (var stream = await response.Content.ReadAsStreamAsync())
            {
                var bitmap = Image.FromStream(stream);
                _themeCache[themeName] = new WeakReference(bitmap);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to fetch theme: {themeUrl}", ex);
        }
    }

    private void ValidateDirectory(string directory)
    {
        if (!Directory.Exists(directory)) throw new DirectoryNotFoundException($"The specified directory '{directory}' does not exist.");
    }
}
