unsigned long long seed = 0;
void thread_safe_srand(unsigned int seed) {
    pthread_mutex_lock(&rand_lock);
    srand(seed);
    pthread_mutex_unlock(&rand_lock);
}

unsigned int thread_safe_rand() {
    pthread_mutex_lock(&rand_lock);
    unsigned int result = rand();
    pthread_mutex_unlock(&rand_lock);
    return result;
}

// Function to initialize arrays and manage memory
void init(record_t **records, char **metadata, int *keys, long *offsets) {
    records = (record_t *)my_malloc(RECORD_ARRAY_SIZE * sizeof(record_t));
    if (!records) return;

    metadata = (char *)calloc(METADATA_ARRAY_SIZE, METADATA_ARRAY_SIZE);
    if (!metadata) {
        my_free(records, RECORD_ARRAY_SIZE * sizeof(record_t));
        return;
    }

    keys = (int *)calloc(KEY_ARRAY_SIZE, sizeof(int));
    if (!keys) {
        free(metadata);
        my_free(records, RECORD_ARRAY_SIZE * sizeof(record_t));
        return;
    }

    offsets = (long *)calloc(OFFSET_ARRAY_SIZE, sizeof(long));
    if (!offsets) {
        free(keys);
        free(metadata);
        my_free(records, RECORD_ARRAY_SIZE * sizeof(record_t));
        return;
    }
}
