1. Memory Pool Allocator:

```cpp
class MemoryPool {
public:
    virtual void* allocate(size_t size) = 0;
    virtual void deallocate(void* ptr) = 0;
};

class SimpleMemoryPool : public MemoryPool {
private:
    std::vector<char> pool;
    size_t freeListIndex;

public:
    SimpleMemoryPool(size_t initialSize, size_t blockSize) {
        pool.resize(initialSize);
        freeListIndex = 0;
    }

    void* allocate(size_t size) override {
        if (freeListIndex + size > pool.size()) throw std::runtime_error("Memory allocation failed");
        auto ptr = &pool[freeListIndex];
        freeListIndex += size;
        return ptr;
    }

    void deallocate(void* ptr) override {
        if (static_cast<char*>(ptr) < &pool[0] || static_cast<char*>(ptr) >= &pool[pool.size()])
            throw std::runtime_error("Invalid memory pointer");
        freeListIndex = static_cast<size_t>(static_cast<char*>(ptr) - &pool[0]);
    }
};
```

