```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/stat.h>
#include <unistd.h>
#include <semaphore.h>
#include <log4c.h>

typedef struct {
    int key;
    long offset;
} record;

struct memory_manager {
    size_t capacity;
    size_t keys_count;
    size_t records_count;
    int* keys;
    long* offsets;
    record* records;
    sem_t mutex;
};

void mm_init(struct memory_manager* mm, size_t capacity) {
    mm->capacity = capacity;
    mm->keys_count = 0;
    mm->records_count = 0;
    mm->keys = malloc(sizeof(int) * capacity);
    mm->offsets = calloc(sizeof(long), capacity);
    mm->records = malloc(sizeof(record) * capacity);
    sem_init(&mm->mutex, 0, 1);
}

void mm_deinit(struct memory_manager* mm) {
    free(mm->keys);
    free(mm->offsets);
    free(mm->records);
    sem_destroy(&mm->mutex);
}

int mm_allocate_key(struct memory_manager* mm) {
    if (mm->keys_count >= mm->capacity) return -1;
    int key = mm->keys[mm->keys_count];
    mm->keys[mm->keys_count] = -1;
    mm->keys_count++;
    return key;
}

long mm_allocate_offset(struct memory_manager* mm) {
    if (mm->records_count >= mm->capacity) return -1;
    long offset = mm->offsets[mm->records_count];
    mm->offsets[mm->records_count] = 0;
    mm->records_count++;
    return offset;
}

void mm_deallocate(struct memory_manager* mm, int key) {
    size_t index = (size_t)key;
    if (index >= mm->capacity || mm->keys[index] == -1) return;
    mm->keys[index] = -1;
    mm->records_count--;
}

record* mm_get(struct memory_manager* mm, int key) {
    size_t index = (size_t)key;
    sem_wait(&mm->mutex);
    if (index >= mm->capacity || mm->keys[index] == -1) {
        sem_post(&mm->mutex);
        return NULL;
    }
    record* record = &mm->records[index];
    sem_post(&mm->mutex);
    return record;
}

void process_file(const char* path, const char* new_ext) {
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s.%s", path, new_ext);
    if (strlen(new_filename) > 255) {
        LOG4C_ERROR(logger, "Filename too long: %s", new_filename);
        return;
    }
    rename(path, new_filename);
}

int main() {
    // Initialize logger
    log4c_init();
    Logger* logger = log4c_get_logger("myapp");
    log4c_set_level(logger, LOG4C_LEVEL_INFO);

    struct memory_manager mm;
    mm_init(&mm, 1024);

    // ... (other code for file processing)

    mm_deinit(&mm);
    log4c_shutdown();
    return 0;
}
```

