function manageUserInteraction($_REQUEST) {
    $response = ['message' => 'error', 'data' => []];
    $subAction = $_REQUEST['sub_action'];
    unset($_REQUEST['sub_action']);

    // Database connection (replace with your actual database connection)
    $db = new PDO('mysql:host=localhost;dbname=myDB', 'username', 'password');

    switch ($subAction) {
        case 'create':
            if (!empty($_REQUEST['name']) && filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL) && !empty($_REQUEST['password'])) {
                $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
                $stmt->execute(['name' => $_REQUEST['name'], 'email' => $_REQUEST['email'], 'password' => $_REQUEST['password']]);
                $response['message'] = 'success';
            } else {
                $response['message'] = 'invalid_data';
            }
            break;
        case 'update':
            if (!empty($_REQUEST['id']) && !empty($_REQUEST['name']) && filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL) && (isset($_REQUEST['password']) || empty($_REQUEST['password']))) {
                $stmt = $db->prepare("UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id");
                $stmt->execute(['id' => $_REQUEST['id'], 'name' => $_REQUEST['name'], 'email' => $_REQUEST['email'], 'password' => isset($_REQUEST['password']) ? $_REQUEST['password'] : null]);
                $response['message'] = 'success';
            } else {
                $response['message'] = 'invalid_data';
            }
            break;
        case 'delete':
            if (!empty($_REQUEST['id'])) {
                $stmt = $db->prepare("DELETE FROM users WHERE id=:id");
                $stmt->execute(['id' => $_REQUEST['id']]);
                $response['message'] = 'success';
            } else {
                $response['message'] = 'invalid_data';
            }
            break;
        case 'retrieve':
            if (!empty($_REQUEST['id'])) {
                $stmt = $db->prepare("SELECT * FROM users WHERE id=:id");
                $stmt->execute(['id' => $_REQUEST['id']]);
                $user = $stmt->fetch(PDO::FETCH_ASSOC);
                if ($user) {
                    $response['message'] = 'success';
                    $response['data'] = $user;
                } else {
                    $response['message'] = 'not_found';
                }
            } else {
                $response['message'] = 'invalid_data';
            }
            break;
        case 'hash':
            if (!empty($_REQUEST['password'])) {
                // Hashing algorithm implementation (replace with your actual hashing function)
                $hashedPassword = hash('sha256', $_REQUEST['password']);
                $response['data'] = ['hashed_password' => $hashedPassword];
            } else {
                $response['message'] = 'invalid_data';
            }
            break;
    }

    // Logging implementation (replace with your actual logging function)
    logUserInteraction($_REQUEST, $response);

    return json_encode($response);
}
```

