```javascript
const sprintf = require('sprintf-js');
const axios = require('axios');
const eventBus = new EventEmitter();
const concurrentScriptLimit = 5;
let scriptsInQueue = [];

class ScriptLoader {
  constructor(url, metadataApiUrl) {
    this.url = url;
    this.metadataApiUrl = metadataApiUrl;
    this.filenameGenerator = new FilenameGenerator();
  }

  async load() {
    try {
      const response = await axios.get(this.url, { responseType: 'arraybuffer' });
      const scriptData = new TextDecoder().decode(response.data);
      const metadataResponse = await axios.get(this.metadataApiUrl);
      const metadata = metadataResponse.data;

      // Chunk the script for loading and execution
      const chunkedScript = this.chunkScript(scriptData, concurrentScriptLimit);

      scriptsInQueue.push({ url: this.url, metadata, chunkedScript });
      this.loadNextChunk();
    } catch (error) {
      console.error(`Error loading script ${this.url}:`, error);
      eventBus.emit('script_loading_error', { url: this.url, error });
    }
  }

  loadNextChunk() {
    if (!scriptsInQueue.length) return;

    const currentScript = scriptsInQueue.shift();
    const chunk = currentScript.chunkedScript.shift();

    // Load and execute the next chunk of script
    this.executeChunk(currentScript, chunk);
  }

  executeChunk({ url, metadata }, chunk) {
    try {
      // Execute the chunk of script
      eval(chunk);

      // Generate a new filename based on execution metrics
      const newFilename = this.filenameGenerator.generate(metadata);

      console.log(`Script ${url} executed and saved as ${newFilename}`);
      eventBus.emit('script_executed', { url, newFilename });
    } catch (error) {
      console.error(`Error executing chunk from script ${url}:`, error);
      eventBus.emit('script_execution_error', { url, error });
    } finally {
      // Remove the executed chunk from the queue
      const index = currentScript.chunkedScript.indexOf(chunk);
      if (index !== -1) currentScript.chunkedScript.splice(index, 1);

      if (!currentScript.chunkedScript.length) {
        // If all chunks have been executed, remove the script from the queue
        scriptsInQueue = scriptsInQueue.filter((script) => script !== currentScript);
      }
    }
  }

  chunkScript(scriptData, concurrentScriptLimit) {
    const chunkSize = Math.ceil(scriptData.length / concurrentScriptLimit);
    return Array.from({ length: concurrentScriptLimit }, (_, i) => scriptData.substring(i * chunkSize, (i + 1) * chunkSize));
  }
}

class FilenameGenerator {
  generate(metadata) {
    // Implement the logic to generate a new filename based on the script's metadata and execution metrics
    const timestamp = new Date().getTime();
    const versionNumber = calculateVersionNumberBasedOnMetrics(metadata);
    return sprintf('script_%d_v%d.js', [timestamp, versionNumber]);
  }
}

// Implement the logic to calculate the version number based on execution metrics
function calculateVersionNumberBasedOnMetrics(metadata) {
  // ...
}

// Initialize the script loader with user-uploaded scripts and start loading them
