void validate_filename(const char *filename, size_t max_length) {
    if (strlen(filename) > max_length || strlen(filename) == 0) {
        fprintf(stderr, "Error: Invalid filename length.\n");
        return;
    }

    bool has_extension = false;
    for (size_t i = 0; i < strlen(filename); ++i) {
        if (filename[i] == '.') {
            has_extension = true;
            break;
        }
    }

    if (!has_extension) {
        fprintf(stderr, "Error: Filename does not contain a valid file extension.\n");
        return;
    }
}

int count_digits_before_dot(const char *filename) {
    int count = 0;
    for (size_t i = 0; i < strlen(filename); ++i) {
        if (isdigit(filename[i])) {
            ++count;
        } else if (filename[i] == '.') {
            break;
        }
    }
    return count;
}

char* extract_extension(const char *filename) {
    size_t extension_length = 0;
    for (size_t i = strlen(filename); i > 0; --i) {
        if (filename[i] == '.') {
            extension_length = strlen(filename) - i;
            break;
        }
    }

    char *extension = malloc(extension_length + 1);
    strncpy(extension, filename + strlen(filename) - extension_length, extension_length + 1);
    return extension;
}

char* generate_new_filename(const char *original_filename, int version, size_t max_length) {
    validate_filename(original_filename, max_length);

    int digits_before_dot = count_digits_before_dot(original_filename);
    char* extension = extract_extension(original_filename);

    char *new_filename = malloc(max_length + 10); // Account for version number and ".txt"
    snprintf(new_filename, max_length + 10, "%.*s%d.%s", digits_before_dot > 0 ? digits_before_dot : 0, original_filename, version, extension ? extension : "unknown");

    if (strchr(new_filename, '.') && strcmp(extension, ".txt") != 0) {
        strcat(new_filename, ".txt");
    }

    if (strlen(new_filename) > max_length) {
        size_t truncated_length = max_length - 3; // Account for "...", plus one for the null terminator
        strncpy(new_filename, original_filename, truncated_length);
        strcat(new_filename, "...");
    }

    return new_filename;
}

