    std::unordered_map<int, long> keys;
    std::unique_ptr<Record> record;
    std::vector<Node*> children;
    std::mutex node_mutex;
};

Node* create_node() {
    return new Node();
}

void destroy_node(Node* node) {
    delete node;
}

long allocate_record(std::unique_ptr<Record> record) {
    auto index = reinterpret_cast<long>(record.release());
    return index;
}

void free_record(long index) {
    auto record = static_cast<Record*>(index);
    delete record;
}

Node* find_node(const Node* root, int key) {
    std::lock_guard<std::mutex> lock(root->node_mutex);

    if (root->keys.find(key) != root->keys.end())
        return &root->children[root->keys[key]];

    for (const auto& child : root->children) {
        auto found = find_node(child.get(), key);
        if (found)
            return found;
    }

    return nullptr;
}

void execute_command(Node* node, std::function<int(Record&)> success_test) {
    std::lock_guard<std::mutex> lock(node->node_mutex);

    if (node->record) {
        auto result = success_test(*node->record);
        if (!result) {
            // Log error here
        }
    }

    for (auto& child : node->children) {
        std::thread(execute_command, child.get(), success_test).detach();
    }
}

void execute_commands(Node* root, std::function<int(Record&)> success_test, int argc, char** argv) {
    std::vector<pid_t> pids;

    for (auto& child : root->children) {
        auto pid = fork();
        if (pid == 0) {
            execute_command(child.get(), success_test);
            exit(0);
        } else if (pid > 0) {
            pids.push_back(pid);
        }
    }

    for (auto pid : pids) {
        int status;
        waitpid(pid, &status, 0);
    }
}

int main(int argc, char** argv) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " command_selector success_test_function error_log" << std::endl;
        return -1;
