    private readonly Dictionary<Type, RandomGenerator> _generators;
    private readonly int _maxCallsBeforeReset;
    private int _callCount;

    public DynamicRandomValueGenerator(int maxCallsBeforeReset)
    {
        _generators = new Dictionary<Type, RandomGenerator>();
        _maxCallsBeforeReset = maxCallsBeforeReset;
        _callCount = 0;
    }

    public void AddGenerator<T>(Func<Random> randomFactory, Func<T, T> transformFunction, int minValue, int maxValue, bool isInclusive)
    {
        // Lazy initialization of generators
        if (!_generators.ContainsKey(typeof(T)))
            _generators[typeof(T)] = new RandomGenerator(randomFactory(), minValue, maxValue, isInclusive);

        // Add transformation function for the specified data type
        _generators[typeof(T)].TransformFunction = transformFunction;
    }

    public T Generate<T>()
    {
        if (_callCount % _maxCallsBeforeReset == 0)
            ResetGenerators();

        _callCount++;

        // Use the appropriate generator for the specified data type
        var generator = _generators[typeof(T)];
        return generator.GenerateValue();
    }

    public void ResetGenerator<T>()
    {
        if (_generators.ContainsKey(typeof(T)))
            _generators[typeof(T)].Reset();
    }

    private void ResetGenerators()
    {
        foreach (var generator in _generators.Values)
            generator.Reset();
    }

