    {
        _random = random;
        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusive = isInclusive;
    }

    public void Reset()
    {
        // Implement a mechanism to reset the internal state of the generator
        _currentValue = 0;
    }

    public T GenerateValue()
    {
        // Implement adaptive load balancing among generators to prevent hotspots and ensure even distribution of workload across resources

        var value = _random.Next(_minValue, _maxValue + 1);

        if (!_isInclusive)
            value--;

        if (_transformFunction != null)
            return _transformFunction(default(T)); // Replace default(T) with an appropriate default value for the data type

        return (T)(object)value;
    }
}
