#include <pthread.h>

typedef struct state {
    int id;
    struct state* next;
} State;

typedef struct fsa {
    int num_states;
    int** transitions;
    pthread_mutex_t lock;
} FSA;

State* create_state_list(int* states, int num_states, FSA* fsa) {
    State* head = NULL;
    State* current = NULL;
    for (int i = 0; i < num_states; ++i) {
        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) return NULL;
        new_state->id = states[i];
        new_state->next = NULL;
        pthread_mutex_init(&new_state->lock, NULL);

        if (!head) {
            head = new_state;
            current = head;
        } else {
            current->next = new_state;
            current = current->next;
        }
    }

    pthread_mutex_init(&fsa->lock, NULL);
    fsa->num_states = num_states;
    fsa->transitions = malloc(num_states * sizeof(int*));
    for (int i = 0; i < num_states; ++i) {
        fsa->transitions[i] = calloc(fsa->num_states, sizeof(int));
    }

    return head;
}

// Implement FSA transition function and concurrent access handling here.

void free_state_list(State* head) {
    State* current = head;
    while (head != NULL) {
        current = head;
        head = head->next;
        free(current);
    }
}
