    boost::asio::streambuf::mutable_buffers_type buffers(const_cast<char*>(logFile.rdbuf()->data()), logFile.rdbuf()->max_size());
    boost::asio::streambuf::iterator it = buffers.begin();

    while (true) {
        if (!logQueue.empty()) {
            std::string message = logQueue.front();
            logQueue.pop();
            it = boost::asio::buffers_begin(it, buffers);
            std::copy(message.begin(), message.end(), it);
