#include <iostream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <mutex>
#include <thread>
#include <atomic>
#include <queue>
#include <condition_variable>

class AttackSet {
public:
    std::string name;
    std::vector<Attack> attacks;
    std::unordered_map<Attack, std::chrono::steady_clock::time_point> cooldowns;
    std::mutex mtx;
    std::condition_variable cv;

    AttackSet(std::string name) : name(name) {}
};

class Attack {
public:
    std::string name;
    int cooldown;

    Attack(std::string name, int cooldown) : name(name), cooldowntimepoint(std::chrono::steady_clock::now()) {}

    bool isOnCooldown() {
        auto now = std::chrono::steady_clock::now();
        auto duration = now - cooldowntimepoint;
        return duration < std::chrono::seconds(cooldown);
    }

    void resetCooldown() {
        cooldowntimepoint = std::chrono::steady_clock::now();
    }

private:
    std::chrono::steady_clock::time_point cooldowntimepoint;
};

class Character {
public:
    std::unordered_map<std::string, AttackSet> attackSets;
    std::atomic<int> currentSetIndex{0};
    std::mutex mtx;

    void switchAttackSet(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx);
        if (attackSets.find(name) != attackSets.end()) {
            currentSetIndex = attackSets.begin()->second.attacks.size();
        }
    }

    Attack selectAttack(const std::string& setName, const std::string& attackName) {
        auto it = attackSets.find(setName);
        if (it != attackSets.end()) {
            AttackSet& currentSet = it->second;
            std::lock_guard<std::mutex> lock(currentSet.mtx);
            for (auto& attack : currentSet.attacks) {
                if (attack.name == attackName && !attack.isOnCooldown()) {
                    attack.resetCooldown();
                    return attack;
                }
            }
        }
        throw std::runtime_error("Attack not found or on cooldown.");
    }
};
```

This code defines an `AttackSet` class that stores a set of attacks and their respective cooldown periods. The `Character` class manages the selection process, switching between attack sets, and selecting attacks from the current set while respecting cooldown periods. It uses a mutex for thread safety and condition variables to wait for an attack to become available when it's on cooldown.

The logging mechanism can be implemented by adding a logging function that records the attack selection and its start and end times within the `selectAttack` method. To minimize performance impact during high-load scenarios, consider using a ring buffer or similar efficient data structure for logging.']

