[' Here's a C++ program that addresses your requirements. I've used `std::vector` for efficient memory management and `boost::tokenizer` for parsing lines with varying numbers of floating-point numbers. The program integrates with an existing logging system (assuming you have a function called `logError()` and `logWarning()`) and handles potential delays using a simple sleep mechanism.

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <boost/tokenizer.hpp>
#include <cmath>
#include <thread>
#include <chrono>

struct Entry {
    std::vector<double> numbers;
    double average;
};

void processEntry(Entry& entry, const std::string& line) {
    boost::tokenizer<> tokenizer(line);
    std::copy(std::begin(tokenizer), std::end(tokenizer), std::back_inserter(entry.numbers));

    size_t nonZeroCount = 0;
    for (const auto& number : entry.numbers) {
        if (number != 0.0) {
            ++nonZeroCount;
        }
    }

    double sum = 0.0;
    if (nonZeroCount >= 2) {
        sum = entry.numbers[entry.numbers.size() - 2] + entry.numbers[entry.numbers.size() - 1];
    } else {
        for (const auto& number : entry.numbers) {
            if (number != 0.0) {
                sum += number;
            }
        }
    }

    entry.average = sum / nonZeroCount;
}

void handleLine(const std::string& line, std::vector<Entry>& entries) {
    try {
        Entry entry;
        processEntry(entry, line);
        entries.push_back(std::move(entry));
    } catch (const std::exception& e) {
        logError("Error processing line: " + line + ". Reason: " + e.what());
    }
}

void readFile(const std::string& filename, std::vector<Entry>& entries) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        logError("Could not open file: " + filename);
        return;
    }

    std::string line;
    while (std::getline(file, line)) {
        handleLine(line, entries);
    }
}

void sleepFor(unsigned int milliseconds) {
    std::this_thread::sleep_for(std::chrono::milliseconds(milliseconds));
}

int main() {
    std::vector<Entry> entries;
    readFile("large_dataset.txt", entries);

    for (const auto& entry : entries) {
        logWarning("Entry: " + std::to_string(entry.average));
    }

    // Simulate potential delays in external data source access
    sleepFor(1000);

    return 0;
}
```']

