import com.fasterxml.jackson.databind.ObjectMapper;
import org.bouncycastle.crypto.TripleDES;
import org.bouncycastle.util.encoders.Base64;
import com.google.common.collect.Lists;
import java.io.IOException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static final int E_INVALID_PASSWORD = 1;
    public static final int E_CONNECTION_TITLE_NOT_SET = 2;
    public static final int E_KEY_OR_IV_EMPTY = 3;
    public static final int E_CALLBACK_FUNCTION_NULL = 4;
    public static final int E_DECRYPTION_FAILED = 5;
    public static final int E_JSON_PARSING_FAILURE = 6;
    public static final int E_UNAUTHORIZED_CLASS = 7;

    private static List<Class<?>> authorizedClasses = Lists.newArrayList(YourClass1.class, YourClass2.class); // Add your desired classes here

    public static <T> T processEncryptedData(byte[] jsonBytes, SecurityData securityData) {
        if (securityData == null ||
                securityData.password == null || securityData.password.isEmpty() ||
                securityData.connection == null || securityData.connection.getTitle().isEmpty() ||
                (securityData.connection.getEncryptionKey() == null || securityData.connection.getEncryptionKey().isEmpty()) ||
                (securityData.connection.getIV() == null || securityData.connection.getIV().isEmpty()) ||
                securityData.callback == null) {
            return null;
        }

        String decryptedMessage = decrypt(jsonBytes, securityData);
        if (decryptedMessage == null) {
            return null;
        }

        byte[] decodedJsonBytes = Base64.decode(decryptedMessage);
        ObjectMapper objectMapper = new ObjectMapper();
        T result = null;
        try {
            for (Class<?> clazz : authorizedClasses) {
                if (clazz.isAssignableFrom(objectMapper.readTree(decodedJsonBytes).getClass())) {
                    result = objectMapper.treeToValue(objectMapper.readTree(decodedJsonBytes), clazz);
                    break;
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("JSON parsing failure", e);
        }

        if (result == null) {
            return null;
        }

        if (!authorizedClasses.contains(result.getClass())) {
            logWarning("Attempt to deserialize unauthorized class: " + result.getClass().getName());
        }

        return result;
    }

    private static String decrypt(byte[] encryptedMessage, SecurityData securityData) {
        try {
            TripleDES cipher = new TripleDES(securityData.connection.getEncryptionKey().getBytes());
            cipher.init(TripleDES.DECRYPT_MODE, securityData.password.getBytes());
            return new String(cipher.doFinal(Base64.decode(encryptedMessage)));
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            logError("Decryption failed", e);
            return null;
        }
    }

    private static void logWarning(String message) {
