int is_valid_filename(const char *filename) {
    size_t len = strlen(filename);
    if (len == 0 || len > MAX_FILENAME_LENGTH) return 0;
    for (size_t i = 0; i < len; ++i) {
        if (!isalnum(filename[i]) && filename[i] != '.' && filename[i] != '_') return 0;
    }
    return 1;
}

char* generate_filename(const char *base, int version, const char *dir, int max_len, const char *exts[], int *offsets, int *keys, record *records, int num_records, int min_version, int max_version) {
    if (!is_valid_filename(base)) return "Invalid base filename.";

    size_t base_len = strlen(base);
    int has_digits = 0;
    for (size_t i = 0; i < base_len; ++i) {
        if (isdigit(base[i])) {
            has_digits = 1;
            break;
        }
    }
    int num_dots = 0;
    for (size_t i = 0; i < base_len; ++i) {
        if (base[i] == '.') ++num_dots;
    }
    char *filename = malloc(max_len + 1);
    strncpy(filename, base, min((size_t)max_len, base_len));
    int extension_index = num_dots - 1;
    if (extension_index < 0 || extension_index >= num_dots) extension_index = num_dots;
    char *extension = &filename[extension_index];
    if (*extension == '\0') *extension = "unknown";
    else if (strchr(exts, *extension) == NULL) *extension = "unknown";

    int version_str_len = snprintf(NULL, 0, "%d", version);
    char version_str[version_str_len + 1];
    snprintf(version_str, sizeof(version_str), "%d", version);

    if (strcmp(&filename[extension_index], ".txt") != 0) {
        strcat(filename, version_str);
        strcat(filename, ".txt");
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int found = 0;
    for (int i = 0; i < num_records; ++i) {
        if (keys[i] == version) {
            found = 1;
            break;
        }
    }
    if (!found) {
        int key_index = 0;
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < num_records; ++i) {
            if (keys[i] == -1) {
                key_index = i;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
        keys[key_index] = version;
        records[key_index].key = key_index;
        records[key_index].value = rand() % MAX_RANDOM_VALUE + MIN_RANDOM_VALUE;
    }

    int offset = records[version - min_version].value;
    if (offset >= max_len) {
        snprintf(filename + strlen(filename), max_len - strlen(filename) + 1, "...%d", offset);
    }

    char *fullpath = malloc(strlen(dir) + strlen(filename) + 2);
    strcpy(fullpath, dir);
    strcat(fullpath, "/");
    strcat(fullpath, filename);
    return fullpath;
}
