    // If validation fails, set valid to false and log the error.
}

void exportCertificates(const string& outputFile, const vector<Certificate>& certs) {
    ofstream out(outputFile, ios::binary);
    if (out.is_open()) {
        for (const auto& cert : certs) {
            if (cert.valid) {
                PEM_write_X509(out.rdbuf(), cert.cert);
                PEM_write_PrivateKey(out.rdbuf(), cert.key, nullptr, nullptr, nullptr, nullptr, 0);
            }
        }
        out.close();
    } else {
        cerr << "Failed to open output file: " << outputFile << endl;
    }
}

void processCAs(const vector<pair<string, string>>& caPathsAndRootCAs, const string& rootCAEnvVar, const string& outputFile) {
    MemoryPool pool;
    vector<Certificate> certs;

    for (const auto& [caPath, rootCA] : caPathsAndRootCAS) {
        X509* rootCAcert = d2i_X509(NULL, reinterpret_cast<const unsigned char*>(rootCA.c_str()), rootCA.size());
        if (!rootCAcert) {
            cerr << "Failed to parse root CA: " << rootCA << endl;
            continue;
        }

        fetchAndValidateCert(caPath, rootCA, pool, certs);

        X509_free(rootCAcert);
    }

    exportCertificates(outputFile, certs);
}

