[' Here's a C function that implements the given programming task. I've used `pthread_mutex_t` for thread safety and added functions for digit counting, extension validation, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <limits.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int max_filename_length = 255;

void validate_filename(char *filename) {
    if (!filename || strlen(filename) >= max_filename_length ||
        strchr(filename, '.') == NULL) {
        fprintf(stderr, "Invalid filename: %s\n", filename);
        exit(EXIT_FAILURE);
    }
}

int count_digits(const char *str) {
    int count = 0;
    while (*str && isdigit(*str)) {
        if (!isascii((unsigned char)*str) || (*str & 0x80) != 0) {
            return -1; // non-ASCII digit found
        }
        str++;
        count++;
    }
    return count;
}

char *get_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) {
        return "unknown";
    }
    size_t extension_length = dot - filename + 1;
    char *ext = malloc(extension_length + 1);
    strncpy(ext, filename, extension_length);
    ext[extension_length] = '\0';
    return ext;
}

void ensure_filename_unique(char *new_filename) {
    char path[max_filename_length];
    strncpy(path, new_filename, max_filename_length - 16); // reserve space for number and extension
    path[max_filename_length - 16] = '\0';

    char *dot = strrchr(path, '.');
    if (dot && strlen(get_extension(path)) > 4) { // handle extensions like ".txt.ext"
        *dot = '\0';
    }

    char filename[max_filename_length];
    sprintf(filename, "%s%d.txt", path, count_digits(path));
    strcat(filename, get_extension(filename));

    // ensure uniqueness by appending a number if the new filename already exists
    int i = 1;
    char temp_filename[max_filename_length];
    while (access(filename, F_OK) == 0) {
        sprintf(temp_filename, "%s%d.%s", path, i, get_extension(filename));
        strcpy(filename, temp_filename);
        i++;
    }
}

void init_arrays(char *new_filename, int array_size) {
    pthread_mutex_lock(&mutex);

    long *offsets = calloc(array_size, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed.\n");
        exit(EXIT_FAILURE);
    }

    int *keys = calloc(array_size, sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation for keys failed.\n");
        exit(EXIT_FAILURE);
    }

    record *records = calloc(array_size, sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&mutex);

    validate_filename(new_filename);
    ensure_filename_unique(new_filename);

    FILE *file = fopen(new_filename, "wb");
    if (!file) {
        fprintf(stderr, "Could not open file %s for writing.\n", new_filename);
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and write to the file here...
}
```

