    assert(fs::is_directory(dirPath));
    assert(!filename.empty());

    std::regex re("\\.[^.]+$");
    smatch match;
    if (std::regex_search(filename, match, re)) {
        auto extension = match.str();
        size_t pos = filename.find_last_of('.');
        std::string id;
        if (pos != std::string::npos) {
            id = filename.substr(0, pos);
            size_t numDigits = 0;
            for (auto c : id) {
