void *random_record(void *arg) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    static unsigned long seed = time(NULL);
    pthread_once(&once_control, init_rand);

    record_t *record = (record_t *) arg;
    record->value = rand_r(&seed) % MAX_VALUE;
    return NULL;
}

void init_rand() {
    srand(time(NULL));
}

pair_t *allocate_pairs(size_t size) {
    pair_t *pairs = (pair_t *) malloc(sizeof(pair_t) * size);
    if (!pairs) {
        log_event("Failed to allocate memory for pairs");
        return NULL;
    }
    log_event("Allocated memory for %zu pairs", size);
    return pairs;
}

record_t *allocate_records(size_t size) {
    record_t *records = (record_t *) malloc(sizeof(record_t) * size);
    if (!records) {
        log_event("Failed to allocate memory for records");
        return NULL;
    }
    log_event("Allocated memory for %zu records", size);

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    for (size_t i = 0; i < size; ++i) {
        pthread_create(&records[i].lock, NULL, random_record, &records[i]);
    }

    return records;
}

pair_t *get_key_offset(const record_t *records, size_t index) {
    if (index >= MAX_RECORDS) {
        log_event("Invalid index: %zu", index);
        return NULL;
    }

    pair_t *pairs = malloc(sizeof(pair_t));
    pairs->key = records[index].key;
    pairs->offset = records[index].offset;
    return pairs;
}

int deallocate(void **ptr) {
    if (!*ptr) {
        log_event("Trying to deallocate NULL pointer");
        return -1;
    }

    free(*ptr);
    *ptr = NULL;
    log_event("Deallocated memory at %p", *ptr);
    return 0;
}
