[' Here's a simplified C++ implementation that addresses most of your requirements. Note that this is a basic version and may need further optimization and error handling for real-world scenarios. Also, it uses the `<random>` library for thread-safe random number generation, which is available in modern C++ compilers.

```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <random>
#include <cstdlib>
#include <cstring>
#include <sys/mman.h>
#include <cassert>
#include <fstream>
#include <chrono>

struct Record {
    int value;
};

class MemoryManager {
public:
    MemoryManager(size_t offsetSize, size_t keySize, size_t recordCount) {
        if (offsetSize * sizeof(long) + keySize * sizeof(int) + recordCount * sizeof(Record) > 1024 * 1024) {
            throw std::runtime_error("Total memory requirement exceeds 1 MB");
        }

        offsets = static_cast<long*>(mmap(nullptr, offsetSize * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0));
        if (offsets == MAP_FAILED) {
            throw std::runtime_error("Failed to allocate memory for offsets");
        }

        keys = static_cast<int*>(mmap(nullptr, keySize * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0));
        if (keys == MAP_FAILED) {
            throw std::runtime_error("Failed to allocate memory for keys");
        }

        records.resize(recordCount);
        for (auto& record : records) {
            new (&record) Record();
        }
    }

    ~MemoryManager() {
        if (offsets != nullptr) {
            munmap(offsets, offsetSize * sizeof(long));
        }
        if (keys != nullptr) {
            munmap(keys, keySize * sizeof(int));
        }

        for (auto& record : records) {
            record.~Record();
        }
    }

    void setRandomValues(unsigned int seed, int minValue, int maxValue) {
        std::random_device rd;
        std::mt19937 gen(seed);
        std::uniform_int_distribution<> distr(minValue, maxValue);

        for (auto& record : records) {
            record.value = distr(gen);
        }
    }

private:
    size_t offsetSize;
    size_t keySize;
    size_t recordCount;
    long* offsets;
    int* keys;
    std::vector<Record> records;
};

