#include <memory>
#include <atomic>
#include <thread>
#include <mutex>
#include <chrono>

struct Value {
    int value;
};

struct Node {
    std::atomic<long> offset{0};
    int key{1};
    std::list<Value> values;
    std::shared_ptr<Node> next;
};

class DataStructureManager {
public:
    DataStructureManager(size_t nodesCount, size_t valuesPerNode, size_t minValues, size_t maxValues)
        : nodes_(nodesCount), valuesMin_(minValues), valuesMax_(maxValues) {
        initialize();
        generateRandomValues(valuesPerNode);
    }

    void generateRandomValues(size_t count) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(valuesMin_, valuesMax_);

        for (auto& node : nodes_) {
            for (size_t i = 0; i < count && i < node.values.max_size(); ++i) {
                node.values.emplace_back();
                node.values.back().value = distr(gen);
            }
        }
    }

    void monitorMemory() {
        auto start = std::chrono::system_clock::now();
        auto memoryUsage = getMemoryUsage();

        if (memoryUsage > memoryThreshold_) {
            std::cout << "Warning: Memory usage exceeded threshold (" << memoryUsage << ").\n";
        }

        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - start).count();
        if (elapsed < memoryMonitorInterval_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(memoryMonitorInterval_ - elapsed));
            monitorMemory();
        }
    }

    void initialize() {
        nodes_.front().next = &nodes_[1];
        for (size_t i = 1; i < nodes_.size() - 1; ++i) {
            nodes_[i].next.reset(new Node);
            nodes_[i].next->offset = nodes_[i - 1].offset.load() + nodes_[i - 1].values.size();
            nodes_[i].next->next = &nodes_[i + 1];
        }
        nodes_.back().next = nullptr;
    }

    std::vector<Node> nodes_;
    int valuesMin_, valuesMax_;
    size_t memoryThreshold_{50 * 1024 * 1024}; // 50 MB threshold
    size_t memoryMonitorInterval_{60}; // Monitor every minute
};

size_t getMemoryUsage() {
    // Implement a function to calculate the current system memory usage (e.g., using malloc_usable_size or /proc/self/status)
}
