void* read_file(const char *path) {
    struct stat st;
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    stat(path, &st);
    void *content = malloc(st.st_size + 1);
    ssize_t nread;
    while ((nread = read(fd, content + st.st_size - nread, nread)) > 0) {}
    close(fd);
    if (nread == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    ((char *)content)[st.st_size] = '\0';
    return content;
}
