#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* metadata;
} data_entry;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr, size_t size) {
    free(ptr);
}

data_entry** init_data_entries(size_t initial_size) {
    data_entry** entries = (data_entry**)custom_malloc((initial_size + 1) * sizeof(data_entry*));
    for (size_t i = 0; i < initial_size; ++i) {
        entries[i] = (data_entry*)custom_malloc(sizeof(data_entry));
    }
    return entries;
}

void resize_data_entries(data_entry** entries, size_t current_size, size_t new_size) {
    if (new_size <= current_size) return;

    data_entry** new_entries = init_data_entries(new_size);
    for (size_t i = 0; i < current_size; ++i) {
        new_entries[i] = entries[i];
    }
    custom_free(entries, sizeof(data_entry*) * current_size);
    entries = new_entries;
}
```

This code defines a `custom_malloc` function that logs an error message and exits the program if memory allocation fails. The `init_data_entries` function dynamically allocates memory for an array of pointers to `data_entry` structures, while the `resize_data_entries` function handles reallocation when the actual data size differs significantly from the initial estimate.']

[' Here's a C++ implementation using the Standard Template Library (STL) that addresses the given requirements:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <new>
#include <mutex>

struct Record {
    long offset;
    int key;
    int value;
    Record* next;
};

class MemoryManager {
public:
    MemoryManager(size_t numRecords, size_t keysSize) : records_(nullptr), keys_(new int[keysSize]), numRecords_(numRecords) {}

    ~MemoryManager() {
        if (records_) {
            Record* current = records_;
            while (current != nullptr) {
                Record* temp = current;
                current = current->next;
                delete temp;
            }
            delete[] keys_;
        }
    }

    Record* allocateRecord() {
        if (!records_) {
            records_ = new Record[numRecords_];
            std::srand(std::time(nullptr));
            for (size_t i = 0; i < numRecords_; ++i) {
                records_[i].offset = i;
                records_[i].key = keys_[i] = std::rand() % MAX_KEY;
                records_[i].value = std::rand() % MAX_VALUE;
                records_[i].next = (i + 1 < numRecords_) ? &records_[i + 1] : nullptr;
            }
        }

        Record* current = records_;
        for (size_t i = 0; i < numRecords_ - 1; ++i) {
            if (current->next == nullptr) {
                current->next = operator new(sizeof(Record));
                if (!current->next) {
                    throw std::bad_alloc();
                }
                current = current->next;
            }
            current = current->next;
        }

        return current;
    }

    void freeRecord(Record* record) {
        if (record == records_) {
            // Free the entire list if the first record is being freed.
            while (records_ != nullptr) {
                Record* temp = records_;
                records_ = records_->next;
                delete temp;
            }
            delete[] keys_;
        } else {
            Record* current = records_;
            while (current->next != record) {
                current = current->next;
                if (!current->next) {
                    throw std::runtime_error("Record not found");
                }
            }
            current->next = record->next;
            delete record;
        }
    }

private:
    static constexpr int MAX_KEY = 100000;
    static constexpr int MAX_VALUE = 1000000;

    std::vector<int> keys_;
    Record* records_;
    size_t numRecords_;
};
```

This implementation uses a singly linked list to manage the records, with each record maintaining a pointer to its corresponding key in the `keys_` array. The `MemoryManager` class handles memory allocation and deallocation, ensuring proper alignment and robust error handling for memory allocation failures.

To minimize contention and ensure thread safety, you can use a mutex when accessing the `records_` and `keys_` arrays concurrently from multiple threads. Additionally, the function to allocate records is optimized for both read and write performance by pre-populating the records with random values during initialization.

The trade-off between memory usage and performance in this implementation is that it uses a bit more memory than a packed array due to the use of pointers, but it offers better flexibility and scalability as the number of records grows or changes. The implementation should not significantly affect the stability and responsiveness of the entire system if used properly with appropriate synchronization mechanisms for concurrent access.

