int init_records(Record** records, size_t* count, size_t offset_size, size_t key_size, const char* env_var) {
    long seed = strtol(getenv(env_var), NULL, 10);
    time_t now = time(NULL);
    srand((unsigned int)(seed * now));

    *count = 0;
    *records = malloc(offset_size * key_size * sizeof(Record));
    if (*records == NULL) {
        perror("Memory allocation failed");
        return -1;
