        record->key = rand() % INT_MAX;
        while ((*count > 0 && record->key == (*records)[*count - 1].key)) {
            record->key = rand() % INT_MAX;
        }
        record->offset = i * sizeof(Record);
        record->status = 0;
        ++(*count);
    }

    return 0;
}

void free_records(Record* records, size_t count) {
    free(records);
}
