            // Notify administrators of critical failures
            // ...
        }
    }

    private ICryptoTransform CreateDecryptor()
    {
        var decryptor = _aes.CreateDecryptor(_aes.Key, _aes.IV);
        return new CbcMode { Mode = CipherMode.CBC, Padding = PaddingMode.PKCS7 }.CreateDecryptor(decryptor.CreateDecryptor());
    }

    private byte[] Decrypt(ICryptoTransform decryptor, byte[] encryptedMessage)
    {
        using (var ms = new MemoryStream(encryptedMessage))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            return cs.ReadAllBytes();
        }
    }
