void generate_unique_records(Record** records, size_t* offsets, size_t* keys, size_t count, size_t max_value) {
    for (size_t i = 0; i < count; ++i) {
        int found = 0;
        do {
            (*records)[i].value = rand() % max_value;
            for (size_t j = 0; j < i; ++j) {
