public class ShellCommandExecutor {
    private final ExecutorService executor;

    public ShellCommandExecutor(int threadPoolSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
    }

    // Method to execute a shell command asynchronously
    public Future<?> execute(String command, File fileToDeleteBeforeExecution) {
        ProcessBuilder processBuilder = new ProcessBuilder("/bin/bash", "-c", command);
        if (fileToDeleteBeforeExecution != null && fileToDeleteBeforeExecution.exists()) {
            processBuilder.redirectErrorStream(true);
            Process process = null;
            try {
                process = processBuilder.start();
                Files.deleteIfExists(fileToDeleteBeforeExecution.toPath());
            } catch (IOException e) {
                // Handle exceptions
            } finally {
                if (process != null) {
                    process.destroy();
                }
            }
        }
        return executor.submit(() -> {
            try {
                Process process = processBuilder.start();
                // Non-blocking I/O for file outputs
                InputStream inputStream = process.getInputStream();
                OutputStream outputStream = new BufferedOutputStream(new FileOutputStream("/dev/null"));
                StreamGobbler errorStreamGobbler = new StreamGobbler(process.getErrorStream(), "ERROR");
                StreamGobbler inputStreamGobbler = new StreamGobbler(inputStream, "OUTPUT");

                // Start the thread for error stream
                errorStreamGobbler.start();

                // Start the thread for input stream
                inputStreamGobbler.start();

                // Wait for the process to finish
                process.waitFor();
            } catch (IOException | InterruptedException e) {
                // Handle exceptions
            }
        });
    }
}
