// Function to allocate aligned memory for an array of longs and ints
void* align_alloc(size_t size, size_t alignment) {
    void* ptr = malloc(size + alignment - 1);
    if (ptr != NULL) {
        size_t remainder = (size_t)(ptr) % alignment;
        if (remainder > 0) {
            memmove(ptr + remainder, ptr, size);
            memset(ptr, 0, remainder);
        }
    }
    return (void*)((uintptr_t)ptr + alignment - remainder);
}
