```javascript
const fs = require('fs');
const path = require('path');

async function readJsonFiles(directory, mode) {
  const files = await new Promise((resolve, reject) => {
    const results = [];
    const walk = (dir, file, next) => {
      const ext = path.extname(file);
      if (ext === '.json' && mode === 'async') {
        fs.readFile(file, 'utf8', (err, data) => {
          if (err) return reject(err);
          try {
            results.push(JSON.parse(data));
          } catch (e) {
            console.error(`Error parsing ${file}:`, e);
          }
          next();
        });
      } else if (!mode || ext === '.json') {
        next();
      } else {
        fs.stat(file, (err, stat) => {
          if (err) return reject(err);
          if (stat && stat.isDirectory()) walk(file, ...fs.readdirSync(file));
          else next();
        });
      }
    };

    fs.readdir(directory, (err, files) => {
      if (err) return reject(err);
      walk(directory, ...files, () => resolve(results));
    });
  });

  return files;
}
```

