const blueslip = require('blueslip'); // Mock environment library
const fs = require('fs');
const path = require('path');
const chokidar = require('chokidar'); // File system monitoring utility
const child_process = require('child_process'); // For spawning processes

function executeTests(config) {
  const testsDir = config.testsDir;
  let testFiles, parallelMode, loggingLevel;

  try {
    testFiles = fs.readdirSync(testsDir).filter(file => path.extname(file) === '.js');
  } catch (err) {
    console.error(`Error reading tests directory: ${err}`);
    return;
  }

  if (testFiles.length === 0) {
    console.log('No test files found in the specified directory.');
    return;
  }

  parallelMode = config.parallelMode || false;
  loggingLevel = config.loggingLevel || 'info';

  const watcher = chokidar.watch(testsDir, { persistent: true });

  watcher.on('add', (file) => {
    if (!testFiles.includes(file)) {
      testFiles.push(file);
    }
  });

  watcher.on('change', (file) => {
    const index = testFiles.indexOf(file);
    if (index > -1) {
      testFiles.splice(index, 1);
      runTests(testFiles, parallelMode, loggingLevel);
      testFiles.push(file);
    }
  });

  function runTests(files, parallel, logLevel) {
    const tests = files.map(file => {
      const testPath = path.join(testsDir, file);
      return new Promise((resolve, reject) => {
        try {
          const testModule = require(testPath);
          const testFn = testModule.default || testModule;
          testFn({ blueslip })
            .then(() => resolve())
            .catch(err => {
              console.error(`Test "${file}" failed: ${err}`);
              reject(err);
            });
        } catch (err) {
          console.error(`Error loading test module for "${file}": ${err}`);
          reject(err);
        }
      });
    });

    if (parallel) {
      Promise.all(tests)
        .then(() => console.log('All tests passed.'))
        .catch(err => console.error('One or more tests failed:', err));
    } else {
      let currentTest = 0;
      function nextTest() {
        if (currentTest < tests.length) {
          tests[currentTest++]
            .then(() => nextTest())
            .catch(err => console.error(`Test "${files[currentTest - 1]}" failed: ${err}`));
        } else {
          console.log('All tests passed.');
        }
      }
      nextTest();
    }
  }
}
```

**C (lineCounter)**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

void usage(char *progname) {
  printf("Usage: %s [--manpage] [-cs] [-o output_file]\n", progname);
}

int countLines(int fd) {
  char buffer[4096];
  ssize_t bytesRead;
  int lineCount = 0;

  while ((bytesRead = read(fd, buffer, sizeof(buffer))) > 0) {
    char *lineStart = buffer;
    char *lineEnd = buffer + bytesRead;

    while (lineStart < lineEnd && (*lineStart == '\n' || *lineStart == '\r')) {
      lineStart++;
      lineCount++;
    }

    while (lineStart < lineEnd && *lineStart != '\0') {
      if (*lineStart++ == '\n' || *lineStart == '\r') {
        lineCount++;
      }
    }
  }

  return lineCount;
}

int main(int argc, char **argv) {
  int opt;
  char *inputFile = NULL;
  char *outputFile = NULL;
  int stats = 0;

  while ((opt = getopt(argc, argv, "m:o:cs")) != -1) {
    switch (opt) {
      case 'm':
        usage(argv[0]);
        return 0;
      case 'o':
        outputFile = optarg;
        break;
      case 'c':
        stats = 1;
        break;
      default:
        usage(argv[0]);
        return 1;
    }
  }

  if (optind < argc - 1) {
    usage(argv[0]);
    return 1;
  }

  inputFile = argv[optind];

  int fd = open(inputFile, O_RDONLY);
  if (fd == -1) {
    perror("Error opening file");
    return 1;
  }

  int lineCount = countLines(fd);
  close(fd);

  if (stats) {
    printf("File %s has %d lines.\n", inputFile, lineCount);
  } else if (outputFile) {
    FILE *outFd = fopen(outputFile, "w");
    if (!outFd) {
      perror("Error opening output file");
      return 1;
    }

    fprintf(outFd, "%s\n%d\n", inputFile, lineCount);
    fclose(outFd);
  }

  return 0;
}
```']

