from collections import deque
from typing import Dict, List, Union

class Session:
    def __init__(self, id: str, url: str, data: Dict):
        self.id = id
        self.url = url
        self.data = data
        self.children: Dict[str, 'Session'] = {}

    def add_child(self, child: 'Session'):
        self.children[child.id] = child

    def update(self, field_names: List[str], batch: bool):
        updated_field_names = deque(field_names)

        def _update(session: Union['Session', dict]):
            for field in updated_field_names:
                if isinstance(session, Session):
                    if field in session.data and not session.id == field:
                        updated_field_names.appendleft(field)
                    _update(getattr(session, field, None))
                elif isinstance(session, dict):
                    if field in session:
                        updated_field_names.appendleft(field)
                        session[field] = update_value(session[field], batch)

        def update_value(value, batch: bool):
            if not batch:
                return update_individually(value)
            else:
                return update_batch(value)

        def update_individually(value):
            if isinstance(value, list):
                return [update_individually(item) for item in value]
            elif isinstance(value, dict):
                return {k: update_individually(v) for k, v in value.items()}
            else:
                return None

        def update_batch(value):
            if isinstance(value, list):
                return [update_batch(item) for item in value]
            elif isinstance(value, dict):
                return {k: update_batch(v) for k, v in value.items()}
            else:
                return value

        _update(self.data)

        def update_field_names_inplace(field_names: List[str], target: str, is_child: bool):
            if not field_names:
                return
            for i, field in enumerate(field_names):
                if field == target or (is_child and i == 0):
                    field_names.insert(i, target)
                    break
            if target not in field_names:
                field_names.append(target)

        def update_session_field_names(session: Union['Session', dict], field_names: List[str]):
            if isinstance(session, Session):
                for child_id, child in session.children.items():
                    update_session_field_names(child, field_names)
            elif isinstance(session, dict):
                update_field_names_inplace(list(session.keys()), *field_names)

        update_session_field_names(self.data, field_names)

    def save(self):
        # Implement session persistence strategy here
        pass

def manage_session(session_id: str, url: str, field_names: List[str]):
    # Assuming sessions are stored in a global dictionary called SESSIONS
    for session in SESSIONS.values():
        if session.id == session_id:
            session.update(field_names, batch=True)  # Set to True for batch mode
            break

def update_field_names_inplace(field_list: List[str], target: str, is_child: bool):
    if not field_list:
        return
    for i, field in enumerate(field_list):
        if field == target or (is_child and i == 0):
            field_list.insert(i, target)
            break
    if target not in field_list:
        field_list.append(target)
```

