        this.timeoutMillis = timeoutMillis;
        this.dbUrl = dbUrl;
        this.dbUsername = dbUsername;
        this.dbPassword = dbPassword;
        this.connections = new ArrayList<>();
        this.executor = Executors.newCachedThreadPool();
