            PreparedStatement preparedStatement = connection.prepareStatement(sqlCommand);
            for (int i = 0; i < parameters.size(); i++) {
                preparedStatement.setObject(i + 1, parameters.get(i));
            }
            CallableChannelFuture<IDataReader> future = new CallableChannelFuture<>();
            executor.submit(() -> {
                try (ResultSet resultSet = preparedStatement.executeQuery()) {
                    IDataReader dataReader = new DataReaderImpl(resultSet);
                    future.complete(dataReader);
                } catch (SQLException e) {
                    LOGGER.error("Error executing SQL command", e);
                    future.fail(e);
                }
            });
            return future;
        } catch (SQLException e) {
            LOGGER.error("Error acquiring connection from the pool", e);
            // Handle configuration errors gracefully and provide sensible defaults at runtime
        } finally {
            if (connection != null && !connections.contains(connection.unwrap(ChannelFuture.class))) {
                connections.add(connection.unwrap(ChannelFuture.class));
            }
        }
    }

