#include <boost/system/error_code.hpp>

struct Record {
    int value;
};

void InitializeRecordsAndStartWebsite(const std::string& dirPath, const std::string& siteName, const std::function<std::istream*(const std::string&)>& configService) {
    boost::filesystem::path path(dirPath);
    if (!boost::filesystem::exists(path) || !boost::filesystem::is_directory(path)) {
        std::cerr << "Error: Invalid directory path." << std::endl;
        return;
    }

    boost::filesystem::path configFile = path / "web.config";
    if (!boost::filesystem::exists(configFile)) {
        auto serviceStream = configService("remote_config_service");
        if (serviceStream) {
            std::stringstream ss;
            *serviceStream >> ss;
            boost::property_tree::xml_parser::read_xml(ss, pt);

            // Assuming the XML structure is as follows:
            // <config>
            //   <sites>
            //     <site name="[SITE_NAME]">
            //       <!-- Site-specific configuration -->
            //     </site>
            //   </sites>
            auto sites = pt.get_child("config.sites");
            for (auto& site : sites) {
                if (site.get<std::string>("name") == siteName) {
                    configFile = path / "web_" + siteName + ".config";
                    boost::filesystem::create_directories(path / "web");
                    std::ofstream out(configFile.string());
                    out << site.get_child("<site>").data();
                    break;
                }
            }
        } else {
            std::cerr << "Error: Unable to connect to remote configuration service." << std::endl;
        }
    }

    // Parse the web.config file or the generated one from the remote service
    boost::property_tree::xml_parser::read_xml(std::ifstream(configFile), pt);

    // Assuming the XML structure is as follows:
    // <site name="[SITE_NAME]">
    //   <!-- Site-specific configuration -->
    // </site>
    auto site = pt.get_child("<site>" + siteName + "</site>");

    if (site.empty()) {
        std::cerr << "Error: No matching site found in the configuration." << std::endl;
    } else if (site.size() > 1) {
        std::cerr << "Error: Multiple sites with the same name found in the configuration." << std::endl;
    }

    int offsetSize = static_cast<int>(std::stoi(site.get<std::string>("offset_size", "10000")));
    int keySize = static_cast<int>(std::stoi(site.get<std::string>("key_size", "10000")));
    std::vector<long> offsets(offsetSize);
    std::vector<int> keys(keySize);
    std::vector<Record> records(keySize);

    srand(time(nullptr));
    for (auto& record : records) {
        record.value = rand() % static_cast<int>(std::stoi(site.get<std::string>("record_range", "10000")));
    }

    std::cout << "Initialized records and started website." << std::endl;

    // Set the environment variable for the directory path
    std::string envVarName = "WEB_DIR";
    if (getenv(envVarName)) {
        std::string currentValue = getenv(envVarName);
        setenv(envVarName.c_str(), dirPath.c_str(), 1);
        std::cout << "Updated environment variable: " << envVarName << "=" << dirPath << ", previous value: " << currentValue << std::endl;
    } else {
        putenv(const_cast<char*>(dirPath.c_str()));
        std::cout << "Set new environment variable: " << envVarName << "=" << dirPath << std::endl;
    }
}
```

