2. Implementing the function:

```cpp
#include <algorithm>
#include <sstream>

std::vector<std::string> transformAndEnsureUniqueness(std::vector<std::string>& vec, const std::map<std::string, std::string>& transformations, size_t index, size_t key) {
    // Create a new vector to store the transformed and unique strings
    std::vector<std::string> result;

    // Apply transformation if the index is valid
    if (index < vec.size()) {
        auto it = transformations.find(vec[index]);
        if (it != transformations.end()) {
            result.push_back(it->second);
        } else {
            result.push_back(vec[index]); // Use the original string if no transformation is found
        }
    } else {
        result.push_back(vec.back()); // Use the last element of the vector if the index is out of bounds
    }

    // Create a set to store unique strings (considering transformations)
    std::unordered_set<std::string, std::hash<std::string>> uniqueStrings;

    // Add the first transformed string to the set and check for uniqueness
    if (!uniqueStrings.emplace(result.front()).second) {
        throw std::runtime_error("Initial string is not semantically unique");
    }

    // Transform and add remaining strings to the set, checking for uniqueness
    for (size_t i = 1; i < result.size(); ++i) {
        auto it = transformations.find(result[i]);
        if (it != transformations.end()) {
            std::string transformedString = it->second;
            // Check for uniqueness using the set
            if (!uniqueStrings.emplace(transformedString).second) {
                throw std::runtime_error("Transformed string is not semantically unique");
            }
            result[i] = transformedString;
        } else {
            // Use the original string if no transformation is found
            result[i] = result[i];
        }
    }

    return result;
}
```

