using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;

    public float MinFloat
    {
        get => minFloat;
        set => minFloat = Mathf.Max(value, 0);
    }

    public float MaxFloat
    {
        get => maxFloat;
        set => maxFloat = Mathf.Min(value, float.MaxValue);
    }

    public int MinInt
    {
        get => minInt;
        set => minInt = Math.Max(value, int.MinValue);
    }

    public int MaxInt
    {
        get => maxInt;
        set => maxInt = Math.Min(value, int.MaxValue);
    }

    public float GetRandomFloat(bool inclusive)
    {
        if (inclusive) return UnityEngine.Random.Range(minFloat, maxFloat);
        else return UnityEngine.Random.Range(minFloat + 0.001f, maxFloat - 0.001f);
    }

    public int GetRandomInt(bool inclusive)
    {
        if (inclusive) return UnityEngine.Random.Range(Mathf.RoundToInt(minFloat), Mathf.RoundToInt(maxFloat));
        else return UnityEngine.Random.Range((int)Mathf.Ceil(minFloat), (int)Mathf.Floor(maxFloat)) - 1;
    }

    public static void EvaluateArrayPerformance(int[] array)
    {
        if (array == null || array.Length == 0)
        {
            Console.WriteLine("Empty array provided.");
            return;
        }

        var watch = new System.Diagnostics.Stopwatch();
        watch.Start();

        int maxValue = array[0];
        foreach (var value in array)
        {
            if (value > maxValue) maxValue = value;
        }

        watch.Stop();
        Console.WriteLine($"Largest integer found: {maxValue}");
        Console.WriteLine($"Time taken to determine the largest integer: {watch.ElapsedMilliseconds} milliseconds.");
    }
}
```

