using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Win32;

public class XmlHelper
{
    private const int MaxDepth = 100;
    private static readonly Dictionary<string, string> _envVariables = new Dictionary<string, string>();
    private static readonly object _lock = new object();

    public static List<XmlNode> GetElementsByXPath(string xml, string xpath)
    {
        if (string.IsNullOrEmpty(xml))
        {
            Console.WriteLine("Warning: XML document is null.");
            return new List<XmlNode>();
        }

        XmlDocument doc = new XmlDocument();
        try
        {
            doc.LoadXml(xml);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return new List<XmlNode>();
        }

        var nodes = new List<XmlNode>();
        GetNodesByXPath(doc, xpath, nodes, 0);

        return nodes;

        void GetNodesByXPath(XmlNode node, string xpath, List<XmlNode> nodes, int depth)
        {
            if (depth > MaxDepth)
                return;

            var currentNodes = node.SelectNodes(xpath);
            if (currentNodes != null)
            {
                foreach (var node in currentNodes)
                    nodes.Add(node);
            }

            foreach (XmlNode child in node.ChildNodes)
                GetNodesByXPath(child, xpath, nodes, depth + 1);
        }
    }

    public static string GetOrCreateDirectory(string directoryName, string envVariableName = null)
    {
        lock (_lock)
        {
            if (!_envVariables.TryGetValue(envVariableName, out var envVar))
            {
                envVar = Path.Combine(Environment.CurrentDirectory, envVariableName);
                _envVariables[envVariableName] = envVar;
            }

            string directoryPath = Path.Combine(envVar, directoryName);

            if (!Directory.Exists(directoryPath))
            {
                try
                {
                    Directory.CreateDirectory(directoryPath);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error creating directory: {ex.Message}");

                    // Implement retry logic with different user accounts if needed
                }
            }

            return directoryPath;
        }
    }
}
