[' I'll provide a simplified version of the requested function in C++11 with pthreads and boost libraries for concurrency, caching, and random shuffling. Note that this is a complex task and the following code snippet only covers the main aspects:

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <boost/random/mt19937.hpp>
#include <boost/random/uniform_int_distribution.hpp>
#include <boost/thread/thread.hpp>
#include <boost/container/small_vector.hpp>
#include <boost/unordered_map.hpp>
#include <pthread.h>

struct Record {
    int value;
    std::string id;
    double* data;
};

class RecordCache {
public:
    RecordCache(size_t maxSize) : cache_(maxSize), nextId_(0) {}

    Record getOrCreateRecord(const std::string& id) {
        auto it = cache_.find(id);
        if (it != cache_.end())
            return *it;

        Record record{nextId_++, id, new double};
        cache_[id] = std::move(record);
        return record;
    }

private:
    boost::unordered_map<std::string, Record> cache_;
    int nextId_;
};

void printRecord(const Record& record) {
    std::cout << "ID: " << record.id << ", Value: " << record.value
              << ", Data: " << *record.data << std::endl;
}

void* generateAndShuffleRecords(void* arg) {
    auto& cache = *(static_cast<RecordCache*>(arg));
    boost::random::mt19937 gen;
    boost::random::uniform_int_distribution<> distr(0, 100);

    for (size_t i = 0; i < 100; ++i) {
        Record record = cache.getOrCreateRecord("id" + std::to_string(i));
        record.value = distr(gen);
        record.data[0] = static_cast<double>(record.value) * i / 10.0;
    }

    std::vector<Record> records(cache.begin(), cache.end());
    std::shuffle(records.begin(), records.end(), gen);

    for (const auto& record : records) {
        printRecord(record);
    }

    return nullptr;
}

int main() {
    RecordCache cache(100);
    boost::container::small_vector<pthread_t, 4> threads;
    for (size_t i = 0; i < threads.capacity(); ++i) {
        pthread_create(&threads[i], nullptr, &generateAndShuffleRecords, &cache);
    }

    for (auto& thread : threads) {
        pthread_join(thread, nullptr);
    }

    // Free memory
    for (auto& record : cache) {
        delete record.second.data;
    }

    return 0;
}
```

This code creates a `RecordCache` class that manages the records and their unique identifiers, ensuring efficient memory usage. The `generateAndShuffleRecords` function generates and shuffles records concurrently using pthreads. The main function initializes threads, starts them, waits for them to finish, and frees allocated memory.']

