typedef struct DataPacket {
    unsigned int id;
    time_t timestamp;
    size_t payload_size;
    bool error;
} DataPacket;

struct MemoryPool {
    size_t capacity;
    DataPacket* packets;
    size_t allocated;
};

void* memory_pool_alloc(struct MemoryPool* pool) {
    if (pool->allocated < pool->capacity) {
        return &pool->packets[pool->allocated++];
    }
    return NULL;
}

void log_event(const char* event, ...) {
    // Implement logging using a thread-safe logging library
}

struct DataPacketReader {
    FILE* file;
    gzFile gz_file;
    bool is_gzipped;
    struct MemoryPool pool;
};

void data_packet_reader_init(struct DataPacketReader* reader, const char* filename) {
    reader->file = fopen(filename, "rb");
    if (!reader->file) return;

    struct stat st;
    fstat(fileno(reader->file), &st);

    reader->is_gzipped = (st.st_size < 10 || memcmp(st.st_name, ".gz", 3) == 0);
    if (reader->is_gzipped) {
        reader->gz_file = gzopen(filename, "rb");
    }
}

void data_packet_reader_deinit(struct DataPacketReader* reader) {
    if (reader->gz_file) gzclose(reader->gz_file);
    fclose(reader->file);
}

DataPacket* data_packet_reader_read(struct DataPacketReader* reader) {
    char buffer[1024];
    size_t read = 0;

    if (reader->is_gzipped) {
        read = gzread(reader->gz_file, buffer, sizeof(buffer));
    } else {
        read = fread(buffer, 1, sizeof(buffer), reader->file);
    }

    if (read <= 0) return NULL;

    char delimiter[] = ",";
    char* token = strtok(buffer, delimiter);

    DataPacket* packet = memory_pool_alloc(&reader->pool);
    if (!packet) {
        log_event("Memory allocation error");
        return NULL;
    }

    packet->id = atoi(token);
    token = strtok(NULL, delimiter);
    time_t timestamp = strtol(token, NULL, 10);
    if (timestamp == (time_t)-1) {
        log_event("Invalid timestamp");
        free(packet);
        return NULL;
    }
    packet->timestamp = timestamp;

    token = strtok(NULL, delimiter);
    packet->payload_size = atoi(token);
    if (packet->payload_size < MIN_PAYLOAD_SIZE) {
        log_event("Filtered: Payload size too small");
        free(packet);
        return NULL;
    }

    token = strtok(NULL, delimiter);
    packet->error = atoi(token) != 0;

    return packet;
}

// Implement thread-safe read and write lock mechanisms for the memory pool

int main() {
    // Initialize logging system and thread-safe data structure

    struct DataPacketReader reader;
    data_packet_reader_init(&reader, "input.csv.gz");

    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_data_packets, &reader);
    }

    // Wait for all threads to finish

    data_packet_reader_deinit(&reader);

    return 0;
}
```

