                    free(string_array);
                    free(current_processor->items);
                    free(current_task->item1);
                    free(current_task->item2);
                    if (current_task) free(current_task);
                    exit(EXIT_FAILURE);
                }
            }

            item* current_item = current_processor->items[current_processor->count];
            current_item->id = item_count++;
            current_item->value = (double)rand() / RAND_MAX * 200.0 - 100.0;
        }
    }

    srand(time(NULL)); // Seed random number generator for each call
}
