1. Memory management and data structures:

```rust
use std::sync::{Arc, Mutex};
use rand::{thread_rng, Rng};
use std::collections::HashMap;

struct Record {
    id: i32,
    offset: i64,
    value: f64,
}

struct DataManager {
    offsets: Vec<i64>,
    keys: Vec<i32>,
    values: Vec<f64>,
    records: Arc<Mutex<HashMap<i32, Record>>>,
}

impl DataManager {
    fn new() -> Self {
        let offsets = vec![0; MAX_OFFSETS];
        let keys = vec![0; MAX_KEYS];
        let values = vec![0.0; MAX_VALUES];
        let records = Arc::new(Mutex::new(HashMap::new()));

        Self { offsets, keys, values, records }
    }

    fn allocate(&mut self) -> Result<(), ()> {
        // Allocate memory for offsets, keys, and values
        if self.offsets.len() >= MAX_OFFSETS {
            return Err(());
        }
        let offset = self.offsets[self.offsets.len() - 1];
        self.offsets.push(offset + 1);

        if self.keys.len() >= MAX_KEYS {
            return Err(());
        }
        let key = self.keys[self.keys.len() - 1] + 1;
        self.keys.push(key);

        if self.values.len() >= MAX_VALUES {
            return Err(());
        }
        let value = rand::thread_rng().gen();
        self.values.push(value);

        let record = Record { id: key, offset, value };
        self.records.lock().unwrap().insert(key, record);
        Ok(())
    }

    // ... (Implement other methods like deallocate, get_record, search, compress, etc.)
}
```

