void resize_linear(struct Data*** grid, int* capacity, int* size) {
    *capacity *= 2;
    struct Data** new_grid = realloc(*grid, sizeof(struct Data*) * (*capacity));
    if (new_grid == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *grid = new_grid;
}

void resize_exponential(struct Data*** grid, int* capacity, int* size) {
    *capacity *= 2;
    struct Data** new_grid = realloc(*grid, sizeof(struct Data*) * (*capacity));
    if (new_grid == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = *size; i < *capacity; ++i) {
        new_grid[i] = malloc(sizeof(struct Data));
        if (new_grid[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
