#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

Record* create_records(size_t size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < size; ++i) {
        records[i].key = rand() % MAX_KEY + MIN_KEY;
        records[i].offset = rand() % MAX_OFFSET + MIN_OFFSET;
        records[i].value = ((double)rand() / RAND_MAX) * (MAX_VALUE - MIN_VALUE) + MIN_VALUE;
        pthread_mutex_init(&records[i].mutex, NULL);
    }

    return records;
}

Record* get_record(Record *records, size_t index) {
    if (index >= sizeof(records) / sizeof(Record)) return NULL;
    pthread_mutex_lock(&records[index].mutex);
    Record *result = &records[index];
    pthread_mutex_unlock(&result->mutex);
    return result;
}

void* search_record(void *arg, int key) {
    Record *records = arg;
    size_t size = sizeof(records) / sizeof(Record);
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key == key) return &records[i];
    }
    return NULL;
}
```

