```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef enum { A, B, C, D, E } Category;

struct Record {
    long offset;
    int key;
    char status;
    Category category;
};

struct HashSet {
    unsigned int capacity;
    unsigned int size;
    bool* data;
};

void hash_set_init(struct HashSet* set, unsigned int capacity) {
    set->capacity = capacity;
    set->size = 0;
    set->data = calloc(capacity, sizeof(bool));
}

bool hash_set_insert(struct HashSet* set, int key) {
    if (set->size >= set->capacity) {
        unsigned int new_capacity = set->capacity * 2;
        bool* new_data = realloc(set->data, new_capacity * sizeof(bool));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            return false;
        }
        set->data = new_data;
        set->capacity = new_capacity;
    }
    return set->data[key] == false && (set->data[key] = true);
}

void record_init(struct Record* record, long offset, int key) {
    record->offset = offset;
    record->key = key;
    record->status = 0;
    record->category = E;
}

Category assign_category(int key) {
    if (key >= 3000 && key <= 3999)
        return D;
    else if (key >= 2000 && key <= 2999)
        return C;
    else if (key >= 1000 && key <= 1999)
        return B;
    else if (key >= 0 && key <= 999)
        return A;
    return E;
}

int allocate_records(unsigned int* offsets, unsigned int* keys, char* statuses, struct HashSet* used_keys, struct Record** records, unsigned int num_records, unsigned int record_size, unsigned int memory_limit) {
    unsigned int total_memory = 3 * num_records * sizeof(unsigned long) + num_records * sizeof(struct Record);
    if (total_memory > memory_limit) {
        fprintf(stderr, "Insufficient memory\n");
        return -1;
    }

    *offsets = calloc(num_records, sizeof(unsigned long));
    if (!*offsets) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    *keys = malloc(num_records * sizeof(int));
    if (!*keys) {
        free(*offsets);
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    *statuses = calloc(num_records, sizeof(char));
    if (!*statuses) {
        free(*keys);
        free(*offsets);
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    *records = malloc(num_records * record_size * sizeof(struct Record));
    if (!*records) {
        free(*statuses);
        free(*keys);
        free(*offsets);
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    struct Record* record_ptr = *records;
    for (unsigned int i = 0; i < num_records; ++i) {
        int key = 0;
        while (!hash_set_insert(used_keys, key)) {
            key = rand() % RAND_MAX + 1; // Generate random number within the range of unsigned int (0-RAND_MAX)
        }
        record_init(record_ptr++, i, key);
        record_ptr->category = assign_category(key);
    }

    return 0;
}

int main() {
    unsigned int offsets[10];
    unsigned int keys[10];
    char statuses[10];
    struct HashSet used_keys;
    struct Record records[10];

    hash_set_init(&used_keys, 4096);

    if (allocate_records(offsets, keys, statuses, &used_keys, (struct Record*)&records, 10, sizeof(records[0]), 50000)) {
