// Define tree node structure
typedef struct Node {
    void* data;
    struct Node* left, *right;
    size_t height;
} Node;

// Global memory pool for nodes
Node* mem_pool = NULL;
size_t mem_pool_capacity = 0;

// Function to allocate a node from the memory pool
Node* alloc_node() {
    if (mem_pool_capacity > 0) {
        Node* node = mem_pool + --mem_pool_capacity;
        node->left = node->right = NULL;
        node->height = 0;
        return node;
    }
    return malloc(sizeof(Node));
}

// Function to free a node and return it to the memory pool
void free_node(Node* node) {
    if (mem_pool_capacity < mem_pool_capacity_max) {
        node->left = node->right = NULL;
        node->height = 0;
        memmove(mem_pool + mem_pool_capacity, node, sizeof(Node));
        ++mem_pool_capacity;
    } else {
        free(node);
    }
}

// Implement insertion, deletion, and traversal functions here
// ...

// Function to destroy the tree and free all allocated memory
void destroy_tree(Node* root) {
    if (root == NULL) return;

    destroy_tree(root->left);
    destroy_tree(root->right);

    free_node(root);
}

// Implement logging functions here
// ...

// Main function to handle user input and manage the tree
int main() {
    // Initialize memory pool with a certain capacity
    mem_pool = mmap(NULL, mem_pool_capacity_max * sizeof(Node), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem_pool == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

