```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    float temperature;
    char condition[3]; // Max 3 characters for weather conditions
} measurement;

void generate_filename(char *base, int version, int max_length, char *directory, char *output) {
    int len = strlen(base);
    int dot_index = -1;
    for (int i = 0; i < len; ++i) {
        if (base[i] == '.') {
            dot_index = i;
            break;
        }
    }

    if (dot_index == -1) {
        strcpy(output, "unknown");
    } else {
        int extension_len = len - dot_index - 1;
        snprintf(output, max_length, "%.*s%d.txt", dot_index, base, version);
        if (extension_len + 5 > max_length) {
            strcpy(output + max_length - 3, "...");
        }
    }

    strcat(output, directory);
    strcat(output, "/");
}

record *init_records(int size) {
    record *arr = (record *)malloc(size * sizeof(record));
    if (!arr) return NULL;

    for (int i = 0; i < size; ++i) {
        arr[i].value = rand() % 101; // Random value between 0 and 100
    }

    return arr;
}

measurement *init_measurements(int size) {
    measurement *arr = (measurement *)malloc(size * sizeof(measurement));
    if (!arr) return NULL;

    for (int i = 0; i < size; ++i) {
        arr[i].temperature = (float)(rand() % 101) - 50; // Random temperature between -50 and 50
        strncpy(arr[i].condition, "Rain", sizeof(arr[i].condition)); // Default weather condition: Rain
    }

    return arr;
}

int main() {
    char base[] = "weather_data.csv";
    int version = 1;
    int max_length = 256;
    char directory[] = "/path/to/save/files";

    char filename[max_length];
    generate_filename(base, version, max_length, directory, filename);

    int records_size = 10000;
    record *records = init_records(records_size);
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        return 1;
    }

    measurement *measurements = init_measurements(records_size);
    if (!measurements) {
        free(records);
        printf("Error: Failed to allocate memory for measurements.\n");
        return 1;
    }

    // Continue with processing the data...

    return 0;
}
```

This code generates a unique filename based on the given parameters, dynamically allocates and initializes multiple arrays as specified, and avoids modifying global state by using local variables. The function is not thread-safe in its current form but can be made so by adding synchronization mechanisms for concurrent access if needed.']

