using System;

public class DynamicDataProcessor
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;

    public DynamicDataProcessor(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        this.minFloat = Math.Min(maxFloat, minFloat);
        this.maxFloat = Math.Max(maxFloat, minFloat);
        this.minInt = Math.Min(maxInt, minInt);
        this.maxInt = Math.Max(maxInt, minInt);
    }

    public float NextFloat()
    {
        return (float)new Random().NextDouble() * (maxFloat - minFloat) + minFloat;
    }

    public int NextInt()
    {
        return new Random().Next(minInt, maxInt + 1);
    }

    public override string ToString()
