typedef struct Product {
    int id;
    float price;
    char* name;
    char* manufacturer;
} Product;

struct MemoryBlock {
    void* data;
    size_t capacity;
    size_t allocated;
};

static struct MemoryBlock products, names, manufacturers;
static LoggingInitParams params = { .identity = "ProductManager", .category = "Memory" };
static Logger log = LOG4C_NULL;

void init_logging() {
    log = LoggingFactoryInit(&params);
}

void log_memory(const char* action, const void* ptr, size_t bytes) {
    if (log != LOG4C_NULL) {
        LoggingEvent event = (LoggingEvent){
            .level = LOG4C_INFO_LEVEL,
            .category = params.category,
            .identity = params.identity,
            .message = action,
            .data1 = ptr,
            .data2 = bytes,
        };
        LoggingEventPush(log, &event);
    }
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        log_memory("Failed to allocate", ptr, size);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

char* safe_strdup(const char* str) {
    char* copy = strdup(str);
    if (copy == NULL) {
        log_memory("Failed to duplicate string", str, strlen(str));
        exit(EXIT_FAILURE);
    }
    return copy;
}

void init_product_array(Product** products_ptr, size_t capacity) {
    *products_ptr = safe_malloc(capacity * sizeof(Product));

    products.data = *products_ptr;
    products.capacity = capacity;
    products.allocated = 0;

    names.data = calloc(capacity, sizeof(char*));
    manufacturers.data = calloc(capacity, sizeof(char*));

    log_memory("Initialized product array", products.data, capacity * sizeof(Product));
}

void free_product_array(Product** products_ptr) {
    if (products.data != NULL) {
        for (size_t i = 0; i < products->allocated; ++i) {
            free(((Product*)products.data)[i].name);
            free(((Product*)products.data)[i].manufacturer);
        }
        free(products.data);
        products.data = NULL;
    }

    if (names.data != NULL) {
        free(names.data);
        names.data = NULL;
    }

    if (manufacturers.data != NULL) {
        free(manufacturers.data);
        manufacturers.data = NULL;
    }

    log_memory("Freed product array", products.data, products.capacity * sizeof(Product));
}

void set_product(Product* product, int id, float price, const char* name, const char* manufacturer) {
    product->id = id;
    product->price = price;
    product->name = safe_strdup(name);
    product->manufacturer = safe_strdup(manufacturer);
}

void resize_product_array(Product** products_ptr, size_t new_capacity) {
    if (new_capacity <= products.allocated) return;

    Product* old_products = *products_ptr;
    init_product_array(products_ptr, new_capacity);

    for (size_t i = 0; i < products->allocated; ++i) {
        set_product(*((Product*)old_products + i), i + 1000, old_products[i].price, old_products[i].name, old_products[i].manufacturer);
    }

    free(old_products);
}

void log_memory_usage() {
    size_t used = products.allocated * sizeof(Product) + names.allocated + manufacturers.allocated;
    size_t total = sysconf(_SC_PAGE_SIZE) * (sysconf(_SC_PHYS_PAGES) - sysconf(_SC_FREE_PAGES));
    printf("Memory usage: %zu / %zu bytes\n", used, total);
}
```

