typedef struct Block {
    size_t size;
    struct Block* next;
} Block;

Block* head = NULL;

void* my_malloc(size_t size) {
    if (size == 0) return NULL;

    Block* new_block = (Block*) malloc(sizeof(Block) + size);
    if (!new_block) return NULL;

    new_block->size = size;
    new_block->next = head;
    head = new_block;

    return (void*) ((char*) new_block + sizeof(Block));
}

void my_free(void* ptr) {
    if (!ptr || !(char*) ptr >= (char*) head) return;

    Block* current = head;
    while (current && (char*) ptr < (char*) current->next) {
        current = current->next;
    }

    if (current && (char*) ptr == (char*) current) {
        Block* to_free = current;
        current = current->next;
        free(to_free);
    }
}
