class MemoryPool {
public:
    MemoryPool(size_t blockSize) : blockSize_(blockSize), freeListHead_(nullptr) {}

    void* allocate() {
        if (freeListHead_ != nullptr) {
            void* result = freeListHead_;
            freeListHead_ = static_cast<char*>(freeListHead_) + blockSize_;
            return result;
        }
        return operator new(blockSize_);
    }

    void deallocate(void* ptr) {
        if (freeListHead_ == nullptr) {
            freeListHead_ = ptr;
        } else {
            static_cast<char*>(freeListHead_)->~char();
            new (static_cast<char*>(freeListHead_)) char();
            std::memcpy(static_cast<char*>(freeListHead_), ptr, blockSize_);
            freeListHead_ = static_cast<char*>(freeListHead_) + blockSize_;
        }
    }

private:
    size_t blockSize_;
    char* freeListHead_;
};

class RecordManager {
public:
    RecordManager(int n, MemoryPool& pool) : pool_(pool), n_(n), keys_(new int[n_]), offsets_(new long[n_]), records_(new record[n_]) {}

    ~RecordManager() {
        delete[] keys_;
        delete[] offsets_;
        delete[] records_;
    }

    void initialize() {
        std::fill(offsets_, offsets_ + n_, 0);
        std::iota(std::begin(keys_), std::end(keys_), 0);
        for (int i = 0; i < n_; ++i) {
            offsets_[keys_[i]] = i;
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100); // Adjust the range as needed

        std::mutex mtx;
        std::vector<std::thread> threads;
        for (int i = 0; i < n_; ++i) {
            threads.emplace_back([&, i]() mutable {
                std::unique_lock<std::mutex> lock(mtx);
                records_[offsets_[i]].value = dis(gen);
                lock.unlock();
            });
        }
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void logError(const std::string& message) const {
        auto timestamp = std::time(nullptr);
        std::ostringstream oss;
        oss << "[" << ctime(&timestamp) << "] Error: " << message << "\n";
        std::cout << oss.str();
    }

    void* getMemoryPool() const { return &pool_; }

private:
    MemoryPool& pool_;
    int n_;
    int* keys_;
    long* offsets_;
    record* records_;
};

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: ./program <number_of_records>\n";
        return EXIT_FAILURE;
    }

    int n = std::stoi(argv[1]);
    MemoryPool pool(sizeof(record));
    RecordManager manager(n, pool);
    manager.initialize();

    // Use the data structures here...

    manager.~RecordManager();
    return EXIT_SUCCESS;
}
