typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef int (*generate_crc)(const void*, size_t);

void* array_resize(void** arr, size_t* capacity, size_t new_size) {
    void* new_arr = realloc(*arr, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_arr) return NULL;
    *capacity = new_size;
    return new_arr;
}

void log_algorithm_usage(const char* algorithm) {
    // Implement logging here
}

int init_crc_array(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* capacity, size_t N, const char* env_var) {
    *arr = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*arr) return -1;
    *capacity = N;

    void* handle = dlopen(getenv(env_var), RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        free(*arr);
        return -1;
    }

    generate_crc gen_crc = dlsym(handle, "generate_crc");
    if (!gen_crc) {
        fprintf(stderr, "Failed to find symbol 'generate_crc'\n");
        dlclose(handle);
        free(*arr);
        return -1;
    }

    for (size_t i = 0; i < N; ++i) {
        (*arr)[i].rnti = i + 1;
        (*arr)[i].crc_indication.crcflag = gen_crc((const void*)&(*arr)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        log_algorithm_usage(dlerror());
    }

    return 0;
}

void deinit_crc_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t capacity) {
    if (arr) {
        dlclose(dlopen(getenv("CRYPTO_LIBRARY"), RTLD_NOW | RTLD_LOCAL));
        free(arr);
    }
}
