[" Here's a simplified implementation of the task, focusing on key aspects while keeping the code concise and readable. This solution uses pthreads for multi-threading, malloc/free for dynamic memory allocation, and a custom cache system for improving access speed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

struct data {
    long *offsets;
    int *keys;
    record *records;
    size_t n;
    int min_value, max_value;
    size_t cache_size;
    record *cache;
    pthread_mutex_t mutex;
};

void init_data(struct data *data, size_t n, int min_value, int max_value) {
    data->n = n;
    data->min_value = min_value;
    data->max_value = max_value;

    data->offsets = malloc((n + 1) * sizeof(long));
    data->keys = malloc(n * sizeof(int));
    data->records = NULL;
    data->cache = NULL;
    data->cache_size = 0;

    pthread_mutex_init(&data->mutex, NULL);
}

void free_data(struct data *data) {
    if (data->records) {
        free(data->records);
    }
    if (data->offsets) {
        free(data->offsets);
    }
    if (data->keys) {
        free(data->keys);
    }
    pthread_mutex_destroy(&data->mutex);
}

record *get_record(struct data *data, int key) {
    record *record;

    if (!data->cache || data->cache_size == 0) {
        pthread_mutex_lock(&data->mutex);
        if (!data->records) {
            pthread_mutex_unlock(&data->mutex);
            return NULL;
        }

        record = malloc(data->n * sizeof(record));
        for (size_t i = 0; i < data->n; ++i) {
            record[i].value = rand() % (max_value - min_value + 1) + min_value;
        }
        data->records = record;
        pthread_mutex_unlock(&data->mutex);
    } else {
        record = data->cache;
    }

    for (size_t i = 0; i < data->n; ++i) {
        if (data->keys[i] == key) {
            return &record[i];
        }
    }

    // Cache miss, find an empty slot in the cache and store the record there.
    for (size_t i = 0; i < data->cache_size && data->cache[i].value != 0; ++i) {}
    if (i == data->cache_size) {
        // Cache is full, evict the least recently used record.
        size_t least_recently_used = 0;
        for (size_t i = 1; i < data->cache_size; ++i) {
            if (data->cache[least_recently_used].value > data->cache[i].value) {
                least_recently_used = i;
            }
        }
        record = &data->cache[least_recently_used];
        data->keys[record - data->cache] = key;
        data->offsets[record - data->cache] = -1;
    }

    data->keys[i] = key;
    data->offsets[i] = (long) (record - data->records);
    record->value = rand() % (max_value - min_value + 1) + min_value;
    return record;
}

void *init_thread(void *arg) {
    struct data *data = arg;
    for (size_t i = 0; i < data->n; ++i) {
        get_record(data, i);
    }
    pthread_exit(NULL);
}

int main() {
    srand(time(NULL));

    struct data data;
    init_data(&data, 10000, 0, 100000);

    pthread_t threads[4];
    for (size_t i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, init_thread, &data);
    }
    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Perform validation checks and error handling here.

    free_data(&data);
    return 0;
}
```

