        if (table->table[i]) {
            decompress_record(table->table[i], NULL);
            free(table->table[i]);
        }
    }
    free(table->table);
}

record* get_record_by_index(hash_table* table, size_t index) {
    pthread_mutex_lock(&table->lock);
    record* record = table->table[index];
    pthread_mutex_unlock(&table->lock);
    return record;
}

record* get_record_by_key(hash_table* table, int key) {
    size_t index = hash(key, table->size);
    pthread_mutex_lock(&table->lock);
    while (table->table[index] && table->table[index]->key != key) {
        ++index;
        if (index >= table->size) index = 0;
    }
    record* record = table->table[index];
    pthread_mutex_unlock(&table->lock);
    return record;
}

void insert_record(hash_table* table, record* record) {
    size_t index = hash(record->key, table->size);
    pthread_mutex_lock(&table->lock);
    while (table->table[index]) {
        ++index;
        if (index >= table->size) index = 0;
    }
    table->table[index] = record;
    pthread_mutex_unlock(&table->lock);
}
