constexpr double MIN_VALUE = 1e-308;
constexpr double MAX_VALUE = 1e+308;
constexpr int MAX_NUMBERS = 5000;
constexpr int LOG_COMPRESSION_THRESHOLD = 1024;

std::deque<double> numbers;
std::vector<std::string> invalidInputs;
boost::atomic<bool> running(true);
boost::mutex mtx;

void inputProcessor() {
    std::string line;
    while (running) {
        std::getline(std::cin, line);
        if (!line.empty()) {
            std::istringstream iss(line);
            double num;
            if (!(iss >> num)) {
                boost::lock_guard<boost::mutex> lock(mtx);
                invalidInputs.push_back(line);
                compressLog();
            } else if (!boost::math::isfinite(num) || num < MIN_VALUE || num > MAX_VALUE) {
                std::cout << "Invalid input: Number out of range. Please re-enter.\n";
                boost::lock_guard<boost::mutex> lock(mtx);
                invalidInputs.push_back(line);
                compressLog();
            } else {
                if (numbers.size() >= MAX_NUMBERS) {
                    std::cout << "Sum exceeded threshold. Terminating early.\n";
                    running = false;
                } else {
                    numbers.push_back(num);
                }
            }
        }
    }
}

void compressLog() {
    if (invalidInputs.size() > LOG_COMPRESSION_THRESHOLD) {
        std::sort(invalidInputs.begin(), invalidInputs.end());
        invalidInputs.erase(std::unique(invalidInputs.begin(), invalidInputs.end()), invalidInputs.end());
        boost::filesystem::path logPath("invalid_inputs.log");
        if (boost::filesystem::exists(logPath)) {
            boost::filesystem::remove(logPath);
        }
        std::ofstream outFile(logPath);
        for (const auto& input : invalidInputs) {
            outFile << input << '\n';
        }
    }
}

double mean() {
    double sum = 0;
    for (auto num : numbers) {
        sum += num;
    }
    return sum / numbers.size();
}

double standardDeviation() {
    double meanValue = mean();
    double sumOfSquares = 0;
    for (auto num : numbers) {
        sumOfSquares += pow(num - meanValue, 2);
    }
    return sqrt(sumOfSquares / numbers.size());
}

void printResults() {
    if (numbers.empty()) {
        std::cout << "No valid numbers entered.\n";
    } else {
        std::cout << "Mean: " << mean() << "\n";
        std::cout << "Standard Deviation: " << standardDeviation() << "\n";
    }
}

int main(int argc, char* argv[]) {
    // Handle command-line arguments for threshold configuration
    double sumThreshold;
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <sum_threshold>\n";
        return 1;
    } else {
        sumThreshold = std::stod(argv[1]);
    }

    boost::thread inputThread(inputProcessor);
    boost::thread resultThread([&]() {
        while (running) {
            if (numbers.size() >= MAX_NUMBERS || numbers.size() > 0 && sum(numbers) > sumThreshold) {
                running = false;
            }
        }
    });

    inputThread.join();
    resultThread.join();

    printResults();

    return 0;
}
