unsigned long hash(const char *key, unsigned long size) {
    unsigned long hash = 5381;
    for (int i = 0; key[i]; ++i)
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    return hash % size;
}

void insert(HashTable *ht, const char *key, int value) {
    pthread_mutex_lock(&ht->lock);
    unsigned long index = hash(key, ht->size);
    Record *record = malloc(sizeof(Record));
    record->value = value;
    record->next = ht->table[index];
    ht->table[index] = record;
    pthread_mutex_unlock(&ht->lock);
}

int find(HashTable *ht, const char *key) {
    pthread_mutex_lock(&ht->lock);
    unsigned long index = hash(key, ht->size);
    Record *record = ht->table[index];
    while (record) {
        if (!strcmp(record->value, key)) {
            int value = record->value;
            Record *temp = record;
            record = record->next;
            free(temp);
            pthread_mutex_unlock(&ht->lock);
            return value;
        }
        record = record->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return -1;
}

