[' Here's a C++ implementation using a linked list for efficient memory management and thread-safe access with `std::mutex`. The provided function takes as input the initial size, maximum capacity, and deallocation callback, and returns a pointer to the newly created structure.

```cpp
#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <mutex>
#include <memory>

struct Record {
    int value;
    long* offset;
    Record* next;
};

class RecordPool {
public:
    RecordPool(size_t initialSize, size_t maxCapacity, std::function<void(void*)> deallocate)
        : m_initialSize(initialSize), m_maxCapacity(maxCapacity), m_deallocate(std::move(deallocate)), m_head(nullptr), m_tail(nullptr), m_mutex() {}

    Record* createRecord(long offset) {
        if (m_head == nullptr) {
            m_head = new Record;
            m_head->offset = new long(offset);
            m_head->next = nullptr;
            m_tail = m_head;
        } else {
            Record* newRecord = new Record;
            newRecord->offset = new long(offset);
            newRecord->next = m_head;
            m_head = newRecord;
        }

        newRecord->value = rand() % 100; // Set value to a random number within [0, 99]
        return newRecord;
    }

    void resize(size_t newSize) {
        if (newSize > m_maxCapacity) {
            std::cerr << "Error: New size exceeds maximum capacity." << std::endl;
            return;
        }

        Record* current = m_head;
        for (size_t i = m_initialSize; i < newSize - 1; ++i) {
            current = current->next;
        }
        Record* newTail = new Record;
        newTail->offset = new long(0); // Set offset to 0 for the new records
        newTail->next = nullptr;
        current->next = newTail;
        m_tail = newTail;
        m_initialSize = newSize;
    }

    void destroy() {
        Record* current = m_head;
        while (m_head != nullptr) {
            Record* next = current->next;
            m_deallocate(current->offset);
            delete current->offset;
            delete current;
            current = next;
        }
        m_head = nullptr;
        m_tail = nullptr;
    }

    std::mutex& getMutex() { return m_mutex; }

private:
    size_t m_initialSize;
    size_t m_maxCapacity;
    std::function<void(void*)> m_deallocate;
    Record* m_head;
    Record* m_tail;
    std::mutex m_mutex;
};
```

This implementation uses a linked list for efficient memory management and dynamic resizing. The `RecordPool` class manages the creation, destruction, and resizing of records while ensuring thread safety with a mutex. The provided function creates a new record with a given offset and sets its value to a random number within a specified range.

To handle unexpected load spikes gracefully, consider implementing a strategy for automatically increasing the maximum capacity when memory exhaustion is imminent or using a buffer pool for more efficient memory management under high concurrency.']

