    if (!collection) return NULL;

    collection->capacity = capacity;
    collection->size = 0;
    collection->tasks = calloc(capacity, sizeof(Task));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }

    collection->free_func = free_func;
    collection->tree = rbtree_create(compare);

    pthread_mutex_init(&collection->lock, NULL);
    pthread_create(&collection->cleanup_thread, NULL, cleanup_thread, collection);

    return collection;
}

