}

void cleanup_thread(void* arg) {
    struct task_collection* collection = arg;
    time_t current_time = time(NULL);

    while (1) {
        pthread_mutex_lock(&collection->lock);

        for (size_t i = 0; i < collection->size; ++i) {
            if (current_time - collection->tasks[i].timestamp > MAX_AGE) {
                rbtree_remove(collection->tree, &collection->tasks[i]);
                --collection->size;
                collection->free_func(&collection->tasks[i]);
            }
        }

