void *my_malloc(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void *ptr, size_t size) {
    munmap(ptr, size);
}

struct MemoryPool init_memory_pool(size_t size) {
    struct MemoryPool pool = {my_malloc(size), size, 0};
    return pool;
}

void deallocate_memory_pool(struct MemoryPool *pool) {
