    struct Cache cache = {0};
    cache.max_size = max_size;
    sem_init(&cache.lock, 0, 1);
    return cache;
}

void cache_put(struct Cache *cache, Record record) {
    sem_wait(&cache->lock);
    if (cache->current_size >= cache->max_size) {
        size_t least_recently_used = 0;
        for (size_t i = 1; i < cache->current_size; ++i) {
            if (lru_index[i] < lru_index[least_recently_used])
                least_recently_used = i;
        }
        memmove(cache->cache + lru_index[least_recently_used], cache->cache, sizeof(Record) * (cache->current_size - 1));
        lru_index[least_recently_used] = cache->current_size;
    }
    memcpy(cache->cache + cache->current_size++, &record, sizeof(Record));
    sem_post(&cache->lock);
}

Record *cache_get(struct Cache *cache, size_t index) {
    Record *record = NULL;
    sem_wait(&cache->lock);
    if (index < cache->current_size && cache->lru_index[index] == index) {
        record = &cache->cache[index];
        cache->lru_index[index] = cache->current_size;
    }
    sem_post(&cache->lock);
    return record;
}

