```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class RandomValueGenerator
{
    private readonly Dictionary<string, Random> _generators = new Dictionary<string, Random>();

    public void AddGenerator(string name, Func<Random> generatorFactory, int minValue = int.MinValue, int maxValue = int.MaxValue)
    {
        if (_generators.ContainsKey(name)) throw new ArgumentException($"Generator with name '{name}' already exists.");

        _generators[name] = generatorFactory().With(minValue).With(maxValue);
    }

    public float NextFloat(string name) => _generators[name].NextSingle();

    public int NextInt(string name) => (int)_generators[name].NextDouble() * (_generators[name].MaxValue - _generators[name].MinValue) + _generators[name].MinValue;

    public void ResetGenerator(string name, int calls = int.MaxValue)
    {
        if (!_generators.ContainsKey(name)) throw new ArgumentException($"Generator with name '{name}' does not exist.");
        _generators[name] = _generators[name].With(calls);
    }
}

public class RandomGeneratorFactory
{
    public Func<Random> Standard => () => new Random();
}
```

