void initializeRecords(int num_records, int min_value, int max_value) {
    Record* records = (Record*) malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = i;
        records[i].key = i;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void* randomValueGenerator(void* arg) {
    srand((unsigned int)pthread_self());
    return NULL;
}

void runTests(const char* module, void (*testFunctions[])(), int budget_ms) {
    clock_t start = clock();
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, randomValueGenerator, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_tests; ++i) {
        testFunctions[i]();
        pthread_barrier_t barrier;
        pthread_barrier_init(&barrier, NULL, num_threads);
        for (int j = 0; j < num_threads; ++j) {
            pthread_join(threads[j], NULL);
        }
        pthread_barrier_destroy(&barrier);
    }

    clock_t end = clock();
    double elapsed_secs = (end - start) / CLOCKS_PER_SEC;

    if (elapsed_secs > (double)budget_ms / 1000.0) {
