#include <boost/serialization/vector.hpp>
#include <boost/serialization/string.hpp>
#include <boost/serialization/utility.hpp>
#include <boost/lockfree/queue.hpp>
#include <memory>

struct item {
    std::string data;
    int key;

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & data;
        ar & key;
    }
};

struct collection {
    std::vector<item> items;
    boost::lockfree::queue<std::unique_ptr<item>> operationsQueue;

    void insert(const item& item) {
        auto newItem = std::make_unique<item>(item);
        items.push_back(*newItem);
        operationsQueue.push(std::move(newItem));
    }

    void deleteByKey(int key) {
        for (auto it = items.begin(); it != items.end(); ++it) {
            if (it->key == key) {
                auto newItem = std::move(*it);
                items.erase(it);
                operationsQueue.push(std::move(newItem));
                break;
            }
        }
    }

    void modifyByKey(int key, const item& newItem) {
        for (auto it = items.begin(); it != items.end(); ++it) {
            if (it->key == key) {
                auto oldItem = std::move(*it);
                *it = newItem;
                operationsQueue.push(std::move(oldItem));
                break;
            }
        }
    }

    void persist() {
        // Implement serialization and write to file or network stream
    }

    void recover() {
        // Implement deserialization and read from file or network stream
    }
