    return key % table_size;
}
```

3. **Memory allocation and deallocation functions:**

```c
LogEntry* create_log_entry(int key, long timestamp, char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->key = key;
    entry->timestamp = timestamp;
    entry->message = strdup(message);
    entry->next = NULL;

    return entry;
}

void free_log_entry(LogEntry* entry) {
    if (entry) {
        free(entry->message);
        free(entry);
    }
}
```

4. **Hash table initialization and expansion:**

```c
HashTable* create_hash_table(unsigned int initial_size, float load_factor) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    if (!hash_table) return NULL;

    hash_table->size = initial_size;
    hash_table->load_factor = load_factor;
    hash_table->table = calloc(initial_size, sizeof(LogEntry*));

    return hash_table;
}

void expand_hash_table(HashTable* hash_table) {
    unsigned int new_size = hash_table->size * 2;
    LogEntry** new_table = calloc(new_size, sizeof(LogEntry*));

    for (unsigned int i = 0; i < hash_table->size; ++i) {
        LogEntry* current = hash_table->table[i];
        while (current != NULL) {
            int key = current->key;
            long index = hash(key, new_size);
            current->next = new_table[index];
            new_table[index] = current;
            current = current->next;
        }
    }

    free(hash_table->table);
    hash_table->table = new_table;
    hash_table->size = new_size;
}
```

5. **Insert, delete, and lookup functions:**

```c
LogEntry* find(HashTable* hash_table, int key) {
    unsigned int index = hash(key, hash_table->size);
    LogEntry* current = hash_table->table[index];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

void insert(HashTable* hash_table, int key, long timestamp, char* message) {
    LogEntry* entry = create_log_entry(key, timestamp, message);
    if (!entry) return;

    unsigned int index = hash(key, hash_table->size);
    entry->next = hash_table->table[index];
    hash_table->table[index] = entry;

    if (hash_table->load_factor > 0.75) {
        expand_hash_table(hash_table);
    }
}

void delete(HashTable* hash_table, int key) {
    LogEntry** previous = &hash_table->table[hash(key, hash_table->size)];
    LogEntry* current = *previous;

    if (current == NULL) return;

    while (current != NULL && current->key != key) {
        previous = &current->next;
        current = current->next;
    }

    if (current == NULL) return;

    free_log_entry(current);
    *previous = current->next;
}
