        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distInt(m_minIntValue, m_maxIntValue);
        std::uniform_real_distribution<> distFloat(m_minFloatValue, m_maxFloatValue);

        std::generate_n(m_offsets.data(), maxOffset, [&]() { return distInt(gen); });
        std::generate_n(m_keys.data(), maxKeys, [&]() { return distInt(gen); });

        for (auto& record : m_records) {
            record.value = distInt(gen);
        }
    }

    void addRecords(std::uint32_t numRecords) {
        if (numRecords > m_records.capacity() - m_records.size()) {
            throw std::runtime_error("Cannot add more records than available capacity");
        }

        std::generate_n(std::back_inserter(m_records), numRecords, [&]() {
            auto value = m_minIntValue + static_cast<int>(std::uniform_int_distribution<>(m_minIntValue, m_maxIntValue)(m_gen));
            m_records.back().value = value;
            return m_records.back();
        });
    }

    void toString() const {
        std::cout << "Min Int: " << m_minIntValue << ", Max Int: " << m_maxIntValue << "\n";
        std::cout << "Min Float: " << m_minFloatValue << ", Max Float: " << m_maxFloatValue << "\n";
        std::cout << "Offsets:\n";
        for (const auto& offset : m_offsets) {
            std::cout << offset << ", ";
        }
        std::cout << "\nKeys:\n";
        for (const auto& key : m_keys) {
            std::cout << key << ", ";
        }
        std::cout << "\nRecords:\n";
        for (const auto& record : m_records) {
            std::cout << record.value << ", ";
        }
    }

private:
    struct Record {
        int value;
    };

    std::uint64_t m_minIntValue, m_maxIntValue, m_maxOffset;
    float m_minFloatValue, m_maxFloatValue;
    std::vector<std::uint64_t> m_offsets;
    std::vector<std::uint32_t> m_keys;
    std::vector<Record> m_records;
    std::mt19937 m_gen; // Mersenne Twister pseudo-random number generator
};
```

