    char *favorite_activities;
    char *social_media_handles;
    pthread_mutex_t lock;
    unsigned int id;
} UserProfile;

gsl_hash_table *user_profiles;
pthread_mutex_t user_profiles_lock;

void init() {
    user_profiles = gsl_hash_table_alloc(gsl_hash_table_string, sizeof(UserProfile*));
    pthread_mutex_init(&user_profiles_lock, NULL);
}

unsigned int generate_id() {
    return time(NULL);
}

void create_profile(const char *username, const char *name, const char *email, const char *dob,
                     const char *favorite_activities, const char *social_media_handles) {
    UserProfile *new_user = malloc(sizeof(UserProfile));
    strcpy(new_user->name, name);
    strcpy(new_user->email, email);
    strcpy(new_user->dob, dob);
    new_user->favorite_activities = strdup(favorite_activities);
    new_user->social_media_handles = strdup(social_media_handles);
    pthread_mutex_init(&new_user->lock, NULL);
    new_user->id = generate_id();

    pthread_mutex_lock(&user_profiles_lock);
    gsl_hash_table_insert(user_profiles, username, new_user);
    pthread_mutex_unlock(&user_profiles_lock);
}

UserProfile *get_profile(const char *username) {
    UserProfile *user;
    pthread_mutex_lock(&user_profiles_lock);
    user = gsl_hash_table_get(user_profiles, username);
    pthread_mutex_unlock(&user_profiles_lock);
    return user;
}

void update_profile(UserProfile *user, const char *name, const char *email, const char *dob,
                     const char *favorite_activities, const char *social_media_handles) {
    pthread_mutex_lock(&user->lock);
    strcpy(user->name, name);
    strcpy(user->email, email);
    strcpy(user->dob, dob);
    free(user->favorite_activities);
    user->favorite_activities = strdup(favorite_activities);
    free(user->social_media_handles);
    user->social_media_handles = strdup(social_media_handles);
    pthread_mutex_unlock(&user->lock);
}

void delete_profile(const char *username) {
    UserProfile *user;
    pthread_mutex_lock(&user_profiles_lock);
    user = gsl_hash_table_remove(user_profiles, username);
    if (user) {
        free(user->name);
        free(user->email);
        free(user->dob);
        free(user->favorite_activities);
        free(user->social_media_handles);
        pthread_mutex_destroy(&user->lock);
        free(user);
    }
    pthread_mutex_unlock(&user_profiles_lock);
}
