        while (true) {
            keys[i] = rand() % keyCount;
            bool unique = true;
            for (unsigned long j = 0; j < i; ++j) {
                if (keys[i] == keys[j]) {
                    unique = false;
                    break;
                }
            }
            if (unique) {
                break;
            }
        }
    }

    record* records = (record*)malloc(recordCount * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return "Memory allocation for records failed.";
    }

    unsigned long minSize = (unsigned long)min((unsigned long)offsetCount, keyCount);
    recordCount = minSize > 0 ? minSize : recordCount;

    for (unsigned long i = 0; i < recordCount; ++i) {
        records[i].offset = i < minSize ? i : offsets[i - minSize];
        records[i].key = keys[i];
        records[i].status = (records[i].offset & 1) ? 'B' : 'A';
    }

    free(offsets);
    free(keys);

    return records;
}
