// Custom memory allocator (not optimized)
void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom memory deallocator (not optimized)
void custom_free(void* ptr) {
    int rc = munmap(ptr, msize);
    if (rc == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

// Custom memory pool (not optimized)
typedef struct MemPool_t {
    void* start;
    size_t size;
    size_t allocated;
    size_t free;
    pthread_mutex_t lock;
} MemPool_t;

MemPool_t mempool;

void init_mempool(size_t size) {
    mempool.start = custom_malloc(size);
    mempool.size = size;
    mempool.allocated = 0;
    mempool.free = size;
    pthread_mutex_init(&mempool.lock, NULL);
}

void* mempool_alloc(size_t size) {
    if (size > mempool.free) {
        fprintf(stderr, "Not enough memory in the pool\n");
        return NULL;
    }

    pthread_mutex_lock(&mempool.lock);
    void* ptr = mempool.start + mempool.allocated;
    mempool.allocated += size;
    mempool.free -= size;
    pthread_mutex_unlock(&mempool.lock);

    return ptr;
}

void mempool_free(void* ptr) {
    if (!ptr || ptr < mempool.start || (char*)ptr >= (char*)mempool.start + mempool.size) {
        fprintf(stderr, "Invalid memory pointer\n");
        return;
    }

    pthread_mutex_lock(&mempool.lock);
    mempool.free += sizeof(void*);
    mempool.allocated -= sizeof(void*);
    pthread_mutex_unlock(&mempool.lock);
}

// Record structure and functions (not optimized)
typedef struct Record_t {
    int key;
    long offset;
    double value;
} Record_t;

Record_t* record_new() {
    return mempool_alloc(sizeof(Record_t));
}

void record_init(Record_t* record) {
    if (record == NULL) {
        return;
    }

    record->key = rand() % 100;
    record->offset = rand() % 1000000000L;
    record->value = (double)(rand() % 1000000) / 1000000.0;
}

// B-tree index structure and functions (not optimized)
// Implementation of B-tree, custom sorting algorithm, and hybrid indexing strategy is left for further development.

// External logging library integration (not optimized)
#include <log4c.h>
void log_memory_event(const char* event, void* ptr) {
    if (!ptr) {
        return;
    }

    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%p", ptr);
    LOG4C_INFO(logger, "Memory %s: %s", event, buffer);
}
```

