constexpr size_t MAX_MEMORY_LIMIT = 100 * 1024 * 1024; // 100 MB

struct Record {
    int value;
};

void allocateRecords(size_t n) {
    MemoryPool<Record> pool;
    std::vector<Record> records;

    size_t totalMemory = 0;
    while (totalMemory < MAX_MEMORY_LIMIT && records.size() < n) {
