```

2. Implement a priority queue using a binary heap:

```cpp
#include <stdlib.h>
#include <limits.h>

struct PriorityQueue {
    struct Job* jobs;
    int size;
    int capacity;
};

void swap(struct Job* a, struct Job* b) {
    struct Job temp = *a;
    *a = *b;
    *b = temp;
}

int parent(int i) { return (i - 1) / 2; }
int leftChild(int i) { return 2 * i + 1; }
int rightChild(int i) { return 2 * i + 2; }

void siftUp(struct PriorityQueue* pq, int index) {
    while (index > 0 && pq->jobs[parent(index)] < pq->jobs[index]) {
        swap(&pq->jobs[parent(index)], &pq->jobs[index]);
        index = parent(index);
    }
}

void siftDown(struct PriorityQueue* pq, int index) {
    int left = leftChild(index);
    int right = rightChild(index);
    int largest = index;

    if (left < pq->size && pq->jobs[left] > pq->jobs[largest])
        largest = left;

    if (right < pq->size && pq->jobs[right] > pq->jobs[largest])
        largest = right;

    if (largest != index) {
        swap(&pq->jobs[index], &pq->jobs[largest]);
        siftDown(pq, largest);
    }
}
```

