}

void deleteJobByName(struct JobCollection* jc, const char* name) {
    int index = -1;
    for (int i = 0; i < jc->priorityQueue->size; ++i) {
        if (strcmp(jc->priorityQueue->jobs[i].name, name) == 0) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        // Swap the last job with the one to be deleted and remove it from the priority queue
        jc->priorityQueue->jobs[index] = jc->priorityQueue->jobs[--(jc->priorityQueue->size)];
        siftDown(jc->priorityQueue, index);
    }
}

void updateJobByName(struct JobCollection* jc, const char* name, int priorityLevel, float costEstimate) {
    int index = -1;
