        jc->priorityQueue->jobs[index].priorityLevel = priorityLevel;
        jc->priorityQueue->jobs[index].costEstimate = costEstimate;
        siftUp(jc->priorityQueue, index);
        siftDown(jc->priorityQueue, index);
    }
}
