#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

struct MemoryManager {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
};

void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    return ptr;
}

void validate(struct MemoryManager *mm) {
    if (!mm->offsets || !mm->keys || !mm->records) {
        fprintf(stderr, "Error: Failed to allocate memory for one or more arrays\n");
    }
}

void init_arrays(struct MemoryManager *mm) {
    mm->offsets = (long *)custom_malloc((mm->size + 1) * sizeof(long));
    mm->keys = (int *)custom_malloc(mm->size * sizeof(int));
    mm->records = (Record *)custom_malloc(mm->size * sizeof(Record));

    if (!validate(mm)) return;

    for (size_t i = 0; i < mm->size; ++i) {
        mm->offsets[i] = i;
        mm->keys[i] = i * 2;
        mm->records[i].value = mm->keys[i] + mm->offsets[i];
    }
}

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
}

void export_to_csv(const char *filename, struct MemoryManager mm) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        log_error("Failed to open output file");
        return;
    }

    fprintf(file, "Offset,Key,Record\n");
    for (size_t i = 0; i < mm.size; ++i) {
        fprintf(file, "%ld,%d,%d\n", mm.offsets[i], mm.keys[i], mm.records[i].value);
    }
    fclose(file);
}

void *memory_manager(void *arg) {
    struct MemoryManager *mm = arg;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    init_arrays(mm);

    // Periodically check memory usage and free unused records
    while (1) {
        sleep(60); // Adjust the interval as needed
        pthread_mutex_lock(&lock);
        // Implement memory cleanup logic here
        pthread_mutex_unlock(&lock);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s size\n", argv[0]);
        return 1;
    }

    size_t size = strtol(argv[1], NULL, 10);
    if (size <= 0) {
        log_error("Invalid size provided");
        return 1;
    }

    struct MemoryManager mm = { .size = size };
    pthread_t thread;

    pthread_create(&thread, NULL, memory_manager, &mm);

    // Implement command-line options for logging and CSV export here

    pthread_join(thread, NULL);
    return 0;
}
```

