        records.push({ offset: Number(offset), key: Number(key) });
    });

    rl.on('close', () => {
        return records;
    });
}

function processLogAndExecuteCommand(logFile, command, resourceFile) {
    const errorPatterns = ['ERROR\\w+', 'FATAL\\w+', 'CRITICAL\\w+'];
    const errorMessages = {};

    const stream = fs.createReadStream(logFile);
    const rl = readline.createInterface({ input: stream });

    let lineCount = 0;
    rl.on('line', line => {
        if (line.match(new RegExp(errorPatterns[0] | errorPatterns[1] | errorPatterns[2], 'g'))) {
            const key = Number(line.split(':')[-1].trim());
            if (!errorMessages[key]) errorMessages[key] = 0;
            errorMessages[key]++;
        }
        lineCount++;
    });

    rl.on('close', () => {
        const process = child_process.spawn(command, {
            stdio: 'inherit'
        });

        process.on('exit', code => {
            console.log(`Command executed with return code ${code}`);
        });
    });
}
```

Both functions assume the presence of a resource file containing records in the format `offset\tkey`, and they process log files line by line, filtering out non-error lines based on predefined error patterns. They also execute shell commands using child processes and handle errors appropriately. The JavaScript function uses Node.js to read the log file line by line and load the resource file."]

