JavaScript (Node.js) Component:

```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const zlib = require('zlib');

function isValidPath(filePath) {
    const absFilePath = path.resolve(filePath);
    return fs.existsSync(absFilePath) && fs.statSync(absFilePath).isFile();
}

async function countLines(filePath) {
    if (!isValidPath(filePath)) throw new Error(`Invalid file path: ${filePath}`);

    const rl = readline.createInterface({
        input: fs.createReadStream(filePath),
        console: false,
    });

    let totalLines = 0;
    for await (const line of rl) {
        totalLines++;
    }

    return totalLines;
}

function runLengthEncoding(data) {
    let currentChar = data[0];
    let count = 1;
    const encodedData = [];

    for (let i = 1; i < data.length; ++i) {
        if (data[i] === currentChar) {
            count++;
        } else {
            encodedData.push(count);
            encodedData.push(currentChar);
            currentChar = data[i];
            count = 1;
        }
    }

    // Add the last character and its count
    encodedData.push(count);
    encodedData.push(currentChar);

    return encodedData;
}

function skipComments(data) {
    let index = 0;
    const result = [];

    while (index < data.length) {
        if (data[index] === '/' && (data[index + 1] === '/' || data[index + 1] === '*')) {
            // Single-line or multi-line comment
            let commentEndIndex = index;
            if (data[index + 1] === '*') {
                while (++commentEndIndex < data.length && data[commentEndIndex] !== '/') {}
            } else {
                ++commentEndIndex;
            }

            index = commentEndIndex;
        } else {
            result.push(data[index]);
            ++index;
        }
    }

    return result;
}

function writeFile(filePath, data) {
    fs.writeFileSync(filePath, data);
}

async function processFiles(directoryPath, outputDirectoryPath, action, outputFilePath) {
    const files = await fs.promises.readdir(directoryPath);

    for (const file of files) {
        const absFilePath = path.resolve(directoryPath, file);
        const absOutputFilePath = path.resolve(outputDirectoryPath, outputFilePath + file);

        if (isValidPath(absFilePath)) {
            const data = await fs.promises.readFile(absFilePath, 'utf8');

            switch (action) {
                case 'count':
                    console.log(`Counting lines for ${file}: ${await countLines(absFilePath)}`);
                    break;
                case 'encode':
                    const encodedData = runLengthEncoding(skipComments(data));
                    writeFile(absOutputFilePath, encodedData.join(''));
                    console.log(`Run-length encoding for ${file}: Saved to ${absOutputFilePath}`);
                    break;
                default:
                    throw new Error(`Invalid action specified: ${action}`);
            }
        }
    }
}
```

