[' I will provide you with two functions: `entry_t` structure definition, `entry_array_init` for initializing the array of `entry_t` structures, and `populate_entries` for populating each entry's string field with a unique file path from a specified directory.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    char *path;
} entry_t;

entry_t* entry_array = NULL;
size_t entries_count = 0;
size_t entries_capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void entry_array_init(size_t capacity) {
    if (entry_array != NULL) {
        free(entry_array);
    }

    entry_array = malloc(capacity * sizeof(entry_t));
    entries_count = 0;
    entries_capacity = capacity;
}

void* populate_entries(void* arg) {
    DIR* dir = (DIR*)arg;
    struct dirent* entry;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        size_t path_len = strlen(arg) + strlen(entry->d_name) + 2; // "/" and '\0'
        char* path = malloc(path_len);
        snprintf(path, path_len, "%s/%s", arg, entry->d_name);

        pthread_mutex_lock(&mutex);
        if (entries_count >= entries_capacity) {
            entry_array_init(entries_capacity * 2);
        }
        entry_t* entry_ptr = &entry_array[entries_count];
        entry_ptr->offset = entries_count;
        entry_ptr->key = rand(); // Replace with a more suitable key generation strategy if needed
        entry_ptr->path = path;
        entries_count++;
        pthread_mutex_unlock(&mutex);
    }

    free(arg);
    return NULL;
}
```

To populate the array of `entry_t` structures with file paths from a specified directory, you can use the following code:

```c
void populate_entries_from_dir(const char* dir_path, size_t num_threads) {
    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        perror("opendir");
        return;
    }

    pthread_t threads[num_threads];
    char path[strlen(dir_path) + 16]; // "/" and "\" for thread arguments

    for (size_t i = 0; i < num_threads; ++i) {
        snprintf(path, sizeof(path), "%s/", dir_path);
        pthread_create(&threads[i], NULL, populate_entries, strdup(path));
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    closedir(dir);
}
```']

