    while (1) {
        size_t connection_size = sizeof(connection_t);
        connection_t *conn = memory_pool_alloc();
        new_socket = accept(server_fd, (struct sockaddr *)conn->client_addr, &connection_size);

        if (new_socket < 0) {
            perror("accept failed");
            continue;
        }

        pthread_create(&conn->thread_id, NULL, handle_connection, conn);

        if (num_connections >= MAX_CONCURRENT_CONNECTIONS) {
            printf("Maximum concurrent connections reached\n");
            break;
        }
        num_connections++;
    }

    return EXIT_SUCCESS;
}
