    return ds;
}

void dealloc_data_struct(DataStruct* ds) {
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
}

Record* generate_record(size_t index, DataStruct* ds) {
    Record* record = &ds->records[index];
    record->key = rand() % 100;
    record->offset = rand() % LONG_MAX;
    record->value = (double)(rand() % 10000) / 100.0;
    return record;
}

Record* get_record(size_t index, DataStruct* ds) {
    pthread_mutex_lock(&ds->lock);
    Record* record = &ds->records[index];
    pthread_mutex_unlock(&ds->lock);
    return record;
}

Record* find_record(int key, DataStruct* ds) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i].key == key) {
            Record* record = &ds->records[i];
            pthread_mutex_unlock(&ds->lock);
            return record;
        }
    }
