[' I'm providing a simplified C++ solution that addresses some of the requirements you've mentioned. This code is not production-ready and should be further optimized, tested, and integrated with an actual logging library or service.

```cpp
#include <iostream>
#include <string>
#include <mutex>
#include <ctime>
#include <sys/stat.h>
#include <unistd.h>
#include <cstdio>
#include <cstdarg>
#include <thread>
#include <vector>

class Logger {
public:
    enum Severity { DEBUG, INFO, WARNING, ERROR };
    static constexpr int MB = 1024 * 1024;
    static constexpr int DEFAULT_MAX_FILE_SIZE = 10 * MB;
    static constexpr int DEFAULT_RETENTION_DAYS = 7;

    Logger(const std::string& logPath, Severity minLogLevel, int maxFileSizeMB = DEFAULT_MAX_FILE_SIZE, int retentionDays = DEFAULT_RETENTION_DAYS)
        : m_logPath(logPath), m_minLogLevel(minLogLevel), m_maxFileSizeMB(maxFileSizeMB), m_retentionDays(retentionDays), m_file(""), m_mutex() {
        rotateIfNeeded();
    }

    void log(Severity severity, const char* format, ...) {
        if (severity >= m_minLogLevel) {
            std::string timestamp = getTimestamp();
            va_list args;
            va_start(args, format);
            size_t len = snprintf(nullptr, 0, format, args) + timestamp.size() + 1;
            std::vector<char> buf(len);
            vsnprintf(&buf[0], buf.size(), format, args);
            std::strcpy(&buf[timestamp.size()], timestamp.c_str());
            m_mutex.lock();
            m_file << buf << std::endl;
            m_mutex.unlock();
        }
    }

private:
    void rotateIfNeeded() {
        struct stat fileStat;
        if (stat(m_logPath.c_str(), &fileStat) == -1) return;
        if (fileStat.st_size > m_maxFileSizeMB * MB || daysSinceLastModification(fileStat) > m_retentionDays) {
            std::string newLogPath = rotateFileName(m_logPath);
            std::ofstream newFile(newLogPath);
            newFile << m_file.rdbuf();
            m_file.close();
            m_file.open(newLogPath, std::ios_base::app | std::ios_base::out);
        }
    }

    std::string getTimestamp() {
        char buf[32];
        time_t now = time(nullptr);
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
        return buf;
    }

    std::string rotateFileName(const std::string& baseName) {
        size_t dotPos = baseName.find_last_of('.');
        if (dotPos == std::string::npos) throw std::runtime_error("Invalid log file name");
        std::string extension = baseName.substr(dotPos);
        std::string newBaseName = baseName.substr(0, dotPos);
        int rotationCount = std::stoi(newBaseName.substr(newBaseName.find_last_of('_') + 1));
        ++rotationCount;
        newBaseName = baseName.substr(0, baseName.find_last_of('.'));
        newBaseName += "_" + std::to_string(rotationCount) + extension;
        return newBaseName;
    }

    int daysSinceLastModification(const struct stat& fileStat) {
        time_t now = time(nullptr);
        return static_cast<int>(now - fileStat.st_mtime);
    }

    std::string m_logPath;
    Severity m_minLogLevel;
    int m_maxFileSizeMB;
    int m_retentionDays;
    std::ofstream m_file;
    std::mutex m_mutex;
};
```

This code creates a `Logger` class that supports logging with different severity levels, dynamic log file rotation based on size and date, and concurrent access from multiple threads using a mutex. The logging mechanism can be configured with a minimum log level, maximum file size in megabytes, retention period in days, and the log path.

The `Logger` class handles rotating files when necessary and appends timestamps to each log entry. It uses `snprintf` and `va_start/va_end` for efficient message formatting. However, it does not address some of the more complex requirements such as integration with external logging services or optimizations for systems with limited resources.']

[" Here's a simplified example of how you might structure this logging system in C using pthreads for concurrency, `snprintf` for formatting, and a custom log queue to manage asynchronous logging. This implementation does not cover all the features requested but serves as a starting point.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { DEBUG, INFO, WARNING, ERROR, CRITICAL } log_level;

struct log_message {
    log_level level;
    char tag[32];
    char message[4096];
};

struct log_queue {
    struct log_message* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
};

void log(struct log_queue* queue, log_level level, const char* tag, const char* format, ...) {
    va_list args;
    struct log_message msg;

    va_start(args, format);
    vsnprintf(msg.message, sizeof(msg.message), format, args);
    va_end(args);

    msg.level = level;
    strncpy(msg.tag, tag, sizeof(msg.tag));

    pthread_mutex_lock(&queue->lock);

    while (queue->head - queue->tail == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    queue->buffer[queue->head] = msg;
    queue->head = (queue->head + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_empty);

    pthread_mutex_unlock(&queue->lock);
}

void log_worker(struct log_queue* queue) {
    while (true) {
        pthread_mutex_lock(&queue->lock);

        while (queue->head == queue->tail) {
            pthread_cond_wait(&queue->not_empty, &queue->lock);
        }

        struct log_message msg = queue->buffer[queue->tail];
        queue->tail = (queue->tail + 1) % queue->capacity;
        pthread_cond_signal(&queue->not_full);
        pthread_mutex_unlock(&queue->lock);

        // Handle log message here, e.g., write to file or send to external service
    }
}
```

This code defines a `log_message` struct for holding the log data and a `log_queue` struct for managing asynchronous logging. The `log()` function is used to add messages to the queue, while `log_worker()` processes them.

To handle dynamic configuration changes at runtime, you could implement a signal handler that modifies the log level or other settings and notifies the log worker thread(s) to reevaluate their behavior.

For real-time filtering based on contextual tags, you could add a tag comparison step in the `log()` function before adding messages to the queue.

To support horizontal scaling, you can create multiple worker threads and manage them accordingly. For handling memory allocation/deallocation under heavy load, consider using a custom allocator or memory pooling strategy.

For logging rotation, archiving old log files, and periodic compression, you could implement additional functions that work alongside the log queue and worker thread(s).

To prioritize certain types of logs, you can modify the worker thread's behavior based on the log level. For example, it could process critical logs more quickly than debug logs.

Lastly, to ensure modularity, consider organizing your code into separate files or modules for easier maintenance and extension."]

