class MemoryManager {
public:
    MemoryManager(size_t offsetSize, size_t keySize, size_t identifierSize) {
        if (offsets_.capacity() + keys_.capacity() + identifiers_.capacity() + records_.capacity() > MAX_MEMORY) {
            throw std::system_error(errno, std::generic_category(), "Memory limit exceeded");
        }

        offsets_.reserve(RECORD_COUNT);
        keys_.reserve(RECORD_COUNT);
        identifiers_.reserve(RECORD_COUNT);
        records_.reserve(RECORD_COUNT);
    }

    void allocate() {
        for (size_t i = 0; i < RECORD_COUNT; ++i) {
            records_[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        }
        std::random_device rd;
        std::mt19937 gen(rd());
        std::shuffle(std::begin(records_), std::end(records_), gen); // Seed random number generator uniquely for each instance
    }

    void* allocateDataStructures() {
