        offsets_.resize(RECORD_COUNT);
        keys_.resize(RECORD_COUNT);
        identifiers_.resize(RECORD_COUNT);
        std::fill(data.get(), data.get() + offsets_.capacity(), 0); // Zero out memory for efficient deallocation
        return data.release();
    }

    void deallocate(size_t start, size_t count) {
        auto data = static_cast<char*>(allocatedData_);
        std::fill_n(data + offsets_.size() + keys_.size() + identifiers_.size(), records_.size() - start * RECORD_COUNT - count * RECORD_COUNT, 0);
    }

    Record& getRecord(size_t index) {
        if (index >= RECORD_COUNT) {
            static const Record sentinel; // Sentinel value for out-of-bounds access
            return sentinel;
        }
        auto offset = offsets_[index];
        return *reinterpret_cast<Record*>(allocatedData_ + offset);
    }

    void logEvent(const char* event, size_t size) {
        if (logBuffer_.size() + size > LOG_BUFFER_THRESHOLD) {
            compressLog();
        }
        logBuffer_.append(event, size);
    }

private:
    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<unsigned short> identifiers_;
    std::vector<Record> records_;
    std::unique_ptr<char[]> allocatedData_;
    std::string logBuffer_;
    static constexpr size_t LOG_BUFFER_THRESHOLD = 1024 * 1024; // Log buffer threshold (1MB)

    void compressLog() {
        uLongf totalIn = logBuffer_.size();
        uLongf totalOut = totalIn;
        char* out = new char[totalOut];
        auto result = deflateInit(&compress, Z_DEFAULT_COMPRESSION);
        if (result != Z_OK) {
            throw std::system_error(errno, std::generic_category(), "Compression failed");
        }
        uLongf totalInFiltered = totalIn + 1024; // Add some extra space for filtering
        auto in = new char[totalInFiltered];
        auto outIndex = 0;
        std::copy(logBuffer_.begin(), logBuffer_.end(), in);
        uLongf totalOutFiltered = deflate(&compress, Z_FINISH, in, totalInFiltered, nullptr, out + outIndex, totalOut - outIndex);
        if (compress.total_out != totalOutFiltered) {
            throw std::system_error(errno, std::generic_category(), "Compression failed");
        }
        delete[] in;
        deflateEnd(&compress);
        logBuffer_.assign(out, out + totalOutFiltered);
        delete[] out;
    }
};
```

