#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned long capacity;
    unsigned long size;
    record** table;
} hash_table;

void rehash(hash_table* ht) {
    unsigned long new_capacity = ht->capacity * 2;
    record** new_table = calloc(new_capacity, sizeof(record*));
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        if (ht->table[i]) {
            unsigned long hash = hash_function(ht->table[i]->key, ht->table[i]->key_len);
            unsigned long index = hash % new_capacity;
            new_table[index] = ht->table[i];
        }
    }
    free(ht->table);
    ht->table = new_table;
    ht->capacity = new_capacity;
}

unsigned long hash_function(const char* key, size_t len) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    return hash % ht->capacity;
}
```

