#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int load_resource_bundle(const char* filename, record** records, size_t* num_records) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    *records = calloc(file_size, sizeof(record));
    if (!*records) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < file_size; ++i) {
        char line[256];
        fgets(line, sizeof(line), file);
        size_t len = strlen(line);
        if (len > 1 && line[len - 1] == '\n') line[len - 1] = '\0';

        sscanf(line, "%d %255s", &(*records)[i].value, (*records)[i].key);
        (*records)[i].key_len = strlen((*records)[i].key);
    }

    *num_records = file_size;
    fclose(file);
    return 0;
}
