    char* value;
} Record;

// Custom hash function
unsigned long hash(const unsigned char *str, size_t len) {
    unsigned long h = 5381;
    for (size_t i = 0; i < len; ++i)
        h = ((h << 5) + h) + str[i]; /* hash * 33 + c */
    return h;
}

// Custom hash table with dynamic resizing
typedef struct HashTable {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

void init_hash_table(HashTable* table, size_t initial_capacity) {
    table->records = calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
}

void resize_hash_table(HashTable* table) {
    Record** new_records = calloc((table->capacity * 2), sizeof(Record*));
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i]) {
            unsigned long index = hash(table->records[i]->value, strlen(table->records[i]->value)) % (table->capacity * 2);
            Record* record = table->records[i];
            table->records[i] = NULL; // free in deallocate_hash_table()
            new_records[index] = record;
        }
    }
    free(table->records);
    table->records = new_records;
    table->capacity *= 2;
}

void add_record(HashTable* table, Record* record) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(record->value, strlen(record->value)) % table->capacity;
    while (table->records[index]) ++index; // linear probing
    table->records[index] = record;
    if (++table->count >= table->capacity) resize_hash_table(table);
    pthread_mutex_unlock(&table->lock);
}

Record* get_record(HashTable* table, unsigned long index) {
    pthread_mutex_lock(&table->lock);
    Record** record = &table->records[index % table->capacity];
    if (*record) pthread_mutex_unlock(&table->lock);
    else {
        while ((*record = table->records[(index + 1) % table->capacity])) index++;
        pthread_mutex_unlock(&table->lock);
    }
    return *record;
}

void deallocate_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i]) free(table->records[i]->value);
        free(table->records[i]);
    }
    free(table->records);
    pthread_mutex_destroy(&table->lock);
}

// Function to manage dynamic memory allocation and initialization for multiple complex data structures
void* manage_memory(void* arg) {
    size_t offset_size = 1024 * 64; // adjust as needed
    size_t key_size = 1024; // adjust as needed
    size_t record_size = sizeof(Record);

    long* offsets = malloc(offset_size);
    int* keys = calloc(key_size, sizeof(int));
    Record* records = malloc(key_size * record_size);

    // Initialize records with random integers and strings
    srand(time(NULL));
    for (size_t i = 0; i < key_size; ++i) {
        records[i].key = rand() % 100 + 1;
        size_t str_len = records[i].key > 5 ? records[i].key : 5;
        records[i].value = calloc(str_len, sizeof(char));
        snprintf(records[i].value, str_len, "String %zu", i);
    }

    // Create a hash table and add records to it
    HashTable table;
    init_hash_table(&table, 16);
    for (size_t i = 0; i < key_size; ++i) add_record(&table, &records[i]);

    // Deallocate memory when done
    free(offsets);
    free(keys);
    deallocate_hash_table(&table);

    return NULL;
}
```

This code includes a custom hash table with dynamic resizing, as well as functions to manage the dynamic allocation and initialization of multiple complex data structures. The `manage_memory()` function demonstrates how these components can be used together.']

