[' Due to the complexity of the task, I will provide you with an outline for a custom data structure (`my_list`) and its functions in C, using the doubly-linked list approach for efficient memory usage and dynamic growth. This implementation uses pthreads for thread safety, malloc/free for memory management, and assumes the use of an external memory management library (not specified) for automatic deallocation of unused memory blocks.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct item {
    char buffer[256]; // Adjust the size as needed
    size_t length;
    void* payload;
    struct item* prev;
    struct item* next;
} Item;

typedef struct my_list {
    Item* head;
    Item* tail;
    size_t size;
    pthread_mutex_t lock;
} MyList;

MyList* create_my_list() {
    MyList* list = malloc(sizeof(MyList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void append_item(MyList* list, const char* buffer, size_t length, void* payload) {
    Item* new_item = malloc(sizeof(Item));
    if (!new_item) return;

    new_item->length = length;
    memcpy(new_item->buffer, buffer, length);
    new_item->payload = payload;
    new_item->prev = NULL;
    new_item->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = new_item;
        list->tail = new_item;
    } else {
        list->tail->next = new_item;
        new_item->prev = list->tail;
        list->tail = new_item;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void* get_payload(const MyList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    Item* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        if (!current) break;
        current = current->next;
    }

    void* result = NULL;
    if (current) result = current->payload;

    pthread_mutex_unlock(&list->lock);
    return result;
}

void compact(MyList* list) {
    // Implement a compacting algorithm here
}

void clear_my_list(MyList* list) {
    pthread_mutex_lock(&list->lock);

    Item* current = list->head;
    while (current) {
        Item* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}
```

