        std::iota(std::begin(keys_), std::end(keys_), 0);
    }

    void populate(int min, int max) {
        std::unordered_map<int, size_t> usedKeys;
        for (size_t i = 0; i < records_.capacity(); ++i) {
            int key = keys_[i];
            while (usedKeys.count(key)) key = rand() % (max - min + 1) + min;
            usedKeys[key] = i;
            Record& record = records_[i];
            record.value = key;
            record.field = static_cast<char>(rand() % 256);
        }
