Here's an example of how the insert function might look:

```c
int hash_table_insert(HashTable* table, const Item* item) {
    size_t index = table->hash_function(item->key) % table->size;

    // Lock the table to prevent concurrent modifications
    pthread_mutex_lock(&table->lock);

    // Check if the key already exists and increment its counter
    if (table->table[index]) {
        table->table[index]->counter++;
        pthread_mutex_unlock(&table->lock);
        return 1; // Duplicate key found
    }

    // Allocate memory for the new item and store it in the table
    Item* new_item = malloc(sizeof(Item));
    if (!new_item) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failed
    }

    memcpy(new_item, item, sizeof(Item));
    new_item->counter = 1;
    table->table[index] = new_item;

    pthread_mutex_unlock(&table->lock);
    return 0; // Successfully inserted the item
}
```"]

