    FILE *file = fopen(filename, "r");
    if (!file)
        return 0;

    long max_offset = 0;
    int max_key = 0;

    while (1) {
        size_t offset_index = max_offset;
        int key_index = max_key;
        int value;

        if (fscanf(file, "offset:%ld\n", &offset_index) != 1 ||
            fscanf(file, "key:%d\n", &key_index) != 1 ||
            fscanf(file, "value:%d\n", &value) != 1 ||
            feof(file)) {
            break;
        }

        if (offset_index > max_offset)
            max_offset = offset_index;
        if (key_index > max_key)
            max_key = key_index;
    }

    fclose(file);

    *array_size = max_offset + 1;
    offsets = realloc(offsets, sizeof(long) * (*array_size));
    if (!offsets)
        handle_error("Failed to allocate memory for offsets");

    keys = realloc(keys, sizeof(int) * (max_key + 1));
    if (!keys)
        handle_error("Failed to allocate memory for keys");

    records = malloc(sizeof(Record) * (*array_size));
    if (!records)
        handle_error("Failed to allocate memory for records");

    file = fopen(filename, "r");
    if (!file)
        handle_error("Failed to reopen configuration file");

    for (long i = 0; i < *array_size; ++i) {
        if (fscanf(file, "offset:%ld\n", &offsets[i]) != 1 ||
            fscanf(file, "key:%d\n", &keys[i]) != 1 ||
            fscanf(file, "value:%d\n", &records[i].value) != 1 ||
            feof(file)) {
            handle_error("Failed to read configuration file");
        }
    }

    fclose(file);
    return 1;
}

void free_memory(long *offsets, int *keys, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int main() {
    srand(time(NULL));

    long offsets = NULL;
    int keys = NULL;
    Record *records = NULL;

    if (!read_config("config.txt", &offsets, &keys, &array_size)) {
        free_memory(offsets, keys, records);
        return EXIT_FAILURE;
    }

    // Your code to process the arrays goes here

    free_memory(offsets, keys, records);
    return EXIT_SUCCESS;
}
```

