  fs.writeSync(tempFile, pemContent);
  fs.closeSync(tempFile);

  // Read the generated PEM file and return its content as a promise
  const pemFileBuffer = await readFileToBuffer(`${themeCacheDir}/temp-pem.txt`);
  fs.unlinkSync(`${themeCacheDir}/temp-pem.txt`);

  // Handle theme caching, bitmap recycling, and other integration issues here
  // ...

  return pemFileBuffer;
}

function readStreamToBuffer(readableStream) {
  return new Promise((resolve, reject) => {
    const buffer = Buffer.alloc(0);
    let isPaused = true;

    readableStream.on('data', (chunk) => {
      if (isPaused) return;
      buffer = Buffer.concat([buffer, chunk]);
    });

    readableStream.on('end', () => resolve(buffer));
    readableStream.on('error', reject);

    function pause() {
      isPaused = true;
      readableStream.pause();
    }

    function resume() {
      isPaused = false;
      readableStream.resume();
    }

    // Add pause and resume functions here for efficient resource management
    // ...
  });
}

function readFileToBuffer(filePath) {
  return new Promise((resolve, reject) => {
    const file = fs.readFileSync(filePath);
    resolve(file);
  });
}
```

