void populate_data(float *data, int rows, int cols) {
    for (int i = 0; i < rows * cols; ++i) data[i] = rand() % 101;
}

Node* build_tree(Node *root, int id, float *data, int start, int end) {
    if (!data || id < start || id > end) return root;

    Node *new_node = create_node(id);
    new_node->data = realloc(new_node->data, sizeof(float) * (end - start + 1));
    memcpy(new_node->data, data + start, sizeof(float) * (end - start + 1));

    if (start < end) {
        int mid = (start + end) / 2;
        new_node->left = build_tree(new_node->left, id, data, start, mid);
        new_node->right = build_tree(new_node->right, id, data, mid + 1, end);
    }

    return new_node;
}

