Graph* create_graph(int capacity) {
    // Allocate memory for the graph and its components
    Graph* graph = mmap(NULL, sizeof(Graph), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (graph == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    graph->num_vertices = 0;
    graph->num_edges = 0;

    // Allocate memory for vertices and edges arrays
    graph->vertices = calloc(capacity, sizeof(Vertex));
    if (!graph->vertices) {
        perror("calloc failed");
        munmap(graph, sizeof(Graph));
        exit(EXIT_FAILURE);
    }

    graph->edges = calloc(capacity, sizeof(Edge*));
    if (!graph->edges) {
        free(graph->vertices);
        perror("calloc failed");
        munmap(graph, sizeof(Graph));
        exit(EXIT_FAILURE);
