[' Here's a simplified version of the C program you described. This code doesn't include all the features you mentioned but focuses on the core functionality of allocating memory for arrays, initializing them, and setting values using cryptographic hashes. I've also included a basic implementation for parsing command-line arguments.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <openssl/sha.h>

typedef struct {
    int value;
    long offset;
} record;

typedef struct {
    size_t num_records;
    size_t num_offsets;
    size_t num_keys;
    record* records;
    long* offsets;
    int* keys;
} metadata;

metadata* init_memory(size_t num_records) {
    metadata* meta = (metadata*)malloc(sizeof(metadata));
    meta->num_records = num_records;
    meta->num_offsets = num_records;
    meta->num_keys = num_records;

    meta->records = (record*)calloc(num_records, sizeof(record));
    if (!meta->records) {
        free(meta);
        return NULL;
    }

    meta->offsets = (long*)calloc(num_offsets, sizeof(long));
    if (!meta->offsets) {
        free(meta->records);
        free(meta);
        return NULL;
    }

    meta->keys = (int*)calloc(num_keys, sizeof(int));
    if (!meta->keys) {
        free(meta->offsets);
        free(meta->records);
        free(meta);
        return NULL;
    }

    return meta;
}

void generate_offsets(metadata* meta, const char* key_prefix) {
    for (size_t i = 0; i < meta->num_keys; ++i) {
        char key[128];
        snprintf(key, sizeof(key), "%s%ld", key_prefix, i);
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, key, strlen(key));
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Final(hash, &ctx);
