[" Here's a simplified C++ implementation using the Standard Template Library (STL) unordered_map for fast key lookups, a custom allocator for memory management, and mutexes for synchronization. This example is not thread-safe in all scenarios and may require further optimization for production use.

```cpp
#include <iostream>
#include <mutex>
#include <unordered_map>
#include <memory>

namespace record_manager {

class Record {
public:
    explicit Record(int key, long offset) : key_(key), offset_(offset) {}

    int getKey() const { return key_; }
    long getOffset() const { return offset_; }

private:
    int key_;
    long offset_;
};

class Allocator : public std::allocator<Record> {
public:
    using value_type = Record;
    using pointer = value_type*;
    using reference = value_type&;

    pointer allocate(std::size_t n, std::allocator<void>::const_pointer hint) {
        if (free_list_.empty()) {
            return std::allocator<Record>::allocate(n);
        }
        auto result = free_list_.front();
        free_list_.pop_front();
        return result;
    }

    void deallocate(pointer p, std::size_t n) {
        if (!n)
            return;
        free_list_.splice(free_list_.end(), std::make_heap(p, p + n));
        std::sort_heap(p, p + n, [](const Record& a, const Record& b) {
            return a.getKey() < b.getKey();
        });
    }

private:
    std::vector<Record> free_list_;
};

class Collection {
public:
    explicit Collection(std::size_t initial_capacity = 1024) : data_(initial_capacity, Allocator()), mutex_() {}
    ~Collection() { clear(); }

    void add(const Record& record) {
        std::unique_lock<std::mutex> lock(mutex_);
        data_[record.getKey()] = record;
    }

    bool remove(int key) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = data_.find(key);
        if (it == data_.end())
            return false;
        data_.erase(it);
        return true;
    }

    const Record* find(int key) const {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = data_.find(key);
        return it != data_.end() ? &(*it) : nullptr;
    }

    void clear() {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto& record : data_) {
            free_list_.push_back(record);
        }
        data_.clear();
    }

private:
    std::unordered_map<int, Record, std::hash<int>, std::equal_to<int>, Allocator> data_;
    std::vector<Record> free_list_;
    std::mutex mutex_;
};

}  // namespace record_manager
```

This code defines a `record_manager` namespace containing a `Record`, `Allocator`, and `Collection` class. The `Record` class represents the record structure, while the `Allocator` class manages memory allocation and deallocation for the records. The `Collection` class uses an unordered_map to store the records and provides methods for adding, removing, and finding records by key. A mutex is used to synchronize access to the collection from multiple threads."]

