    int value;
};

constexpr size_t DEFAULT_CAPACITY = 1024;
constexpr size_t MIN_CACHE_SIZE = 64;
constexpr size_t MAX_CACHE_SIZE = 4096;
```

3. Implement the MemoryManager class:

```cpp
class MemoryManager {
public:
    MemoryManager() : offsets_(DEFAULT_CAPACITY), keys_(DEFAULT_CAPACITY), records_(DEFAULT_CAPACITY) {}

    // Allocate and initialize memory for offsets, keys, and records arrays.
    void init() {
        std::fill(offsets_.begin(), offsets_.end(), 0);
        std::fill(keys_.begin(), keys_.end(), 0);
        std::generate(records_.begin(), records_.end(), []() -> Record { return Record{}; });
    }

    // Allocate memory for a new record and set its value to a random integer within the specified range.
    Record* allocate_record(int min, int max) {
        if (records_.size() == offsets_.size()) resize();
        auto index = offsets_.back();
        offsets_.push_back(offsets_.size());
        keys_[index] = rand() % (max - min + 1) + min;
        new (&records_[index]) Record{}; // Placement new to ensure proper initialization.
        return &records_[index];
    }

    // Deallocate a specific record by index, handling edge cases and minimizing memory fragmentation.
    void deallocate_record(size_t index) {
        if (index >= offsets_.size()) throw std::out_of_range("Index out of range");
        auto it = records_.begin() + offsets_[index];
        offsets_[index] = offsets_.back();
        offsets_.pop_back();
        it->~Record(); // Virtual destructor to call any necessary cleanup.
    }

    // Retrieve the record at a specific index, with caching support.
    Record* get_record(size_t index) {
        auto it = cache_.find(index);
        if (it != cache_.end()) return &it->second;
        if (cache_.size() >= MAX_CACHE_SIZE) evict_least_recently_used();
        it = records_.begin() + offsets_[index];
        cache_[index] = it;
        return &it->value;
    }

private:
    void resize() {
        auto new_capacity = std::max(offsets_.size() * 2, DEFAULT_CAPACITY);
        auto new_records = std::vector<Record>(new_capacity);
        std::copy(records_.begin(), records_.end(), new_records.begin());
        records_.swap(new_records);
    }

    void evict_least_recently_used() {
        auto it = cache_.rbegin();
        auto end = cache_.rend();
        if (it != end) cache_.erase(it->first);
    }

    std::vector<size_t> offsets_;
    std::vector<int> keys_;
    std::vector<Record> records_;
    std::unordered_map<size_t, Record*> cache_;
    std::mutex mtx; // For thread safety.
};
```

