std::vector<Record> initializeRecords(int num_records) {
    std::vector<Record> records(num_records);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 127);

    std::mutex mtx;
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = i + 1;
        records[i].key = i + 1;
        auto randStr = std::string(32, static_cast<char>(dis(gen)));
        std::unique_lock<std::mutex> lock(mtx);
        records[i].description.swap(randStr);
    }

    return records;
}

void generateDescriptionsAsync(std::vector<Record>& records, int start, int end) {
    for (size_t i = start; i < end; ++i) {
        auto& record = records[i];
        std::thread([record]() {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 127);
            auto randStr = std::string(32, static_cast<char>(dis(gen)));
            record.description.swap(randStr);
        }).detach();
    }
}

void validateAndUpdateDescriptions(std::vector<Record>& records) {
