    if (num_records > 1000) {
        int chunks = num_records / 1000 + (num_records % 1000 > 0);
        for (int i = 0; i < chunks; ++i) {
            generateDescriptionsAsync(records, i * 1000, std::min((i + 1) * 1000, num_records));
        }
    }

    validateAndUpdateDescriptions(records);

    return records;
}
