std::vector<int> state_list;
std::mutex mtx;

void generate_record(int id, int key, long offset) {
    Record record{key};
    record.value = std::rand() % 100 + 1; // Random number within range 1-100
    records[id] = record;
    offsets[id] = offset;
    keys[id] = key;
}

void generate_state_list(const FSA& fsa, int last_state, long total_size) {
    state_list.resize(last_state + 1);
    std::fill(state_list.begin(), state_list.end(), -1);

    std::vector<std::future<void>> futures;

    for (int i = 0; i <= last_state; ++i) {
        if (fsa.transitions.find(i) != fsa.transitions.end()) {
            auto future = std::async(std::launch::async, [this, i]() mutable {
                mtx.lock();
                for (const auto& transition : fsa.transitions[i]) {
                    if (state_list[transition] == -1) {
                        state_list[transition] = offsets.size();
                        generate_record(offsets.size(), transition, offsets[i]);
                    }
                }
                mtx.unlock();
            });
            futures.push_back(std::move(future));
        }
    }

    for (auto& future : futures) {
        future.wait();
    }
}
```

This code creates a function `generate_state_list` that takes an FSA, the last state in the list, and the total size of the memory to allocate. It initializes the arrays for offsets, keys, and records, then populates the state_list using asynchronous processing to handle potential concurrent access gracefully.

