#include <new>
#include <LoggingLibrary/LoggingLibrary.h>

constexpr size_t GROWTH_FACTOR = 1.5;
constexpr int MIN_SIZE = 1024;
constexpr int MAX_CACHE_SIZE = 1024 * 64;

class DataStructuresManager {
public:
    struct Record {
        int value;
        Record() : value(rand() % 1000000) {}
    };

    class Factory {
    public:
        virtual std::unique_ptr<Record> create() = 0;
        virtual ~Factory() {}
    };

    struct Registry {
        std::unordered_map<int, Factory*> factories;

        void registerFactory(int id, Factory* factory) {
            factories[id] = factory;
        }
    };

    DataStructuresManager(Registry& registry, size_t offsetSize, size_t recordSize, int cacheSize)
        : offsets_(offsetSize), keys_(offsetSize), records_(recordSize), registry_(registry), cache_(), mutex_(), cacheSize_(cacheSize) {}

    ~DataStructuresManager() {
        deallocate();
    }

    void allocate() {
        if (offsets_.size() >= MIN_SIZE) return;

        auto newOffsetSize = offsets_.size() * GROWTH_FACTOR;
        auto newRecordSize = records_.size() * GROWTH_FACTOR;

        std::vector<long> newOffsets(newOffsetSize);
        std::vector<int> newKeys(newOffsetSize);
        std::vector<std::unique_ptr<Record>> newRecords(newRecordSize);

        std::copy(offsets_.begin(), offsets_.end(), newOffsets.begin());
        std::copy(keys_.begin(), keys_.end(), newKeys.begin());
        std::copy(records_.begin(), records_.end(), newRecords.begin());

        offsets_ = newOffsets;
        keys_ = newKeys;
        records_ = newRecords;
    }

    void deallocate() {
        for (auto& record : records_) {
            if (record) delete record.get();
        }
        records_.clear();

        offsets_.clear();
        keys_.clear();
    }

    long* getOffset(int index) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index < 0 || index >= static_cast<int>(offsets_.size())) {
            LoggingLibrary::logError("Invalid index");
            return nullptr;
        }
        return &offsets_[index];
    }

    int getKey(long offset) {
        for (size_t i = 0; i < offsets_.size(); ++i) {
            if (offsets_[i] == offset) {
                return keys_[i];
            }
        }
        LoggingLibrary::logError("Invalid offset");
        return -1;
    }

    std::unique_ptr<Record> getRecord(long offset) {
        auto it = cache_.find(offset);
        if (it != cache_.end()) {
            return it->second;
        }

        for (size_t i = 0; i < records_.size(); ++i) {
            if (offsets_[i] == offset) {
                auto record = std::move(records_[i]);
                cache_[offset] = std::move(record);
                return record;
            }
        }
        LoggingLibrary::logError("Invalid offset");
        return nullptr;
    }

    void putRecord(long offset, std::unique_ptr<Record> record) {
        cache_[offset] = std::move(record);
    }

    template <typename Iterator>
    void setKeysAndOffsets(Iterator keysBegin, Iterator keysEnd, Iterator offsetsBegin, Iterator offsetsEnd) {
        if (keysEnd - keysBegin != offsetsEnd - offsetsBegin) {
            LoggingLibrary::logError("Mismatched sizes for keys and offsets");
            return;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        deallocate();

        auto newSize = keysEnd - keysBegin;
        allocate();

        std::copy(keysBegin, keysEnd, keys_.begin());
        std::copy(offsetsBegin, offsetsEnd, offsets_.begin());
    }

    void registerFactory(int id, Factory* factory) {
        registry_.registerFactory(id, factory);
    }

    std::unique_ptr<Record> createRecord(int id) {
        auto it = registry_.factories.find(id);
        if (it == registry_.factories.end()) {
            LoggingLibrary::logError("Invalid factory ID");
            return nullptr;
        }
        return std::move(it->second->create());
    }

private:
    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::vector<std::unique_ptr<Record>> records_;
    Registry registry_;
    std::unordered_map<long, std::unique_ptr<Record>> cache_;
    std::mutex mutex_;
    int cacheSize_;
};
